        foreach (var (id, action) in BuildContextualTabCommands())
            ribbonExtraCommands[id] = action;
        // Home ▸ Styles ▸ Cell Styles gallery items: each built-in preset's display name is its canonical
        // ribbon menu id, so wire every one to apply that style to the selection.
        foreach (var stylePreset in Enum.GetValues<CellStylePreset>())
        {
            var preset = stylePreset;
            ribbonExtraCommands[CellStyleDiffPlanner.GetCellStylePresetDisplayName(preset)] =
                () => ApplyCellStylePreset(preset);
        }
        ribbonCallbacks = ribbonCallbacks with { ExtraCommands = ribbonExtraCommands };

        var (ribbon, refreshRibbonToggleStates, ribbonCommandRegistry) = FreeX.App.Avalonia.Ribbon.AvaloniaRibbonHost.Build(
            () => _session,
            RefreshShell,
            ribbonCallbacks,
            _ribbonContextSource);
        _refreshRibbonToggleStates = refreshRibbonToggleStates;
        _ribbonCommandRegistry = ribbonCommandRegistry;
        _ribbonControl = ribbon;
        ConfigureWorksheetRibbonFlyouts(ribbon);
        ribbon.Loaded += (_, _) => ConfigureWorksheetRibbonFlyouts(ribbon);

        var formulaBar = BuildToolbar();

        var statusBar = BuildStatusBar();
        var belowRibbonQatHost = CreateAvaloniaQuickAccessBelowRibbonHost();

        var sheetTabs = BuildSheetTabsChrome();
        var frame = SisterAppClientFrameBuilder.Build(new SisterAppClientFrameSpec(
            Ribbon: ribbon,
            WorkArea: BuildWorkbookWorkArea(),
            StatusBar: statusBar,
            BottomPanelsAboveStatus: [sheetTabs],
            TopPanelsBelowRibbon: [belowRibbonQatHost, formulaBar]));

        var root = new AvaloniaGrid();
        root.Children.Add(frame.Root);
        root.Children.Add(BuildBackstageOverlay());

        var windowFrame = SisterAppWindowFrameBuilder.Build(new SisterAppWindowFrameSpec(
            Window: this,
            Body: root,
            TitleBarBackground: TitleBarSurface,
            TitleBarForeground: StatusBarForeground));
        PopulateQuickAccessToolbar(windowFrame.QatHost, belowRibbonQatHost);
        return windowFrame.Root;
    }

    private void ConfigureWorksheetRibbonFlyouts(Control ribbon)
    {
        foreach (var button in EnumerateRibbonControls(ribbon).OfType<Button>())
        {
            AttachRibbonQuickAccessCustomization(button);
            switch (button.Tag as string)
            {
                case "Fill Color":
                    button.Flyout = CreateColorPaletteFlyout(ColorPaletteTarget.Fill, includeClearFill: true);
                    break;
                case "Font Color":
                    button.Flyout = CreateColorPaletteFlyout(ColorPaletteTarget.Font, includeClearFill: false);
                    break;
            }
        }
    }

    private static IEnumerable<Control> EnumerateRibbonControls(Control root)
    {
        yield return root;
        switch (root)
        {
            case ItemsControl itemsControl:
                foreach (var item in itemsControl.Items.OfType<Control>())
                    foreach (var descendant in EnumerateRibbonControls(item))
                        yield return descendant;
                break;
            case Panel panel:
                foreach (var child in panel.Children)
                    foreach (var descendant in EnumerateRibbonControls(child))
                        yield return descendant;
                break;
            case ContentControl { Content: Control content }:
                foreach (var descendant in EnumerateRibbonControls(content))
                    yield return descendant;
                break;
            case Decorator { Child: { } child }:
                foreach (var descendant in EnumerateRibbonControls(child))
                    yield return descendant;
                break;
        }
    }

    private Control BuildWorkbookWorkArea()
    {
        var workArea = new DockPanel { LastChildFill = true };
        var pivotFieldPane = BuildPivotFieldPaneChrome();
        DockPanel.SetDock(pivotFieldPane, Dock.Right);
        workArea.Children.Add(pivotFieldPane);
        var slicerTimelinePane = BuildSlicerTimelinePaneChrome();
        DockPanel.SetDock(slicerTimelinePane, Dock.Right);
        workArea.Children.Add(slicerTimelinePane);

        workArea.Children.Add(BuildWorksheetViewportChrome());

        return workArea;
    }

    private Control BuildWorksheetViewportChrome()
    {
        _sheetGridHost.Focusable = true;
        AutomationProperties.SetName(_sheetGridHost, "Worksheet");
        AutomationProperties.SetHelpText(_sheetGridHost, "Shows the active workbook sheet.");
        _sheetGridHost.PointerMoved += SheetGridHost_PointerMoved;
        _sheetGridHost.PointerExited += (_, _) => _sheetGridHost.Cursor = Cursor.Default;
        AttachSplitPanePointerHandlers();

        _sheetScrollViewer.HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled;
        _sheetScrollViewer.VerticalScrollBarVisibility = ScrollBarVisibility.Disabled;
        _sheetScrollViewer.Content = _sheetGridHost;
        _sheetScrollViewer.SizeChanged += SheetScrollViewer_SizeChanged;
        // Avalonia's ScrollViewer class handler can consume a vertical wheel before a bubbling
        // subscription sees it. Handle the worksheet wheel in the tunnel so split-pane wheels use
        // the shared workbook viewport before the ScrollViewer attempts its own offset update.
        _sheetScrollViewer.AddHandler(
            InputElement.PointerWheelChangedEvent,
            SheetScrollViewer_PointerWheelChanged,
            RoutingStrategies.Tunnel,
            handledEventsToo: true);

        _verticalWorksheetScrollBar.Orientation = Orientation.Vertical;
        _verticalWorksheetScrollBar.Width = 16;
        _verticalWorksheetScrollBar.AllowAutoHide = false;
        _verticalWorksheetScrollBar.ValueChanged += WorksheetScrollBar_ValueChanged;

        var chrome = new AvaloniaGrid
        {
            Background = Brushes.White,
            ColumnDefinitions =
            {
                new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) },
                new ColumnDefinition { Width = GridLength.Auto },
            },
            RowDefinitions =
            {
                new RowDefinition { Height = new GridLength(1, GridUnitType.Star) },
            },
        };

        AddGridChild(chrome, _sheetScrollViewer, 0, 0);
        AddGridChild(chrome, _verticalWorksheetScrollBar, 0, 1);

        return chrome;
    }

    private Control BuildSheetTabsChrome()
    {
