    private int FindActiveSheetTabIndex()
        => FindSheetTabIndex(_session.ActiveSheet.Id);

    private int FindSheetTabIndex(SheetId sheetId)
    {
        for (var index = 0; index < _session.SheetTabs.Count; index++)
        {
            if (_session.SheetTabs[index].Id == sheetId)
                return index;
        }

        return -1;
    }

    private Control BuildSheetTabs()
    {
        _sheetTabsBuildCount++;
        var panel = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 0,
            // Nudge the whole strip a few px right of the row-header edge so the first (active) tab's
            // left vertical border clears the header column and is fully visible, matching Windows
            // (the tab strip starts just right of the header edge rather than flush against it, which
            // was clipping the active tab's rounded left corner on Linux).
            Margin = new Thickness(SheetTabStripLeadingInset, 0, 0, 0),
        };

        foreach (var tab in _session.SheetTabs)
        {
            var isGroupedTab = tab.IsGrouped && _session.IsWorkbookGrouped;
            var content = new AvaloniaGrid
            {
                RowDefinitions =
                {
                    new RowDefinition { Height = new GridLength(1, GridUnitType.Star) },
                    new RowDefinition { Height = new GridLength(2) },
                },
            };
            var label = new TextBlock
            {
                Text = tab.Name,
                FontSize = 13,
                FontWeight = tab.IsActive || isGroupedTab ? FontWeight.SemiBold : FontWeight.Normal,
                Foreground = tab.IsActive ? PrimaryInk : HeaderForeground,
                TextTrimming = TextTrimming.CharacterEllipsis,
                TextAlignment = TextAlignment.Center,
                HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
            };
            var tabColorRule = new Border
            {
                Background = tab.TabColor is { } tabColor ? Brush(tabColor) : Brushes.Transparent,
                IsHitTestVisible = false,
            };
            AvaloniaGrid.SetRow(label, 0);
            AvaloniaGrid.SetRow(tabColorRule, 1);
            content.Children.Add(label);
            content.Children.Add(tabColorRule);

            var button = new Button
            {
                MinWidth = 64,
                MaxWidth = 168,
                MinHeight = 27,
                Height = 27,
                Focusable = true,
                Padding = new Thickness(8, 0, 8, 0),
                Background = tab.IsActive
                    ? Brushes.White
                    : isGroupedTab
                        ? Brush(236, 246, 255)
                        : Brushes.Transparent,
                BorderBrush = Brush(213, 217, 223),
                BorderThickness = tab.IsActive ? new Thickness(1, 1, 1, 0) : new Thickness(0, 0, 1, 0),
                Content = content,
                Tag = tab.Id,
                Margin = tab.IsActive ? new Thickness(0, -1, 0, 0) : new Thickness(0),
            };
            button.ContextMenu = CreateSheetTabContextMenu(tab);
            button.AddHandler(
                InputElement.PointerPressedEvent,
                (_, args) => BeginSheetTabPointer(tab.Id, args),
                RoutingStrategies.Tunnel,
                handledEventsToo: true);
            button.KeyDown += (_, args) => HandleSheetTabKeyDown(tab.Id, button, args);
            button.Click += (_, _) => CompleteSheetTabClick(tab.Id);
            AutomationProperties.SetName(button, tab.Name);
            AutomationProperties.SetHelpText(button, SheetTabContextHelpText);
            panel.Children.Add(button);
        }

        DetachNewSheetButtonFromParent();
        panel.Children.Add(_newSheetButton);
        return panel;
    }

    private void DetachNewSheetButtonFromParent()
    {
        if (_newSheetButton.Parent is Panel parent)
            parent.Children.Remove(_newSheetButton);
    }

    private ContextMenu CreateSheetTabContextMenu(WorkbookSheetTab tab)
    {
        var isIdle = !_isOpening && !_isSaving;
        var sheetTabIndex = FindSheetTabIndex(tab.Id);
        var menu = new ContextMenu
        {
            ItemsSource = CreateSheetTabContextMenuItems(tab, isIdle, sheetTabIndex).ToArray(),
        };
        return menu;
    }

    private IEnumerable<Control> CreateSheetTabContextMenuItems(WorkbookSheetTab tab, bool isIdle, int sheetTabIndex)
    {
        yield return CreateSheetTabContextMenuItem(tab, "Rename...", async () => await RenameActiveSheetAsync(), isIdle);
        yield return CreateSheetTabContextMenuItem(tab, "Insert Sheet", AddNewSheet, isIdle);
        yield return CreateSheetTabContextMenuItem(tab, "Duplicate", DuplicateActiveSheet, isIdle);
        yield return CreateSheetTabContextMenuItem(tab, UiText.Get("MoveCopySheet_MenuItem"), ShowMoveOrCopySheetDialog, isIdle);
        yield return CreateSheetTabContextMenuItem(tab, "Delete Sheet", DeleteActiveSheet, isIdle);
        yield return new Separator();
        yield return CreateSheetTabContextMenuItem(tab, "Hide", HideActiveSheet, isIdle && _session.SheetTabs.Count > 1);
        yield return CreateSheetTabContextMenuItem(tab, "Unhide...", async () => await UnhideSheetAsync(), isIdle && _session.HiddenSheets.Count > 0);
        yield return CreateSheetTabColorContextMenuItem(tab, isIdle);
        yield return new Separator();
        yield return CreateSheetTabContextMenuItem(tab, UiText.Get("OutlineSettings_MenuItem"), ShowOutlineSettingsDialog, isIdle);
        yield return new Separator();
        yield return CreateSheetTabContextMenuItem(tab, "Select All Sheets", SelectAllVisibleSheets, isIdle && _session.SheetTabs.Count > 1);
        yield return CreateSheetTabContextMenuItem(tab, "Ungroup Sheets", UngroupSheets, isIdle && _session.IsWorkbookGrouped);
        yield return new Separator();
        yield return CreateSheetTabContextMenuItem(tab, "Move Left", MoveActiveSheetLeft, isIdle && sheetTabIndex > 0);
        yield return CreateSheetTabContextMenuItem(
            tab,
            "Move Right",
            MoveActiveSheetRight,
            isIdle && sheetTabIndex >= 0 && sheetTabIndex < _session.SheetTabs.Count - 1);
    }

    private MenuItem CreateSheetTabContextMenuItem(WorkbookSheetTab tab, string header, Action action, bool isEnabled)
    {
        var menuItem = new MenuItem
        {
            Header = header,
            IsEnabled = isEnabled,
        };
        menuItem.Click += (_, _) =>
        {
            if (!SelectSheetForContextCommand(tab.Id))
                return;

            action();
        };
        return menuItem;
    }

    private MenuItem CreateSheetTabContextMenuItem(WorkbookSheetTab tab, string header, Func<Task> action, bool isEnabled)
    {
        var menuItem = new MenuItem
        {
            Header = header,
            IsEnabled = isEnabled,
        };
        menuItem.Click += async (_, _) =>
        {
            if (!SelectSheetForContextCommand(tab.Id))
                return;

            await action();
        };
        return menuItem;
    }

    private MenuItem CreateSheetTabColorContextMenuItem(WorkbookSheetTab tab, bool isEnabled)
    {
        var menuItem = new MenuItem
        {
            Header = "Tab Color",
            IsEnabled = isEnabled,
            ItemsSource = CreateSheetTabColorContextMenuItems(tab).ToArray(),
        };
        return menuItem;
    }

    private IEnumerable<MenuItem> CreateSheetTabColorContextMenuItems(WorkbookSheetTab tab)
    {
        var clearColorItem = new MenuItem { Header = "No Color" };
        clearColorItem.Click += (_, _) =>
        {
            if (SelectSheetForContextCommand(tab.Id))
                ApplyActiveSheetTabColor(null);
        };
        yield return clearColorItem;

        foreach (var swatch in CellColorPalettePlanner.BuildDefaultSwatches(_session.Workbook.Theme))
        {
            var menuItem = new MenuItem
            {
                Header = swatch.Hex,
                Icon = CreateColorSwatchIcon(swatch.Color),
            };
            menuItem.Click += (_, _) =>
            {
                if (SelectSheetForContextCommand(tab.Id))
                    ApplyActiveSheetTabColor(swatch.Color);
            };
            yield return menuItem;
        }
    }

    private Control BuildSheetGrid()
    {
        _sheetGridBuildCount++;
        _formulaReferenceGridOverlay = null;
        _cellAffordanceOverlay = null;
        _formulaReferenceGridHighlightVisuals.Clear();
        _activeDataValidationDropdown = null;
        _activeCellBorder = null;
        _activeSelectionOutlineVisual = null;
        _autofillHandleVisual = null;
        var viewport = _session.Viewport;
        var showHeadings = _session.IsShowingHeadings;
        var zoomFactor = GetActiveZoomFactor();
        var headerOffset = showHeadings ? 1 : 0;

        // Window ▸ Split (viewport.SplitPanes, distinct from Freeze Panes) pins extra rows/columns
        // ahead of the main scrollable pane, exactly like BuildFrozenAwareRowMetrics/ColMetrics
        // already pin frozen rows/columns into RowMetrics/ColMetrics themselves. Freeze panes need
        // no special handling here because they're baked into RowMetrics/ColMetrics upstream; split
        // panes are NOT (they're kept in the separate SplitPanes.TopRows/LeftColumns/Cells lists so
        // each pane can eventually scroll independently), so this prepends them into the row/column
        // sequence actually walked below — producing all four split quadrants (TopLeft/TopRight/
        // BottomLeft/BottomRight) as one continuous, correctly-ordered grid. This mirrors WPF's
        // SplitPaneCellLayoutPlanner in spirit (same source metrics/cells), adapted to Avalonia's
        // single-Grid-of-rows/columns rendering model instead of DrawingContext painting.
        var rowMetrics = CombineSplitRowMetrics(viewport);
        var colMetrics = CombineSplitColumnMetrics(viewport);
        var splitRowCount = viewport.SplitPanes?.TopRows?.Count ?? 0;
        var splitColCount = viewport.SplitPanes?.LeftColumns?.Count ?? 0;

        var cellsByAddress = viewport.Cells.ToDictionary(cell => (cell.Row, cell.Col));
        if (viewport.SplitPanes?.Cells is { Count: > 0 } splitCells)
        {
            foreach (var cell in splitCells)
                cellsByAddress[(cell.Row, cell.Col)] = cell;
        }

        _sparklinesByCell = BuildSparklineCellLookup(_session.Workbook, _session.ActiveSheet);
        BuildPivotAdornmentLookups(_session.Workbook, _session.ActiveSheet);
        _activeSheetHasBackgroundImage = _session.ActiveSheet.BackgroundImage != null;
        var grid = new AvaloniaGrid
        {
            Background = (IBrush?)BuildWorksheetBackgroundBrush(_session.ActiveSheet.BackgroundImage) ?? Brushes.White,
        };

        if (showHeadings)
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(GetRowHeaderWidth(viewport, zoomFactor)) });
        foreach (var metric in colMetrics)
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(GetDisplayedColumnWidth(metric, zoomFactor)) });

        if (showHeadings)
            grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(GetColumnHeaderHeight(viewport, zoomFactor)) });
        foreach (var metric in rowMetrics)
            grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(GetDisplayedRowHeight(metric, zoomFactor)) });

        if (showHeadings)
        {
            AddGridChild(grid, CreateSelectAllCornerCell(zoomFactor), 0, 0);
            for (var colIndex = 0; colIndex < colMetrics.Count; colIndex++)
            {
                var col = colMetrics[colIndex].Col;
                var selected = IsSelectedColumn(col);
                AddGridChild(grid, CreateColumnHeaderCell(col, colMetrics[colIndex], selected, zoomFactor), 0, colIndex + headerOffset);
            }
        }

        // Merged regions: map each visible row/col to its grid index so a merge's anchor cell can
        // span the full merged rectangle (Grid.RowSpan/ColumnSpan) instead of rendering as separate
        // 1x1 slots. Non-anchor member cells are skipped entirely below — the anchor's spanned
        // Border paints over their slots, which suppresses inner gridlines/borders for free.
        var rowIndexByRow = new Dictionary<uint, int>(rowMetrics.Count);
        for (var i = 0; i < rowMetrics.Count; i++)
            rowIndexByRow[rowMetrics[i].Row] = i;
        var colIndexByCol = new Dictionary<uint, int>(colMetrics.Count);
        for (var i = 0; i < colMetrics.Count; i++)
            colIndexByCol[colMetrics[i].Col] = i;

        for (var rowIndex = 0; rowIndex < rowMetrics.Count; rowIndex++)
        {
            var rowMetric = rowMetrics[rowIndex];
            var row = rowMetric.Row;
            var rowHeight = GetDisplayedRowHeight(rowMetric, zoomFactor);
            if (showHeadings)
            {
                var selectedRow = IsSelectedRow(row);
                AddGridChild(grid, CreateRowHeaderCell(row, rowMetric, selectedRow, zoomFactor), rowIndex + headerOffset, 0);
            }

            for (var colIndex = 0; colIndex < colMetrics.Count; colIndex++)
            {
                var colMetric = colMetrics[colIndex];
                var col = colMetric.Col;
                var address = new CellAddress(_session.ActiveSheet.Id, row, col);
                var mergeRegion = _session.ActiveSheet.GetMergeRegion(address);
                if (mergeRegion is { } merge)
                {
                    // The merge's true anchor (top-left cell) is normally what renders the spanned
                    // Border, with every other member cell skipped below it. But when the anchor's
                    // own row/col has scrolled out of the viewport (e.g. a tall B5:B10 merge scrolled
                    // so ViewTopRow lands on row 7), the anchor is never iterated at all, so nothing
                    // would ever render for this merge — a blank hole where Excel instead keeps
                    // showing the merge's content/fill in whatever portion remains visible. Resolve
                    // the topmost/leftmost *visible* member as a substitute anchor in that case, so
                    // the merge still paints (and still carries the true anchor's content/style).
                    var isVisibleAnchor = ResolveVisibleMergeAnchor(merge, rowIndexByRow, colIndexByCol) is { } visibleAnchor
                        && visibleAnchor.Row == row && visibleAnchor.Col == col;
                    if (!isVisibleAnchor)
                    {
                        // Non-anchor member of a merge: the (possibly substitute) anchor's spanned
                        // Border covers this slot, so skip rendering a separate cell.
                        continue;
                    }
                }

                var colWidth = GetDisplayedColumnWidth(colMetric, zoomFactor);
                var contentAddress = mergeRegion is { } contentMerge
                    ? new CellAddress(_session.ActiveSheet.Id, contentMerge.Start.Row, contentMerge.Start.Col)
                    : address;
                if (!cellsByAddress.TryGetValue((contentAddress.Row, contentAddress.Col), out var cell) &&
                    contentAddress != address &&
                    ResolveOffViewportCell(contentAddress) is { } offViewportCell)
                {
                    // The true anchor is off-viewport (see the substitute-anchor comment above), so
                    // its DisplayCell was never produced by the engine's viewport scan (which only
                    // covers rows/cols within RowMetrics/ColMetrics) — cellsByAddress has no entry for
                    // it. Resolve a minimal DisplayCell straight from the live Sheet/Workbook so the
                    // substitute anchor still shows the true anchor's content and style rather than
                    // rendering blank, matching Excel's behavior of keeping a scrolled merge's content
                    // visible in whatever portion of the merge remains on screen.
                    cell = offViewportCell;
                }

                var rowSpan = 1;
                var colSpan = 1;
                if (mergeRegion is { } anchorMerge)
                {
                    (rowSpan, colSpan, rowHeight, colWidth) = ResolveVisibleMergeSpan(
                        anchorMerge, rowIndex, colIndex, rowIndexByRow, colIndexByCol, rowMetrics, colMetrics, zoomFactor, rowHeight, colWidth);
                }

                var cellControl = CreateCell(cell, row, col, zoomFactor, colWidth, rowHeight, mergeRegion);
                if (rowSpan > 1)
                    AvaloniaGrid.SetRowSpan(cellControl, rowSpan);
                if (colSpan > 1)
                    AvaloniaGrid.SetColumnSpan(cellControl, colSpan);
                AddGridChild(grid, cellControl, rowIndex + headerOffset, colIndex + headerOffset);
            }
        }

        AddCellTextOverflowOverlayToGrid(
            grid,
            cellsByAddress,
            rowMetrics,
            colMetrics,
            showHeadings,
            zoomFactor);

        if (splitRowCount > 0 || splitColCount > 0)
        {
            AddSplitPaneDividerOverlayToGrid(grid, rowMetrics, colMetrics, splitRowCount, splitColCount, headerOffset);
            AddSplitPanePointerChromeToGrid(
                grid,
                viewport,
                rowMetrics,
                colMetrics,
                showHeadings,
                zoomFactor);
        }
        AddSelectionOverlayToGrid(
            grid,
            rowMetrics,
            colMetrics,
            headerOffset,
            zoomFactor);
        AddActiveCellBoxOverlayToGrid(
            grid,
            rowMetrics,
            colMetrics,
            headerOffset,
            zoomFactor);
        AddClipboardMarqueeOverlayToGrid(
            grid,
            rowMetrics,
            colMetrics,
            headerOffset,
            zoomFactor);
        AddAutofillPreviewOverlayToGrid(
            grid,
            rowMetrics,
            colMetrics,
            headerOffset,
            zoomFactor);
        AddSelectionMovePreviewOverlayToGrid(
            grid,
            rowMetrics,
            colMetrics,
            headerOffset,
            zoomFactor);

        var formulaReferenceOverlay = BuildFormulaReferenceGridOverlay(viewport, showHeadings, zoomFactor);
        AvaloniaGrid.SetRowSpan(formulaReferenceOverlay, grid.RowDefinitions.Count);
        AvaloniaGrid.SetColumnSpan(formulaReferenceOverlay, grid.ColumnDefinitions.Count);
        grid.Children.Add(formulaReferenceOverlay);

        var overlay = BuildDrawingObjectOverlay(viewport);
        _cellAffordanceOverlay = overlay;
        AddFormulaReferenceGripOverlay(overlay, viewport, showHeadings, zoomFactor);
        AddDataValidationDropdownOverlay(overlay, viewport, showHeadings, zoomFactor);

        var pageBreakOverlay = WorksheetViewModeUiStatePlanner.Build(_session.ViewMode).UsesPageBreakPreviewOverlay
            ? BuildPageBreakPreviewOverlay(viewport, showHeadings, zoomFactor)
            : null;

        // Excel draws the manual (dashed blue) page-break lines in EVERY view mode, including
        // Normal, once the sheet has at least one manual break - not just in Page Layout / Page
        // Break Preview (see GridView.Overlays.cs RenderManualPageBreaks for the WPF equivalent,
        // which is called unconditionally regardless of WorksheetViewMode). Build it independently
        // of pageBreakOverlay above so Normal view gets it too.
        var manualPageBreakOverlay = BuildManualPageBreakOverlay(viewport, showHeadings, zoomFactor);
        var outlineOverlay = BuildOutlineOverlay(viewport, showHeadings, zoomFactor);
        if (outlineOverlay is not null)
        {
            AvaloniaGrid.SetRowSpan(outlineOverlay, grid.RowDefinitions.Count);
            AvaloniaGrid.SetColumnSpan(outlineOverlay, grid.ColumnDefinitions.Count);
            grid.Children.Add(outlineOverlay);
        }

        if (overlay.Children.Count == 0 && pageBreakOverlay is null && manualPageBreakOverlay is null)
            return grid;

        var composite = new AvaloniaGrid
        {
            ClipToBounds = true,
            Children = { grid },
        };
        if (pageBreakOverlay is not null)
            composite.Children.Add(pageBreakOverlay);
        if (manualPageBreakOverlay is not null)
            composite.Children.Add(manualPageBreakOverlay);
        if (overlay.Children.Count > 0)
            composite.Children.Add(overlay);
        return composite;
    }

    private static readonly IBrush ManualPageBreakLineBrush = Brush(0, 103, 192);

    /// <summary>
    /// Builds the dashed-blue manual (user-inserted) row/column page-break lines shown in every grid
    /// view mode once the active sheet has at least one manual break — matching Excel and the WPF
    /// shell's <c>GridView.Overlays.cs RenderManualPageBreaks</c>, which draws these unconditionally
    /// rather than only in Page Layout / Page Break Preview. Returns null when the sheet has no manual
    /// breaks, or none of them fall within the current viewport.
    /// </summary>
    private Canvas? BuildManualPageBreakOverlay(ViewportModel viewport, bool showHeadings, double zoomFactor)
    {
        var sheet = _session.ActiveSheet;
        var rowBreaks = sheet.RowPageBreaks;
        var colBreaks = sheet.ColumnPageBreaks;
        if (rowBreaks is not { Count: > 0 } && colBreaks is not { Count: > 0 })
            return null;

        var displayViewport = PageBreakPreviewInstructionBuilder.ProjectToDisplaySpace(
            viewport,
            zoomFactor,
            MinimumDisplayedColumnWidth,
            MinimumDisplayedRowHeight);

        var rowHeaderWidth = showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0;
        var columnHeaderHeight = showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0;
        var actualWidth = CalculateDisplayedGridWidth(viewport, showHeadings, zoomFactor);
        var actualHeight = CalculateDisplayedGridHeight(viewport, showHeadings, zoomFactor);

        var lines = BuildManualPageBreakLineInstructions(
            displayViewport, rowBreaks, colBreaks, rowHeaderWidth, columnHeaderHeight, actualWidth, actualHeight);
        if (lines.Count == 0)
            return null;

        var overlay = new Canvas
        {
            Width = actualWidth,
            Height = actualHeight,
            ClipToBounds = true,
            IsHitTestVisible = false,
        };
        AutomationProperties.SetAutomationId(overlay, "ManualPageBreakOverlay");

        foreach (var line in lines)
        {
            overlay.Children.Add(new global::Avalonia.Controls.Shapes.Line
            {
                StartPoint = new Point(line.X1, line.Y1),
                EndPoint = new Point(line.X2, line.Y2),
                Stroke = ManualPageBreakLineBrush,
                StrokeThickness = 2,
                StrokeDashArray = [6, 4],
            });
        }

        return overlay;
    }

    /// <summary>
    /// Pure geometry for <see cref="BuildManualPageBreakOverlay"/>: a horizontal line above each manual
    /// row break, and a vertical line left of each manual column break, spanning the full grid — the
    /// same geometry the WPF shell's RenderManualPageBreaks computes directly from RowMetrics/ColMetrics
    /// (no dependency on the print-range/pagination layout PageBreakPreviewLayoutPlanner uses for masks/
    /// automatic breaks/watermarks). Internal + static so it is independently unit-testable.
    /// </summary>
    internal static IReadOnlyList<PageBreakLineInstruction> BuildManualPageBreakLineInstructions(
        ViewportModel displayViewport,
        IReadOnlyCollection<uint>? rowPageBreaks,
        IReadOnlyCollection<uint>? columnPageBreaks,
        double rowHeaderWidth,
        double columnHeaderHeight,
        double gridWidth,
        double gridHeight)
    {
        var lines = new List<PageBreakLineInstruction>();

        if (rowPageBreaks is { Count: > 0 })
        {
            var rowBreakLookup = rowPageBreaks as IReadOnlySet<uint> ?? new HashSet<uint>(rowPageBreaks);
            foreach (var metric in displayViewport.RowMetrics)
            {
                if (!rowBreakLookup.Contains(metric.Row))
                    continue;

                var y = metric.TopOffset + columnHeaderHeight;
                lines.Add(new PageBreakLineInstruction(rowHeaderWidth, y, gridWidth, y));
            }
        }

        if (columnPageBreaks is { Count: > 0 })
        {
            var columnBreakLookup = columnPageBreaks as IReadOnlySet<uint> ?? new HashSet<uint>(columnPageBreaks);
            foreach (var metric in displayViewport.ColMetrics)
            {
                if (!columnBreakLookup.Contains(metric.Col))
                    continue;

                var x = metric.LeftOffset + rowHeaderWidth;
                lines.Add(new PageBreakLineInstruction(x, columnHeaderHeight, x, gridHeight));
            }
        }

        return lines;
    }

    /// <summary>
    /// Prepends Window ▸ Split's pinned top rows (<see cref="SplitPaneState.TopRows"/>) ahead of the
    /// main scrollable pane's <see cref="ViewportModel.RowMetrics"/>, producing one continuous,
    /// correctly-ordered row sequence that covers all split quadrants. Returns
    /// <c>viewport.RowMetrics</c> unchanged (no allocation) when the sheet has no row split, so the
    /// common unsplit case is exactly as before.
    /// </summary>
    private static IReadOnlyList<RowMetric> CombineSplitRowMetrics(ViewportModel viewport)
    {
        var topRows = viewport.SplitPanes?.TopRows;
        if (topRows is not { Count: > 0 })
            return viewport.RowMetrics;

        // The main (BottomRight) pane's own scroll position (sheet.ViewTopRow) is tracked
        // independently of the split row and can still point above it (e.g. right after Window ▸
        // Split is first applied at the active cell, before the user scrolls the bottom pane down).
        // Excel always keeps the scrollable pane's first visible row at or below the split line, so
        // defensively drop any main-pane row already covered by the pinned block — otherwise the same
        // row number would appear twice (once pinned, once scrollable) and collide in rowIndexByRow.
        var lastPinnedRow = topRows[^1].Row;
        var combined = new List<RowMetric>(topRows.Count + viewport.RowMetrics.Count);
        combined.AddRange(topRows);
        foreach (var metric in viewport.RowMetrics)
        {
            if (metric.Row > lastPinnedRow)
                combined.Add(metric);
        }

        return combined;
    }

    /// <summary>
    /// Prepends Window ▸ Split's pinned left columns (<see cref="SplitPaneState.LeftColumns"/>) ahead
    /// of the main scrollable pane's <see cref="ViewportModel.ColMetrics"/> — the column analogue of
    /// <see cref="CombineSplitRowMetrics"/>.
    /// </summary>
    private static IReadOnlyList<ColMetric> CombineSplitColumnMetrics(ViewportModel viewport)
    {
        var leftColumns = viewport.SplitPanes?.LeftColumns;
        if (leftColumns is not { Count: > 0 })
            return viewport.ColMetrics;

        // See CombineSplitRowMetrics for why the main pane's own columns are filtered against the
        // pinned block rather than simply concatenated.
        var lastPinnedCol = leftColumns[^1].Col;
        var combined = new List<ColMetric>(leftColumns.Count + viewport.ColMetrics.Count);
        combined.AddRange(leftColumns);
        foreach (var metric in viewport.ColMetrics)
        {
            if (metric.Col > lastPinnedCol)
                combined.Add(metric);
        }

        return combined;
    }

    /// <summary>
    /// Draws the Window ▸ Split divider line(s) at the boundary between the pinned split rows/columns
    /// prepended by <see cref="CombineSplitRowMetrics"/>/<see cref="CombineSplitColumnMetrics"/> and
    /// the main scrollable pane — the split quadrants themselves are already laid out correctly by
    /// virtue of being real grid rows/columns (see BuildSheetGrid), so this only needs to paint the
    /// separating line(s), mirroring <see cref="AddFreezePaneDividerOverlay"/> and WPF's
    /// GridView.Rendering.Headers.cs RenderSplitDivider.
    /// </summary>
    private void AddSplitPaneDividerOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int splitRowCount,
        int splitColCount,
        int headerOffset)
    {
        if (splitRowCount > 0)
        {
            var horizontalDivider = new Border
            {
                Background = FreezeDividerBrush,
                Height = FreezeDividerThickness,
                VerticalAlignment = AvaloniaVerticalAlignment.Bottom,
                IsHitTestVisible = false,
            };
            AvaloniaGrid.SetRow(horizontalDivider, splitRowCount - 1 + headerOffset);
            AvaloniaGrid.SetColumn(horizontalDivider, 0);
            AvaloniaGrid.SetColumnSpan(horizontalDivider, colMetrics.Count + headerOffset);
            grid.Children.Add(horizontalDivider);
        }

        if (splitColCount > 0)
        {
            var verticalDivider = new Border
            {
                Background = FreezeDividerBrush,
                Width = FreezeDividerThickness,
                HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                IsHitTestVisible = false,
            };
            AvaloniaGrid.SetColumn(verticalDivider, splitColCount - 1 + headerOffset);
            AvaloniaGrid.SetRow(verticalDivider, 0);
            AvaloniaGrid.SetRowSpan(verticalDivider, rowMetrics.Count + headerOffset);
            grid.Children.Add(verticalDivider);
        }
    }

    /// <summary>
    /// Computes how far a merge's rendered anchor cell (the true top-left anchor, or — when that
    /// anchor has scrolled out of the viewport — the topmost/leftmost visible substitute resolved
    /// by <see cref="ResolveVisibleMergeAnchor"/>) should span in grid rows/columns, clipped to the
    /// portion of the merge that is actually contiguous and visible in the current viewport (a
    /// merge can be partially scrolled off, or straddle the frozen/scrollable boundary where row
    /// indices are not contiguous — in either case we only span as far as metrics are present and
    /// consecutive). Spanning always starts from the rendered row/col (not necessarily the merge's
    /// true Start), since a substitute anchor renders at its own row/col but must still span the
    /// remaining visible extent of the merge. Returns the resolved span plus the summed
    /// height/width across that span so the anchor's content (text alignment, ShrinkToFit
    /// measurement) lays out against the full visible rectangle rather than just one row/column.
    /// </summary>
    private static (int RowSpan, int ColSpan, double Height, double Width) ResolveVisibleMergeSpan(
        GridRange merge,
        int rowIndex,
        int colIndex,
        Dictionary<uint, int> rowIndexByRow,
        Dictionary<uint, int> colIndexByCol,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        double zoomFactor,
        double anchorHeight,
        double anchorWidth)
    {
        var renderedRow = rowMetrics[rowIndex].Row;
        var renderedCol = colMetrics[colIndex].Col;

        var rowSpan = 1;
        var height = anchorHeight;
        for (var r = renderedRow + 1; r <= merge.End.Row; r++)
        {
            if (!rowIndexByRow.TryGetValue(r, out var nextRowIndex) || nextRowIndex != rowIndex + rowSpan)
                break;
            height += GetDisplayedRowHeight(rowMetrics[nextRowIndex], zoomFactor);
            rowSpan++;
        }

        var colSpan = 1;
        var width = anchorWidth;
        for (var c = renderedCol + 1; c <= merge.End.Col; c++)
        {
            if (!colIndexByCol.TryGetValue(c, out var nextColIndex) || nextColIndex != colIndex + colSpan)
                break;
            width += GetDisplayedColumnWidth(colMetrics[nextColIndex], zoomFactor);
            colSpan++;
        }

        return (rowSpan, colSpan, height, width);
    }

    /// <summary>
    /// Resolves the cell that should render a merged region's spanned Border in the current
    /// viewport: the merge's true anchor (top-left cell) when it is visible, or — when the anchor's
    /// own row/col has scrolled out of view — the topmost/leftmost row/col of the merge that IS
    /// present in the viewport metrics. This mirrors Excel, which keeps showing a merged cell's
    /// content/fill in whatever portion of the merge remains visible rather than leaving a blank
    /// gap once the anchor itself scrolls past the top/left edge. Returns null only if no part of
    /// the merge is present in the viewport at all (shouldn't happen for a merge we were asked to
    /// resolve an anchor for, since the caller only calls this for a cell known to be in the merge).
    /// </summary>
    private static CellAddress? ResolveVisibleMergeAnchor(
        GridRange merge,
        Dictionary<uint, int> rowIndexByRow,
        Dictionary<uint, int> colIndexByCol)
    {
        uint? visibleRow = null;
        for (var r = merge.Start.Row; r <= merge.End.Row; r++)
        {
            if (!rowIndexByRow.ContainsKey(r))
                continue;
            visibleRow = r;
            break;
        }

        uint? visibleCol = null;
        for (var c = merge.Start.Col; c <= merge.End.Col; c++)
        {
            if (!colIndexByCol.ContainsKey(c))
                continue;
            visibleCol = c;
            break;
        }

        if (visibleRow is not { } r2 || visibleCol is not { } c2)
            return null;

        return new CellAddress(merge.Start.Sheet, r2, c2);
    }

    /// <summary>
    /// Builds a minimal <see cref="DisplayCell"/> straight from the live <see cref="Sheet"/>/
    /// <see cref="Workbook"/> for an address the engine's viewport scan never produced a DisplayCell
    /// for — specifically a merge's true anchor that has scrolled outside RowMetrics/ColMetrics (see
    /// BuildSheetGrid's substitute-anchor handling). This intentionally shows the literal value/raw
    /// formula text rather than a fully engine-evaluated/number-formatted result (no formula
    /// evaluation happens here) — sufficient to avoid the blank-hole regression while the anchor is
    /// scrolled off; the instant the anchor scrolls back into view the normal viewport-scanned
    /// DisplayCell (with full formatting) takes over again. Known limitation: because CreateCell's
    /// own per-cell lookups (rich-text runs, pivot label padding) key off the RENDERED row/col rather
    /// than this content address, those specific adornments won't apply to the substitute anchor
    /// while it stands in for an off-viewport true anchor — background/border/gridlines/text content
    /// (the reported defect) are unaffected.
    /// </summary>
    private DisplayCell? ResolveOffViewportCell(CellAddress address)
    {
        var cell = _session.ActiveSheet.GetCell(address);
        if (cell is null)
            return null;

        var displayText = cell.HasFormula && cell.FormulaText is not null
            ? "=" + cell.FormulaText
            : FormatScalarValue(cell.Value);
        var style = _session.Workbook.GetStyle(cell.StyleId);
        return new DisplayCell(address.Row, address.Col, cell.Value, displayText, cell.FormulaText, cell.StyleId, Error: null, Style: style);
    }

    private Canvas BuildFormulaReferenceGridOverlay(
        ViewportModel viewport,
        bool showHeadings,
        double zoomFactor)
    {
        var overlay = new Canvas
        {
            Width = CalculateDisplayedGridWidth(viewport, showHeadings, zoomFactor),
            Height = CalculateDisplayedGridHeight(viewport, showHeadings, zoomFactor),
            ClipToBounds = true,
            IsHitTestVisible = false,
        };
        AutomationProperties.SetAutomationId(overlay, "WorksheetFormulaReferenceOverlay");
        _formulaReferenceGridOverlay = overlay;
        AddFormulaReferenceHighlightOverlay(overlay, viewport, showHeadings, zoomFactor);
        return overlay;
    }

    private Canvas BuildDrawingObjectOverlay(ViewportModel viewport)
    {
        var showHeadings = _session.IsShowingHeadings;
        var zoomFactor = GetActiveZoomFactor();
        var overlay = new Canvas
        {
            Width = CalculateDisplayedGridWidth(viewport, showHeadings, zoomFactor),
            Height = CalculateDisplayedGridHeight(viewport, showHeadings, zoomFactor),
            ClipToBounds = true,
            IsHitTestVisible = true,
        };

        // Charts live on the sheet (not projected into viewport.DrawingObjects), so paint them first —
        // before the drawing-object early-out — so a chart renders even when no other objects exist.
        AddChartOverlays(overlay, viewport);

        // Slicers and timelines are positioned drawing objects connected at the workbook level
        // (not projected into viewport.DrawingObjects), so paint them here — before the
        // drawing-object early-out — so they render even when no other objects exist.
        AddSlicerTimelineOverlays(overlay, viewport);

        // Legacy form controls (checkbox/option/spinner/scrollbar/groupbox/label) live on the sheet,
        // not in viewport.DrawingObjects — paint them before the early-out so they render standalone.
        AddFormControlOverlays(overlay, viewport);

        // Formula-auditing trace arrows live in an app-side set, not in viewport.DrawingObjects —
        // paint them before the early-out so they render even with no other drawing objects.
        AddFormulaTraceArrowOverlay(overlay, viewport);

        // Data ▸ Circle Invalid Data overlay is also app-side — paint before the early-out.
        AddValidationCircleOverlay(overlay, viewport);

        // Review ▸ New/Edit Comment uses the same selected-cell inline editor as WPF. Keep it
        // above the worksheet even when the sheet has no drawing objects.
        AddNoteInlineEditorOverlay(overlay, viewport, showHeadings, zoomFactor);
        AddThreadedCommentInlineEditorOverlay(overlay, viewport, showHeadings, zoomFactor);

        // Freeze Panes divider: the frozen rows/columns are already pinned at the head of
        // viewport.RowMetrics/ColMetrics (BuildFrozenAwareRowMetrics/ColMetrics), so only the
        // separating line itself needs to be drawn here — mirrors WPF's RenderFreezeDivider.
        AddFreezePaneDividerOverlay(overlay, viewport, showHeadings, zoomFactor);

        AddTextBoxInlineEditorOverlay(overlay, viewport, showHeadings, zoomFactor);

        if (viewport.DrawingObjects is not { Count: > 0 })
            return overlay;

        foreach (var renderPlan in DrawingObjectRenderPlanner.Plan(viewport))
        {
            var drawingObject = renderPlan.Bounds;
            if (_textBoxInlineEditingId == drawingObject.Id &&
                drawingObject.Kind == SelectionPaneObjectKind.TextBox)
            {
                continue;
            }
            if (!TryGetDisplayedDrawingObjectBounds(
                    viewport,
                    drawingObject,
                    showHeadings,
                    zoomFactor,
                    out var left,
                    out var top,
                    out var width,
                    out var height))
            {
                continue;
            }

            if (!DrawingObjectViewportPlanner.ShouldDisplayObjectRect(
                    new LayoutRect(left, top, width, height),
                    drawingObject.RotationDegrees,
                    overlay.Width,
                    overlay.Height))
            {
                continue;
            }

            var selected = IsSelectedDrawingObject(drawingObject);
            var visual = CreateSelectableDrawingObjectVisual(renderPlan, width, height);
            Canvas.SetLeft(visual, left - (selected ? DrawingObjectSelectionHorizontalPadding : 0));
            Canvas.SetTop(visual, top - (selected ? DrawingObjectSelectionTopPadding : 0));
            overlay.Children.Add(visual);
        }

        return overlay;
    }

    /// <summary>
    /// Draws the Freeze Panes divider line(s) at the boundary between the pinned frozen
    /// rows/columns and the scrollable body — the frozen region itself is already pinned by
    /// BuildFrozenAwareRowMetrics/ColMetrics (consumed via viewport.RowMetrics/ColMetrics ordering),
    /// so this only needs to draw the separating line(s), matching WPF's
    /// GridView.Rendering.Headers.cs RenderFreezeDivider.
    /// </summary>
    private void AddFreezePaneDividerOverlay(Canvas overlay, ViewportModel viewport, bool showHeadings, double zoomFactor)
    {
        var frozen = viewport.FrozenPanes;
        if (frozen is not { } frozenPanes || (frozenPanes.Rows == 0 && frozenPanes.Cols == 0))
            return;

        var headerWidth = showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0;
        var headerHeight = showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0;

        if (frozenPanes.Rows > 0)
        {
            // Count pinned entries by row NUMBER membership (row <= frozenPanes.Rows), not by
            // taking the first frozenPanes.Rows entries of RowMetrics — a hidden/collapsed row
            // inside the frozen range is dropped from RowMetrics entirely (BuildFrozenAwareRowMetrics
            // skips hidden rows), so the pinned block can have FEWER entries than frozenPanes.Rows.
            // Summing by raw index would then walk one entry too far into the scrollable body.
            var dividerY = headerHeight;
            for (var i = 0; i < viewport.RowMetrics.Count && viewport.RowMetrics[i].Row <= frozenPanes.Rows; i++)
                dividerY += GetDisplayedRowHeight(viewport.RowMetrics[i], zoomFactor);

            var horizontalDivider = new Border
            {
                Background = FreezeDividerBrush,
                Width = overlay.Width,
                Height = FreezeDividerThickness,
                IsHitTestVisible = false,
            };
            Canvas.SetLeft(horizontalDivider, 0);
            Canvas.SetTop(horizontalDivider, dividerY - (FreezeDividerThickness / 2));
            overlay.Children.Add(horizontalDivider);
        }

        if (frozenPanes.Cols > 0)
        {
            // Same hidden-column-immune counting as the row divider above: sum pinned entries by
            // col NUMBER membership rather than assuming the first frozenPanes.Cols entries of
            // ColMetrics are the pinned block.
            var dividerX = headerWidth;
            for (var i = 0; i < viewport.ColMetrics.Count && viewport.ColMetrics[i].Col <= frozenPanes.Cols; i++)
                dividerX += GetDisplayedColumnWidth(viewport.ColMetrics[i], zoomFactor);

            var verticalDivider = new Border
            {
                Background = FreezeDividerBrush,
                Width = FreezeDividerThickness,
                Height = overlay.Height,
                IsHitTestVisible = false,
            };
            Canvas.SetLeft(verticalDivider, dividerX - (FreezeDividerThickness / 2));
            Canvas.SetTop(verticalDivider, 0);
            overlay.Children.Add(verticalDivider);
        }
    }

    private void AddDataValidationDropdownOverlay(
        Canvas overlay,
        ViewportModel viewport,
        bool showHeadings,
        double zoomFactor)
    {
        // Resolve cell bounds first — needed for both the input-message tooltip (which is
        // type-agnostic and must show during edit, matching WPF/Excel) and the arrow button
        // (which is list-DV-only and hidden during edit).
        if (!TryGetDisplayedCellBounds(
                viewport,
                _session.ActiveCell,
                showHeadings,
                zoomFactor,
                out var left,
                out var top,
                out var width,
                out var height))
        {
            return;
        }

        // BM1+BM2: Input-message tooltip is type-agnostic and stays visible during edit,
        // matching WPF's independent RefreshDvInputMessage (no editing guard) and Excel's
        // behaviour. Clamp against the visible scroll-viewport, not the full grid canvas
        // (BM3), so the tooltip flips correctly near the viewport edge.
        var viewportBounds = _sheetScrollViewer.Bounds;
        AddDvInputMessageOverlay(
            overlay,
            left,
            top + height,
            viewportBounds.Width > 0 ? viewportBounds.Width : overlay.Width,
            viewportBounds.Height > 0 ? viewportBounds.Height : overlay.Height);

        // The dropdown arrow is only for List-DV and must be hidden while editing (the
        // in-line editor is open), matching Excel and WPF's RefreshValidationDropdown guard.
        if (_session.FormulaEditAddress is not null || IsTextBoxInlineEditorActive)
            return;

        if (!DataValidationDropdownPlanner.TryPlan(
                _session.Workbook,
                _session.ActiveSheet,
                _session.ActiveCell,
                new DataValidationDropdownCellBounds(left, top, width, height),
                out var plan))
        {
            return;
        }

        // Size the ComboBox to exactly ArrowButtonWidth so it looks like Excel's in-cell
        // dropdown-arrow button (a narrow button with a chevron, flush with the cell's right edge).
        var btnWidth = Math.Max(DataValidationDropdownPlanner.MinimumWidth,
            DataValidationAffordancePlanner.ArrowButtonWidth * zoomFactor);
        var btnHeight = Math.Max(DataValidationDropdownPlanner.MinimumHeight, plan.Bounds.Height);
        var btnLeft = left + width - btnWidth;

        var dropdown = CreateDataValidationDropdown(plan, btnWidth, btnHeight);
        Canvas.SetLeft(dropdown, btnLeft);
        Canvas.SetTop(dropdown, plan.Bounds.Top);
        overlay.Children.Add(dropdown);
        _activeDataValidationDropdown = dropdown;
    }

    private void AddDvInputMessageOverlay(
        Canvas overlay,
        double cellLeft,
        double cellBottom,
        double overlayWidth,
        double overlayHeight)
    {
        var prompt = DataValidationAffordancePlanner.GetInputMessagePrompt(
            _session.ActiveSheet, _session.ActiveCell);
        if (prompt is null)
            return;

        const double boxWidth = 160;
        const double maxBoxHeight = 120;

        var left = Math.Max(0, Math.Min(cellLeft, Math.Max(0, overlayWidth - boxWidth)));
        var top = cellBottom + 2;
        if (top + maxBoxHeight > overlayHeight && top > maxBoxHeight + 2)
            top = Math.Max(0, cellBottom - maxBoxHeight - 2);

        var panel = new StackPanel { MaxWidth = boxWidth - 16 };

        if (prompt.Value.Title.Length > 0)
        {
            panel.Children.Add(new TextBlock
            {
                Text = prompt.Value.Title,
                FontWeight = FontWeight.Bold,
                FontSize = 11,
                Foreground = Brushes.Black,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, prompt.Value.Message.Length > 0 ? 3 : 0)
            });
        }

        if (prompt.Value.Message.Length > 0)
        {
            panel.Children.Add(new TextBlock
            {
                Text = prompt.Value.Message,
                FontSize = 11,
                Foreground = Brushes.Black,
                TextWrapping = TextWrapping.Wrap
            });
        }

        var border = new Border
        {
            Background = new SolidColorBrush(Color.FromRgb(255, 255, 225)),
            BorderBrush = new SolidColorBrush(Color.FromRgb(158, 151, 113)),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(8, 6, 8, 6),
            Width = boxWidth,
            MaxHeight = maxBoxHeight,
            Child = panel,
        };
        AutomationProperties.SetAutomationId(border, "WorksheetDvInputMessagePopup");
        AutomationProperties.SetName(border, "Data validation input message");

        Canvas.SetLeft(border, left);
        Canvas.SetTop(border, top);
        overlay.Children.Add(border);
    }

    private ComboBox CreateDataValidationDropdown(DataValidationDropdownPlan plan, double width, double height)
    {
        var dropdown = new ComboBox
        {
            ItemsSource = plan.Items,
            SelectedItem = plan.SelectedItem,
            Width = width,
            Height = height,
            MinWidth = DataValidationDropdownPlanner.MinimumWidth,
            MinHeight = DataValidationDropdownPlanner.MinimumHeight,
            MaxDropDownHeight = 220,
            Padding = new Thickness(0),
            FontSize = 12,
            Cursor = new Cursor(StandardCursorType.Hand)
        };

        ToolTip.SetTip(dropdown, "Pick from list");
        AutomationProperties.SetAutomationId(dropdown, "WorksheetDataValidationDropdown");
        AutomationProperties.SetName(dropdown, "Data validation list");
        AutomationProperties.SetHelpText(dropdown, "Pick a permitted value for the active cell.");
        dropdown.SelectionChanged += DataValidationDropdown_SelectionChanged;
        return dropdown;
    }

    private Control CreateSelectableDrawingObjectVisual(
        DrawingObjectRenderPlan renderPlan,
        double width,
        double height)
    {
        var drawingObject = renderPlan.Bounds;
        var selected = IsSelectedDrawingObject(drawingObject);
        var cropMode = selected && _isPictureCropMode &&
            drawingObject.Kind == SelectionPaneObjectKind.Picture &&
            drawingObject.PictureKind == PictureKind.Image;
        var horizontalPadding = selected ? DrawingObjectSelectionHorizontalPadding : 0;
        var topPadding = selected ? DrawingObjectSelectionTopPadding : 0;
        var bottomPadding = selected ? DrawingObjectSelectionBottomPadding : 0;
        var surface = new AvaloniaGrid
        {
            Width = Math.Max(1, width),
            Height = Math.Max(1, height),
            Margin = new Thickness(horizontalPadding, topPadding, 0, 0),
            HorizontalAlignment = global::Avalonia.Layout.HorizontalAlignment.Left,
            VerticalAlignment = global::Avalonia.Layout.VerticalAlignment.Top,
            IsHitTestVisible = false,
        };
        surface.Children.Add(CreateDrawingObjectVisual(renderPlan, width, height, _session.Workbook.Theme));
        var container = new AvaloniaGrid
        {
            Width = Math.Max(1, width) + (horizontalPadding * 2),
            Height = Math.Max(1, height) + topPadding + bottomPadding,
            Background = Brushes.Transparent,
            ClipToBounds = false,
            Cursor = selected ? Cursor.Default : new Cursor(StandardCursorType.Hand),
            Focusable = true,
        };
        var adorner = cropMode
            ? CreatePictureCropSelectionAdorner(
                width,
                height,
                new PictureCropRatios(
                    drawingObject.CropLeft,
                    drawingObject.CropTop,
                    drawingObject.CropRight,
                    drawingObject.CropBottom))
            : selected
                ? CreateDrawingObjectSelectionAdorner(width, height, drawingObject.RotationDegrees)
                : null;

        AutomationProperties.SetAutomationId(container, $"DrawingObject{drawingObject.Kind}{drawingObject.Id:N}");
        AutomationProperties.SetName(container, $"{FormatDrawingObjectKind(drawingObject.Kind)} {drawingObject.DisplayName}");
        AutomationProperties.SetHelpText(container, "Selects this drawing object preview in the workbook viewport.");
        AutomationProperties.SetItemStatus(container, selected ? "Selected" : "Not selected");

        container.PointerPressed += (_, args) =>
        {
            if (args.GetCurrentPoint(container).Properties.IsRightButtonPressed)
            {
                // Right-click selects the object, then opens its per-target context menu.
                HandleDrawingObjectPointerContext(drawingObject, container, args);
                return;
            }

            if (args.GetCurrentPoint(container).Properties.IsLeftButtonPressed)
            {
                if (cropMode && adorner is not null && TryBeginPictureCropDrag(renderPlan, container, surface, adorner, args))
                    return;

                var isTextBoxDoubleClick =
                    args.ClickCount >= 2 && drawingObject.Kind == SelectionPaneObjectKind.TextBox;
                if (!cropMode && adorner is not null && !isTextBoxDoubleClick &&
                    TryBeginDrawingObjectDrag(renderPlan, container, surface, adorner, args))
                    return;

                SelectDrawingObject(drawingObject);
                if (isTextBoxDoubleClick)
                {
                    BeginTextBoxInlineEdit(drawingObject.Id);
                    args.Handled = true;
                    return;
                }
                args.Handled = true;
            }
        };
        container.KeyDown += (_, args) =>
        {
            if (cropMode && args.Key == Key.Escape)
            {
                ExitPictureCropMode();
                args.Handled = true;
                return;
            }

            if (args.Key is Key.Enter or Key.Space)
            {
                SelectDrawingObject(drawingObject);
                args.Handled = true;
            }
        };

        container.Children.Add(surface);
        if (adorner is not null)
        {
            container.Children.Add(adorner);
            if (cropMode)
                WirePictureCropDragMoveRelease(renderPlan, container, surface);
            else
                WireDrawingObjectDragMoveRelease(renderPlan, container, surface);
        }

        return container;
    }

    private void SelectDrawingObject(DrawingObjectBounds drawingObject)
    {
        if (IsTextBoxInlineEditorVisible &&
            (drawingObject.Kind != SelectionPaneObjectKind.TextBox ||
             drawingObject.Id != _textBoxInlineEditingId) &&
            !HideTextBoxInlineEditor(commit: true))
        {
            return;
        }

        if (!TryCommitPendingFormulaEdit())
            return;

        if (_isPictureCropMode &&
            (drawingObject.Kind != SelectionPaneObjectKind.Picture || drawingObject.Id != _selectedDrawingObjectId))
        {
            _isPictureCropMode = false;
            _pictureCropDragSession = null;
        }

        _selectedDrawingObjectKind = drawingObject.Kind;
        _selectedDrawingObjectId = drawingObject.Id;
        _ribbonContextSource.OnDrawingObjectSelected(drawingObject.Kind);
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
        RefreshShell($"Selected {FormatDrawingObjectKind(drawingObject.Kind)}: {drawingObject.DisplayName}");
    }

    private bool IsSelectedDrawingObject(DrawingObjectBounds drawingObject) =>
        _selectedDrawingObjectKind == drawingObject.Kind &&
        _selectedDrawingObjectId == drawingObject.Id;

    private string? ResolveSelectedDrawingObjectNameBoxText()
    {
        if (_selectedDrawingObjectKind is not { } selectedKind ||
            _selectedDrawingObjectId is not { } selectedId)
        {
            return null;
        }

        return NameBoxDropdownPlanner
            .Build(_session.Workbook, _session.ActiveSheet.Id)
            .FirstOrDefault(item =>
                item.Kind == NameBoxNavigationItemKind.Object &&
                item.ObjectKind == selectedKind &&
                item.ObjectId == selectedId)
            ?.Name;
    }

    private void ClearSelectedDrawingObject()
    {
        if (IsTextBoxInlineEditorVisible && !HideTextBoxInlineEditor(commit: true))
            return;

        _isPictureCropMode = false;
        _pictureCropDragSession = null;
        _selectedDrawingObjectKind = null;
        _selectedDrawingObjectId = null;
        _ribbonContextSource.OnSelectionCleared();
        // WPF's selected-object context callback re-evaluates cell-based contexts after the object
        // is cleared. Keep the same ordering here: the accessors must see no drawing selection, then
        // derive table/pivot state from the active cell that commands intentionally leave unchanged.
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
    }

    private static string FormatDrawingObjectKind(SelectionPaneObjectKind kind) =>
        kind switch
        {
            SelectionPaneObjectKind.Picture => "Picture",
            SelectionPaneObjectKind.Shape => "Shape",
            SelectionPaneObjectKind.TextBox => "Text box",
            _ => "Drawing object"
        };

    private static Control CreateDrawingObjectVisual(
        DrawingObjectRenderPlan renderPlan,
        double width,
        double height,
        WorkbookTheme theme)
    {
        var drawingObject = renderPlan.Bounds;
        var visual = renderPlan.PrimitiveKind switch
        {
            DrawingObjectRenderPrimitiveKind.Shape => CreateDrawingShapeVisual(drawingObject, width, height),
            DrawingObjectRenderPrimitiveKind.Image or DrawingObjectRenderPrimitiveKind.CroppedImage =>
                CreateDrawingImageVisual(renderPlan, width, height),
            DrawingObjectRenderPrimitiveKind.CellRangeSnapshot => CreateDrawingCellRangeSnapshotVisual(renderPlan, width, height, theme),
            DrawingObjectRenderPrimitiveKind.TextBox => CreateDrawingTextBoxVisual(drawingObject, width, height),
            _ => CreateDrawingObjectBoundsMarker(drawingObject, width, height)
        };
        ApplyDrawingObjectTransform(
            visual,
            drawingObject.RotationDegrees,
            drawingObject.FlipHorizontal,
            drawingObject.FlipVertical);
        return visual;
    }

    private static Control CreateDrawingShapeVisual(
        DrawingObjectBounds drawingObject,
        double width,
        double height)
    {
        var metadata = DrawingObjectRenderMetadataPlanner.ResolveBoundsShapeRenderMetadata(drawingObject);
        // Render the body fill when the shape carries one (FillColor non-null = HasFill=true in model).
        // WordArt with no body fill (FillColor=null) uses Transparent so the styled text shows alone.
        // WordArt WITH an authored body fill still renders the box behind the styled text, matching
        // Excel which shows the filled box and the styled run text together.
        var fill = metadata.FillColor is { } fc
            ? Brush(fc)
            : Brushes.Transparent;
        // When OutlineHasNoFill is set the shape explicitly has no border stroke.
        IBrush? strokeBrush = metadata.OutlineColor is { } outlineColor
            ? Brush(outlineColor)
            : null;
        // pt → Avalonia DIPs at 96 dpi: 1 pt = 96/72 DIP. Fall back to 1.5 when unset.
        var strokeThickness = metadata.OutlineThicknessDip;
        var dashArray = GetShapeOutlineDashArray(metadata.OutlineDash);

        var w = Math.Max(1, width);
        var h = Math.Max(1, height);

        // Line now flows through CreateDrawingShapeGeometryVisual → ShapeGeometryBuilder (LinePath)
        // so it renders at the correct angle and length. The old stub Border is removed.
        Control shapeControl = drawingObject.ShapeKind switch
        {
            DrawingShapeKind.Ellipse => CreateEllipseShapeVisual(fill, strokeBrush, strokeThickness, dashArray, w, h),
            _ => CreateDrawingShapeGeometryVisual(drawingObject.ShapeKind, fill, strokeBrush, strokeThickness, dashArray, w, h),
        };

        ApplyDrawingObjectEffect(shapeControl, drawingObject.Effect);

        // Arrowheads for line-like shapes: overlay filled polygons on a Canvas.
        var hasArrowheads = metadata.IsLineLike && metadata.HasArrowheads;

        // Overlay shape text inside the same rotation envelope (text is added as a sibling in a
        // Grid so that ApplyDrawingObjectTransform, called by the caller, rotates both together).
        if (hasArrowheads || metadata.HasShapeText)
        {
            var grid = new AvaloniaGrid
            {
                Width = w,
                Height = h,
                IsHitTestVisible = false,
            };
            grid.Children.Add(shapeControl);
            if (hasArrowheads)
                AddArrowheadOverlays(grid, drawingObject, w, h, strokeBrush, metadata.OutlineThicknessDip);
            if (metadata.HasShapeText)
                grid.Children.Add(CreateShapeTextOverlay(drawingObject, w, h));
            return grid;
        }

        return shapeControl;
    }

    /// <summary>
    /// Adds filled arrowhead Path elements on top of a line/connector visual inside <paramref name="container"/>.
    /// Uses <see cref="ArrowheadGeometry"/> for the polygon math so the calculation is shared with WPF.
    /// </summary>
    private static void AddArrowheadOverlays(
        AvaloniaGrid container,
        DrawingObjectBounds d,
        double w,
        double h,
        IBrush? arrowBrush,
        double strokeDip)
    {
        if (arrowBrush is null || d.ShapeKind is not { } kind)
            return;

        // Pass flipHorizontal/flipVertical as false here: ApplyDrawingObjectTransform sets a
        // ScaleTransform on the container visual that already flips the entire overlay (and its
        // arrowhead Path children). Passing the flip flags to LineEndpoints would mirror the
        // endpoints a second time, landing them at the wrong corners and pointing the wrong way.
        var (startPt, endPt, dirStartToEnd) = ArrowheadGeometry.LineEndpoints(
            0, 0, w, h,
            flipHorizontal: false, flipVertical: false, kind);

        // HeadEnd = start of line, points backward (opposite of travel direction)
        if (d.HeadArrowhead?.IsPresent == true)
            AddArrowheadPath(container, d.HeadArrowhead, startPt, dirStartToEnd + Math.PI, strokeDip, arrowBrush);

        // TailEnd = end of line, points forward (same as travel direction)
        if (d.TailArrowhead?.IsPresent == true)
            AddArrowheadPath(container, d.TailArrowhead, endPt, dirStartToEnd, strokeDip, arrowBrush);
    }

    private static void AddArrowheadPath(
        AvaloniaGrid container,
        DrawingArrowhead arrowhead,
        LayoutPoint tip,
        double directionRadians,
        double strokeWidth,
        IBrush brush)
    {
        if (arrowhead.Type == DrawingArrowheadType.Oval)
        {
            var (center, radius) = ArrowheadGeometry.OvalCenter(arrowhead, tip, directionRadians, strokeWidth);
            var ellipse = new AvaloniaEllipse
            {
                Width = radius * 2,
                Height = radius * 2,
                Fill = brush,
                HorizontalAlignment = global::Avalonia.Layout.HorizontalAlignment.Left,
                VerticalAlignment = global::Avalonia.Layout.VerticalAlignment.Top,
                Margin = new Thickness(center.X - radius, center.Y - radius, 0, 0),
                IsHitTestVisible = false,
            };
            container.Children.Add(ellipse);
            return;
        }

        var pts = ArrowheadGeometry.PolygonPoints(arrowhead, tip, directionRadians, strokeWidth);
        if (pts.Length < 3)
            return;

        var geometry = new StreamGeometry();
        using (var ctx = geometry.Open())
        {
            ctx.BeginFigure(new Point(pts[0].X, pts[0].Y), isFilled: true);
            for (var i = 1; i < pts.Length; i++)
                ctx.LineTo(new Point(pts[i].X, pts[i].Y));
            ctx.EndFigure(isClosed: true);
        }

        var path = new global::Avalonia.Controls.Shapes.Path
        {
            Data = geometry,
            Fill = brush,
            Stretch = Stretch.None,
            HorizontalAlignment = global::Avalonia.Layout.HorizontalAlignment.Left,
            VerticalAlignment = global::Avalonia.Layout.VerticalAlignment.Top,
            IsHitTestVisible = false,
        };
        container.Children.Add(path);
    }

    private static AvaloniaEllipse CreateEllipseShapeVisual(
        IBrush fill,
        IBrush? stroke,
        double strokeThickness,
        double[]? dashArray,
        double w,
        double h)
    {
        var ellipse = new AvaloniaEllipse
        {
            Width = w,
            Height = h,
            Fill = fill,
            Stroke = stroke,
            StrokeThickness = strokeThickness,
            IsHitTestVisible = false,
        };
        if (dashArray is not null)
            ellipse.StrokeDashArray = new AvaloniaList<double>(dashArray);
        return ellipse;
    }

    // Renders shape text as a TextBlock overlay that sits inside the shape's bounding box.
    // Padding, alignment, font, and wrap mirror WPF DrawShapeText.
    // For WordArt shapes: applies gradient Foreground and an outline approximation when set.
    // Returns Control (not TextBlock) so an outline layer Panel can be returned when needed.
    private static Control CreateShapeTextOverlay(DrawingObjectBounds d, double w, double h)
    {
        const double HPad = 4;
        const double VPad = 2;
        const double DefaultFontSizePt = 11.0;
        const double PtToDip = 96.0 / 72.0;

        var fontSizeDip = (d.ShapeTextFontSizePoints > 0 ? d.ShapeTextFontSizePoints : DefaultFontSizePt) * PtToDip;

        IBrush textBrush;
        if (d.ShapeTextColor is { } tc)
        {
            textBrush = Brush(tc);
        }
        else
        {
            // Default: white on dark fill, black on light fill.
            var fc = d.FillColor ?? new CellColor(0x5B, 0x9B, 0xD5);
            var luminance = 0.299 * fc.R + 0.587 * fc.G + 0.114 * fc.B;
            textBrush = luminance < 128 ? Brushes.White : Brushes.Black;
        }

        // WordArt gradient text fill: override Foreground with a vertical LinearGradientBrush.
        // Approximation: the gradient covers the text block bounding box (not per-glyph geometry).
        if (d.IsWordArt && d.ShapeTextGradientEndColor is { } gradEnd && d.ShapeTextColor is { } startColor)
        {
            textBrush = new LinearGradientBrush
            {
                StartPoint = new RelativePoint(0.5, 0, RelativeUnit.Relative),
                EndPoint   = new RelativePoint(0.5, 1, RelativeUnit.Relative),
                GradientStops =
                {
                    new GradientStop(Color.FromRgb(startColor.R, startColor.G, startColor.B), 0),
                    new GradientStop(Color.FromRgb(gradEnd.R,    gradEnd.G,    gradEnd.B),    1),
                },
            };
        }

        var hAlign = d.ShapeTextHAlign switch
        {
            DrawingShapeTextHAlign.Center => TextAlignment.Center,
            DrawingShapeTextHAlign.Right  => TextAlignment.Right,
            _                             => TextAlignment.Left,
        };

        var vAlign = d.ShapeTextVAnchor switch
        {
            DrawingShapeTextVAnchor.Top    => AvaloniaVerticalAlignment.Top,
            DrawingShapeTextVAnchor.Bottom => AvaloniaVerticalAlignment.Bottom,
            _                             => AvaloniaVerticalAlignment.Center,
        };

        var decorations = d.ShapeTextUnderline
            ? CreateTextDecorations(TextDecorationLocation.Underline)
            : null;

        var fillBlock = new TextBlock
        {
            Text = d.ShapeText,
            FontSize = fontSizeDip,
            FontWeight = d.ShapeTextBold ? FontWeight.Bold : FontWeight.Normal,
            FontStyle = d.ShapeTextItalic ? FontStyle.Italic : FontStyle.Normal,
            TextDecorations = decorations,
            Foreground = textBrush,
            TextAlignment = hAlign,
            VerticalAlignment = vAlign,
            TextWrapping = d.ShapeTextWrap ? TextWrapping.Wrap : TextWrapping.NoWrap,
            TextTrimming = d.ShapeTextWrap ? TextTrimming.None : TextTrimming.CharacterEllipsis,
            Margin = new Thickness(HPad, VPad, HPad, VPad),
            IsHitTestVisible = false,
        };

        // WordArt text outline: approximate WPF's per-glyph geometry stroke by layering the text
        // in the outline color at small offsets in 8 directions beneath the fill text.
        // Avalonia's FormattedText does not expose BuildGeometry, so we use this layered approach.
        // The offset is proportional to the outline width (clamped to 0.5–3 DIP so thin outlines
        // remain crisp and thick outlines don't bleed too far).
        if (d.IsWordArt && d.ShapeTextOutlineColor is { } outlineColor)
        {
            const double PtToDipLocal = 96.0 / 72.0;
            var outlineWidthDip = d.ShapeTextOutlineWidthPoints > 0
                ? Math.Clamp(d.ShapeTextOutlineWidthPoints * PtToDipLocal, 0.5, 3.0)
                : 0.75; // thin default outline

            IBrush outlineBrush = Brush(outlineColor);

            // 8-direction offsets (N, NE, E, SE, S, SW, W, NW) at half the outline width.
            var o = outlineWidthDip * 0.5;
            ReadOnlySpan<(double dx, double dy)> offsets =
            [
                (0, -o), (o, -o), (o, 0), (o, o),
                (0, o),  (-o, o), (-o, 0), (-o, -o),
            ];

            var panel = new Panel { IsHitTestVisible = false };
            foreach (var (dx, dy) in offsets)
            {
                panel.Children.Add(new TextBlock
                {
                    Text = d.ShapeText,
                    FontSize = fontSizeDip,
                    FontWeight = d.ShapeTextBold ? FontWeight.Bold : FontWeight.Normal,
                    FontStyle = d.ShapeTextItalic ? FontStyle.Italic : FontStyle.Normal,
                    TextDecorations = decorations,
                    Foreground = outlineBrush,
                    TextAlignment = hAlign,
                    VerticalAlignment = vAlign,
                    TextWrapping = d.ShapeTextWrap ? TextWrapping.Wrap : TextWrapping.NoWrap,
                    TextTrimming = d.ShapeTextWrap ? TextTrimming.None : TextTrimming.CharacterEllipsis,
                    Margin = new Thickness(HPad + dx, VPad + dy, HPad - dx, VPad - dy),
                    IsHitTestVisible = false,
                });
            }
            // Fill text on top so gradient/color renders over the outline.
            panel.Children.Add(fillBlock);
            return panel;
        }

        return fillBlock;
    }

    // Maps DrawingShapeOutlineDash → dash arrays compatible with Avalonia StrokeDashArray.
    // Arrays are dash/gap lengths in units of stroke thickness, matching WPF DashStyles.
    private static double[]? GetShapeOutlineDashArray(DrawingShapeOutlineDash dash) => dash switch
    {
        DrawingShapeOutlineDash.Dash or DrawingShapeOutlineDash.LongDash
            or DrawingShapeOutlineDash.SystemDash                       => [2, 2],
        DrawingShapeOutlineDash.Dot or DrawingShapeOutlineDash.SystemDot => [1, 2],
        DrawingShapeOutlineDash.DashDot or DrawingShapeOutlineDash.SystemDashDot => [2, 2, 1, 2],
        DrawingShapeOutlineDash.LongDashDot                             => [2, 2, 1, 2],
        DrawingShapeOutlineDash.LongDashDotDot                          => [2, 2, 1, 2, 1, 2],
        _                                                               => null,
    };

    // Non-ellipse shapes: render the true preset outline via the geometry factory when available,
    // falling back to a plain rectangle for kinds the factory does not cover.
    // Line now flows through here too (the factory opt-out was removed) so LinePath renders
    // at the correct angle and length authored by ShapeGeometryBuilder.
    private static Control CreateDrawingShapeGeometryVisual(
        DrawingShapeKind? shapeKind,
        IBrush fill,
        IBrush? stroke,
        double strokeThickness,
        double[]? dashArray,
        double w,
        double h)
    {
        if (shapeKind is { } kind &&
            AvaloniaDrawingShapeGeometryFactory.CreateGeometry(kind, w, h) is { } geometry)
        {
            var path = new global::Avalonia.Controls.Shapes.Path
            {
                Data = geometry,
                // Geometry is authored inside a (0,0,w,h) box, so render it 1:1.
                Stretch = Stretch.None,
                Width = w,
                Height = h,
                Fill = fill,
                Stroke = stroke,
                StrokeThickness = strokeThickness,
                IsHitTestVisible = false,
            };
            if (dashArray is not null)
                path.StrokeDashArray = new AvaloniaList<double>(dashArray);
            return path;
        }

        var rect = new AvaloniaRectangle
        {
            Width = w,
            Height = h,
            Fill = fill,
            Stroke = stroke,
            StrokeThickness = strokeThickness,
            IsHitTestVisible = false,
        };
        if (dashArray is not null)
            rect.StrokeDashArray = new AvaloniaList<double>(dashArray);
        return rect;
    }

    // Approximates the authored shape effect (shadow / glow / soft-edges / bevel / reflection / 3-D)
    // using Avalonia's bitmap effects. Faithful: outer/inner shadow, glow (offsetless colored shadow),
    // soft-edges (blur). Approximated: bevel / reflection / 3-D fall back to a light drop shadow so the
    // shape still reads as "lifted" without the full WPF authored geometry.
    private static void ApplyDrawingObjectEffect(Control visual, DrawingObjectEffect? effect)
    {
        if (effect is null)
            return;

        var color = effect.Color ?? new CellColor(0, 0, 0);
        var avColor = Color.FromRgb(color.R, color.G, color.B);

        if (effect.HasSoftEdges)
        {
            visual.Effect = new BlurEffect { Radius = effect.BlurRadius };
            return;
        }

        // Shadow, glow, and the bevel/reflection/3-D approximations all map onto a drop shadow.
        // Glow simply uses a zero offset and the glow colour so it reads as a symmetric halo.
        visual.Effect = new DropShadowEffect
        {
            Color = avColor,
            BlurRadius = effect.BlurRadius,
            OffsetX = effect.OffsetX,
            OffsetY = effect.OffsetY,
            Opacity = effect.Opacity,
        };
    }

    private static Control CreateDrawingImageVisual(
        DrawingObjectRenderPlan renderPlan,
        double width,
        double height)
    {
        var drawingObject = renderPlan.Bounds;
        if (drawingObject.ImageBytes is { Length: > 0 } imageBytes &&
            TryCreateDrawingBitmap(imageBytes, out var bitmap))
        {
            var frame = new Border
            {
                Width = Math.Max(1, width),
                Height = Math.Max(1, height),
                BorderBrush = DrawingObjectBoundsBorder,
                BorderThickness = new Thickness(1),
                ClipToBounds = true,
                IsHitTestVisible = false,
            };

            if (renderPlan.Crop is { } crop)
            {
                frame.Background = new ImageBrush(bitmap)
                {
                    Stretch = Stretch.Fill,
                    SourceRect = CreateDrawingImageSourceRect(crop),
                    DestinationRect = RelativeRect.Fill,
                    TileMode = TileMode.None,
                };
                return frame;
            }

            frame.Child = new Image
            {
                Source = bitmap,
                Stretch = Stretch.UniformToFill,
            };
            return frame;
        }

        return CreateDrawingObjectBoundsMarker(drawingObject, width, height);
    }

    private static RelativeRect CreateDrawingImageSourceRect(DrawingPictureCrop crop)
    {
        var left = ClampDrawingCrop(crop.Left);
        var top = ClampDrawingCrop(crop.Top);
        var right = ClampDrawingCrop(crop.Right);
        var bottom = ClampDrawingCrop(crop.Bottom);
        return new RelativeRect(
            left,
            top,
            Math.Max(0.01, 1 - left - right),
            Math.Max(0.01, 1 - top - bottom),
            RelativeUnit.Relative);
    }

    private static double ClampDrawingCrop(double crop) => Math.Clamp(crop, 0, 0.99);

    private static Control CreateDrawingCellRangeSnapshotVisual(
        DrawingObjectRenderPlan renderPlan,
        double width,
        double height,
        WorkbookTheme theme)
    {
        var drawingObject = renderPlan.Bounds;
        if (renderPlan.PictureGrid is not { } pictureGrid)
            return CreateDrawingObjectBoundsMarker(drawingObject, width, height);

        var frameWidth = Math.Max(1, width);
        var frameHeight = Math.Max(1, height);
        var canvas = new Canvas
        {
            Width = frameWidth,
            Height = frameHeight,
            ClipToBounds = true,
            IsHitTestVisible = false,
        };

        var rowCount = Math.Max(1u, pictureGrid.RowCount);
        var columnCount = Math.Max(1u, pictureGrid.ColumnCount);
        var cellWidth = frameWidth / columnCount;
        var cellHeight = frameHeight / rowCount;
        // Built as a manual last-wins loop rather than .ToDictionary(...): PictureModel.Cells is a
        // plain List<PictureCellSnapshot> with no uniqueness constraint on (RowOffset, ColumnOffset),
        // and a hand-edited or adversarial .fxl file can legitimately contain duplicate offsets. A
        // straight ToDictionary throws ArgumentException on the second duplicate and crashes the
        // render; last-wins keeps the render resilient and picks the later (later-drawn) entry,
        // matching normal "last write wins" dictionary-assignment semantics.
        var cellLookup = new Dictionary<(uint RowOffset, uint ColumnOffset), PictureCellSnapshot>();
        foreach (var cell in pictureGrid.Cells)
        {
            if (cell.RowOffset < rowCount && cell.ColumnOffset < columnCount)
                cellLookup[(cell.RowOffset, cell.ColumnOffset)] = cell;
        }

        // Fills/patterns render first so grid separator lines, text, and cell borders sit above
        // them — mirroring WPF's RenderPicture draw order (DrawPictureCellStyle before the grid
        // lines/text/borders passes) so styled snapshot cells match the Windows render exactly.
        foreach (var cell in cellLookup.Values)
        {
            if (cell.Style is not { } cellStyle)
                continue;

            var cellRect = new Rect(
                cell.ColumnOffset * cellWidth,
                cell.RowOffset * cellHeight,
                cellWidth,
                cellHeight);

            if (cellStyle.ResolveFillColor(theme) is { } fillColor)
            {
                var fillRect = new AvaloniaRectangle
                {
                    Width = cellRect.Width,
                    Height = cellRect.Height,
                    Fill = Brush(fillColor),
                    IsHitTestVisible = false,
                };
                Canvas.SetLeft(fillRect, cellRect.X);
                Canvas.SetTop(fillRect, cellRect.Y);
                canvas.Children.Add(fillRect);
            }

            if (CellPatternFill.Build(cellStyle, theme) is { } patternBrush)
            {
                var patternRect = new AvaloniaRectangle
                {
                    Width = cellRect.Width,
                    Height = cellRect.Height,
                    Fill = patternBrush,
                    IsHitTestVisible = false,
                };
                Canvas.SetLeft(patternRect, cellRect.X);
                Canvas.SetTop(patternRect, cellRect.Y);
                canvas.Children.Add(patternRect);
            }
        }

        for (uint row = 1; row < rowCount; row++)
        {
            var line = new AvaloniaRectangle
            {
                Width = frameWidth,
                Height = 1,
                Fill = Brush(0xD7, 0xDE, 0xE6),
                IsHitTestVisible = false,
            };
            Canvas.SetLeft(line, 0);
            Canvas.SetTop(line, Math.Max(0, row * cellHeight));
            canvas.Children.Add(line);
        }

        for (uint column = 1; column < columnCount; column++)
        {
            var line = new AvaloniaRectangle
            {
                Width = 1,
                Height = frameHeight,
                Fill = Brush(0xD7, 0xDE, 0xE6),
                IsHitTestVisible = false,
            };
            Canvas.SetLeft(line, Math.Max(0, column * cellWidth));
            Canvas.SetTop(line, 0);
            canvas.Children.Add(line);
        }

        foreach (var cell in cellLookup.Values)
        {
            if (string.IsNullOrEmpty(cell.Text))
                continue;

            var style = cell.Style;
            var foreground = style is null ? Brushes.Black : Brush(style.ResolveFontColor(theme));
            var horizontalAlignment = style?.HorizontalAlignment ?? CellHAlign.General;
            var textAlignment = MapCellTextAlignment(horizontalAlignment, cell.IsNumericOrDate, isEffectivelyRightToLeft: false);
            var weight = style?.Bold == true ? FontWeight.Bold : FontWeight.Normal;
            var fontStyle = style?.Italic == true ? FontStyle.Italic : FontStyle.Normal;
            var fontSize = Math.Max(1, (style?.FontSize ?? CellStyle.Default.FontSize) + WorksheetFontSizeDisplayOffset);
            var textDecorations = BuildTextDecorations(style);

            var text = new Border
            {
                Width = Math.Max(1, cellWidth - 6),
                Height = Math.Max(1, cellHeight - 2),
                ClipToBounds = true,
                Background = Brushes.Transparent,
                IsHitTestVisible = false,
                Child = new TextBlock
                {
                    Text = cell.Text,
                    FontSize = fontSize,
                    FontWeight = weight,
                    FontStyle = fontStyle,
                    Foreground = foreground,
                    TextAlignment = textAlignment,
                    TextDecorations = textDecorations,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    VerticalAlignment = AvaloniaVerticalAlignment.Center,
                },
            };
            Canvas.SetLeft(text, cell.ColumnOffset * cellWidth + 3);
            Canvas.SetTop(text, cell.RowOffset * cellHeight + 1);
            canvas.Children.Add(text);

            if (style is { } borderStyle && HasVisibleCellBorder(borderStyle))
            {
                var borderOverlay = new CellBorderPanel(borderStyle, ResolvePictureCellBorderNeighborEdges(cell, cellLookup))
                {
                    Width = cellWidth,
                    Height = cellHeight,
                };
                Canvas.SetLeft(borderOverlay, cell.ColumnOffset * cellWidth);
                Canvas.SetTop(borderOverlay, cell.RowOffset * cellHeight);
                canvas.Children.Add(borderOverlay);
            }
        }

        return new Border
        {
            Width = frameWidth,
            Height = frameHeight,
            Background = Brushes.White,
            BorderBrush = DrawingObjectBoundsBorder,
            BorderThickness = new Thickness(1),
            ClipToBounds = true,
            IsHitTestVisible = false,
            Child = canvas,
        };
    }

    /// <summary>
    /// Looks up the four neighboring snapshot cells' touching border edges within the same
    /// picture grid, mirroring <see cref="ResolveCellBorderNeighborEdges"/> for the interactive
    /// sheet grid, so a bordered picture-of-a-range snapshot resolves shared edges the same way.
    /// </summary>
    private static CellBorderNeighborEdges ResolvePictureCellBorderNeighborEdges(
        PictureCellSnapshot cell,
        IReadOnlyDictionary<(uint RowOffset, uint ColumnOffset), PictureCellSnapshot> cellLookup)
    {
        CellBorder above = default, below = default, left = default, right = default;
        if (cell.RowOffset > 0 && cellLookup.TryGetValue((cell.RowOffset - 1, cell.ColumnOffset), out var aboveCell) && aboveCell.Style is { } aboveStyle)
            above = aboveStyle.BorderBottom;
        if (cellLookup.TryGetValue((cell.RowOffset + 1, cell.ColumnOffset), out var belowCell) && belowCell.Style is { } belowStyle)
            below = belowStyle.BorderTop;
        if (cell.ColumnOffset > 0 && cellLookup.TryGetValue((cell.RowOffset, cell.ColumnOffset - 1), out var leftCell) && leftCell.Style is { } leftStyle)
            left = leftStyle.BorderRight;
        if (cellLookup.TryGetValue((cell.RowOffset, cell.ColumnOffset + 1), out var rightCell) && rightCell.Style is { } rightStyle)
            right = rightStyle.BorderLeft;

        return new CellBorderNeighborEdges(above, below, left, right);
    }

    private static Control CreateDrawingTextBoxVisual(
        DrawingObjectBounds drawingObject,
        double width,
        double height) =>
        new Border
        {
            Width = Math.Max(1, width),
            Height = Math.Max(1, height),
            Background = Brush(drawingObject.FillColor ?? CellColor.White),
            BorderBrush = Brush(drawingObject.OutlineColor ?? new CellColor(0x70, 0x70, 0x70)),
            BorderThickness = new Thickness(1.5),
            ClipToBounds = true,
            IsHitTestVisible = false,
            Child = new TextBlock
            {
                Text = string.IsNullOrWhiteSpace(drawingObject.Text)
                    ? drawingObject.DisplayName
                    : drawingObject.Text,
                FontSize = 12,
                Foreground = Brushes.Black,
                Margin = new Thickness(6, 4),
                TextWrapping = TextWrapping.Wrap,
                TextTrimming = TextTrimming.CharacterEllipsis,
            },
        };

    private static Border CreateDrawingObjectBoundsMarker(
        DrawingObjectBounds drawingObject,
        double width,
        double height)
    {
        var marker = new Border
        {
            Width = Math.Max(1, width),
            Height = Math.Max(1, height),
            Background = DrawingObjectBoundsFill,
            BorderBrush = DrawingObjectBoundsBorder,
            BorderThickness = new Thickness(1.5),
            ClipToBounds = true,
            IsHitTestVisible = false,
        };

        if (width >= 56 && height >= 24)
        {
            marker.Child = new TextBlock
            {
                Text = drawingObject.DisplayName,
                FontSize = 11,
                FontWeight = FontWeight.SemiBold,
                Foreground = DrawingObjectBoundsForeground,
                Margin = new Thickness(6, 3),
                TextTrimming = TextTrimming.CharacterEllipsis,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
            };
        }

        return marker;
    }

    /// <summary>
    /// Builds (and caches) the tiled ImageBrush used to paint a worksheet's Page Layout ▸ Background
    /// picture behind the sheet grid — the Avalonia counterpart to WPF's
    /// GridView.DrawingObjects.Pictures.cs GetWorksheetBackgroundBrush/RenderWorksheetBackground.
    /// Returns null (no background) when the sheet has none or the bytes fail to decode.
    /// </summary>
    private ImageBrush? BuildWorksheetBackgroundBrush(WorksheetBackgroundImage? background)
    {
        if (background == null)
        {
            ClearWorksheetBackgroundBrushCache();
            return null;
        }

        if (_worksheetBackgroundBrushCache is { } cached && ReferenceEquals(_worksheetBackgroundBrushSource, background))
            return cached;

        if (!TryCreateDrawingBitmap(background.ImageBytes, out var bitmap))
        {
            ClearWorksheetBackgroundBrushCache();
            return null;
        }

        var brush = new ImageBrush(bitmap)
        {
            TileMode = TileMode.Tile,
            Stretch = Stretch.None,
            AlignmentX = AlignmentX.Left,
            AlignmentY = AlignmentY.Top,
            DestinationRect = new RelativeRect(0, 0, bitmap.PixelSize.Width, bitmap.PixelSize.Height, RelativeUnit.Absolute),
        };

        // Dispose the previously cached brush's native bitmap before replacing the reference — Avalonia's
        // Bitmap wraps an unmanaged Skia surface and is not finalizer-reclaimed like a BCL stream, so
        // simply overwriting the field (the old behavior) leaked one native bitmap per background change.
        (_worksheetBackgroundBrushCache?.Source as IDisposable)?.Dispose();
        _worksheetBackgroundBrushSource = background;
        _worksheetBackgroundBrushCache = brush;
        return brush;
    }

    /// <summary>
    /// Clears the cached worksheet-background <see cref="ImageBrush"/>, disposing its underlying
    /// native <see cref="Bitmap"/> first so removing/changing the background picture does not leak it.
    /// </summary>
    private void ClearWorksheetBackgroundBrushCache()
    {
        (_worksheetBackgroundBrushCache?.Source as IDisposable)?.Dispose();
        _worksheetBackgroundBrushSource = null;
        _worksheetBackgroundBrushCache = null;
    }

    private static bool TryCreateDrawingBitmap(byte[] imageBytes, out Bitmap bitmap)
    {
        try
        {
            using var stream = new MemoryStream(imageBytes);
            bitmap = new Bitmap(stream);
            return true;
        }
        catch (Exception ex) when (ex is ArgumentException or InvalidDataException or NotSupportedException)
        {
            bitmap = null!;
            return false;
        }
    }

    private static void ApplyDrawingObjectTransform(
        Control visual,
        double rotationDegrees,
        bool flipHorizontal,
        bool flipVertical)
    {
        var hasRotation = Math.Abs(rotationDegrees % 360) > 0.0001;
        if (!hasRotation && !flipHorizontal && !flipVertical)
            return;

        visual.RenderTransformOrigin = new RelativePoint(0.5, 0.5, RelativeUnit.Relative);
        if (!flipHorizontal && !flipVertical)
        {
            visual.RenderTransform = new RotateTransform(rotationDegrees);
            return;
        }

        var transform = new TransformGroup();
        transform.Children.Add(new ScaleTransform(flipHorizontal ? -1 : 1, flipVertical ? -1 : 1));
        if (hasRotation)
            transform.Children.Add(new RotateTransform(rotationDegrees));
        visual.RenderTransform = transform;
    }

    private static bool TryGetDisplayedDrawingObjectBounds(
        ViewportModel viewport,
        DrawingObjectBounds drawingObject,
        bool showHeadings,
        double zoomFactor,
        out double left,
        out double top,
        out double width,
        out double height)
    {
        left = 0;
        top = 0;
        width = 0;
        height = 0;
        // drawingObject.AnchorRow/drawingObject.AnchorCol identify the source anchor; Left/Top
        // carry the projected viewport offsets, including preserved sub-cell positioning.
        var rowHeaderWidth = showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0;
        var columnHeaderHeight = showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0;
        if (!DrawingObjectViewportPlanner.TryCreateDisplayedObjectRect(
                drawingObject,
                rowHeaderWidth,
                columnHeaderHeight,
                zoomFactor,
                out var rect))
        {
            return false;
        }

        left = rect.Left;
        top = rect.Top;
        width = rect.Width;
        height = rect.Height;
        return true;
    }

    private static bool TryGetDisplayedCellBounds(
        ViewportModel viewport,
        CellAddress address,
        bool showHeadings,
        double zoomFactor,
        out double left,
        out double top,
        out double width,
        out double height)
    {
        left = 0;
        top = 0;
        width = 0;
        height = 0;

        if (!TryGetDisplayedColumnLeft(viewport.ColMetrics, address.Col, zoomFactor, out var columnLeft) ||
            !TryGetDisplayedRowTop(viewport.RowMetrics, address.Row, zoomFactor, out var rowTop))
        {
            return false;
        }

        var columnMetric = viewport.ColMetrics.First(metric => metric.Col == address.Col);
        var rowMetric = viewport.RowMetrics.First(metric => metric.Row == address.Row);
        left = (showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0) + columnLeft;
        top = (showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0) + rowTop;
        width = GetDisplayedColumnWidth(columnMetric, zoomFactor);
        height = GetDisplayedRowHeight(rowMetric, zoomFactor);
        return true;
    }

    private static bool TryGetDisplayedRangeBounds(
        ViewportModel viewport,
        GridRange range,
        bool showHeadings,
        double zoomFactor,
        out double left,
        out double top,
        out double width,
        out double height)
    {
        left = 0;
        top = 0;
        width = 0;
        height = 0;

        var startCol = Math.Min(range.Start.Col, range.End.Col);
        var endCol = Math.Max(range.Start.Col, range.End.Col);
        var startRow = Math.Min(range.Start.Row, range.End.Row);
        var endRow = Math.Max(range.Start.Row, range.End.Row);
        var visibleColumns = viewport.ColMetrics
            .Where(metric => startCol <= metric.Col && metric.Col <= endCol)
            .ToList();
        var visibleRows = viewport.RowMetrics
            .Where(metric => startRow <= metric.Row && metric.Row <= endRow)
            .ToList();
        if (visibleColumns.Count == 0 || visibleRows.Count == 0)
            return false;

        if (!TryGetDisplayedColumnLeft(viewport.ColMetrics, visibleColumns[0].Col, zoomFactor, out var columnLeft) ||
            !TryGetDisplayedRowTop(viewport.RowMetrics, visibleRows[0].Row, zoomFactor, out var rowTop))
        {
            return false;
        }

        left = (showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0) + columnLeft;
        top = (showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0) + rowTop;
        width = visibleColumns.Sum(metric => GetDisplayedColumnWidth(metric, zoomFactor));
        height = visibleRows.Sum(metric => GetDisplayedRowHeight(metric, zoomFactor));
        return width > 0 && height > 0;
    }

    private static bool TryGetDisplayedColumnLeft(
        IReadOnlyList<ColMetric> columns,
        uint column,
        double zoomFactor,
        out double left)
    {
        left = 0;
        for (var i = 0; i < columns.Count; i++)
        {
            var metric = columns[i];
            if (metric.Col == column)
                return true;
            left += GetDisplayedColumnWidth(metric, zoomFactor);
        }

        left = 0;
        return false;
    }

    private static bool TryGetDisplayedRowTop(
        IReadOnlyList<RowMetric> rows,
        uint row,
        double zoomFactor,
        out double top)
    {
        top = 0;
        for (var i = 0; i < rows.Count; i++)
        {
            var metric = rows[i];
            if (metric.Row == row)
                return true;
            top += GetDisplayedRowHeight(metric, zoomFactor);
        }

        top = 0;
        return false;
    }

    private static double CalculateDisplayedGridWidth(ViewportModel viewport, bool showHeadings, double zoomFactor)
    {
        var width = showHeadings ? GetRowHeaderWidth(viewport, zoomFactor) : 0;
        foreach (var metric in CombineSplitColumnMetrics(viewport))
            width += GetDisplayedColumnWidth(metric, zoomFactor);

        return width;
    }

    private static double CalculateDisplayedGridHeight(ViewportModel viewport, bool showHeadings, double zoomFactor)
    {
        var height = showHeadings ? GetColumnHeaderHeight(viewport, zoomFactor) : 0;
        foreach (var metric in CombineSplitRowMetrics(viewport))
            height += GetDisplayedRowHeight(metric, zoomFactor);

        return height;
    }

    private static double GetDisplayedColumnWidth(ColMetric metric, double zoomFactor) =>
        Math.Max(MinimumDisplayedColumnWidth, metric.Width) * zoomFactor;

    private static double GetDisplayedRowHeight(RowMetric metric, double zoomFactor) =>
        Math.Max(MinimumDisplayedRowHeight, metric.Height) * zoomFactor;

    private void AddCellTextOverflowOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyDictionary<(uint Row, uint Col), DisplayCell> cellsByAddress,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        bool showHeadings,
        double zoomFactor)
    {
        if (cellsByAddress.Count == 0)
            return;

        var rowTopByRow = new Dictionary<uint, double>(rowMetrics.Count);
        var rowTop = showHeadings ? GetColumnHeaderHeight(_session.Viewport, zoomFactor) : 0;
        foreach (var metric in rowMetrics)
        {
            rowTopByRow[metric.Row] = rowTop;
            rowTop += GetDisplayedRowHeight(metric, zoomFactor);
        }

        var colLeftByCol = new Dictionary<uint, double>(colMetrics.Count);
        var colLeft = showHeadings ? GetRowHeaderWidth(_session.Viewport, zoomFactor) : 0;
        foreach (var metric in colMetrics)
        {
            colLeftByCol[metric.Col] = colLeft;
            colLeft += GetDisplayedColumnWidth(metric, zoomFactor);
        }

        var layer = new Canvas
        {
            IsHitTestVisible = false,
            ClipToBounds = true,
            ZIndex = 50,
        };
        AutomationProperties.SetAutomationId(layer, "WorksheetCellTextOverflowOverlay");

        foreach (var cell in cellsByAddress.Values)
        {
            var address = new CellAddress(_session.ActiveSheet.Id, cell.Row, cell.Col);
            if (Equals(_inlineCellEditAddress, address) ||
                !CellTextOverflowPlanner.CanOverflowCellText(
                    cell.Style,
                    cell.RawValue,
                    cell.DisplayText,
                    _session.ActiveSheet.GetMergeRegion(address)) ||
                cell.ConditionalIcon is not null ||
                !rowTopByRow.TryGetValue(cell.Row, out var top) ||
                !colLeftByCol.TryGetValue(cell.Col, out var left))
            {
                continue;
            }

            var rowIndex = FindMetricIndex(rowMetrics, cell.Row);
            var colIndex = FindMetricIndex(colMetrics, cell.Col);
            if (rowIndex < 0 || colIndex < 0)
                continue;

            var style = cell.Style;
            // Per-run rich text: resolve raw runs the same way the primary cell content builder
            // does, so an overflowed rich-text cell renders its bold/italic/color runs in the
            // overlay instead of falling back to a single uniformly-styled string.
            IReadOnlyList<ResolvedCellTextRun>? richRuns = null;
            if (_session.ActiveSheet.RichTextRuns.TryGetValue(address, out var rawOverflowRuns))
            {
                richRuns = CellRichRunLayoutPlanner.Resolve(rawOverflowRuns, style ?? CellStyle.Default);
            }
            var rowHeight = GetDisplayedRowHeight(rowMetrics[rowIndex], zoomFactor);
            var colWidth = GetDisplayedColumnWidth(colMetrics[colIndex], zoomFactor);
            var fontFamily = ResolveAvaloniaCellFontFamily(style, _session.Workbook.Theme);
            var fontWeight = style?.Bold == true ? FontWeight.Bold : FontWeight.Normal;
            var fontStyle = style?.Italic == true ? FontStyle.Italic : FontStyle.Normal;
            var foreground = style is null
                ? Brushes.Black
                : Brush(style.ResolveFontColor(_session.Workbook.Theme));
            var fontSize = Math.Max(
                1,
                ((style?.FontSize ?? CellStyle.Default.FontSize) + WorksheetFontSizeDisplayOffset) * zoomFactor);
            var flowDirection = MapCellFlowDirection(
                CellTextOrientationLayoutPlanner.ResolveIsEffectivelyRightToLeft(
                    style?.ReadingOrder ?? CellReadingOrder.Context,
                    _session.ActiveSheet.IsRightToLeft));
            var formatted = new FormattedText(
                cell.DisplayText,
                CultureInfo.CurrentCulture,
                flowDirection,
                new Typeface(fontFamily, fontStyle, fontWeight),
                fontSize,
                Brushes.Black);
            var textWidth = formatted.Width;
            var textHeight = formatted.Height;
            // R72-meta-3: a rich-text cell's true rendered width can exceed this single uniform
            // FormattedText estimate (built from the CELL's overall style, e.g. non-bold) once any
            // run carries its own bold/italic/size (e.g. a bold run measures wider than the whole
            // string assumed non-bold) -- CellRichTextInlinesBuilder renders each run with its own
            // font/weight/style/size, so the overflow CLIP EXTENT below must be measured the same
            // per-run way instead of reusing this uniform width, otherwise the host Canvas's
            // Width=clipRight-clipLeft (ClipToBounds=true) visually clips the tail of a rich-text
            // overflow even into an empty neighbor cell.
            var overflowExtentWidth = CellRichTextInlinesBuilder.HasRuns(richRuns)
                ? MeasureRichRunsWidth(richRuns!, flowDirection)
                : textWidth;
            var indent = GetCellIndentPadding(style) * zoomFactor;
            var horizontalPadding = 8 * zoomFactor;
            var effectiveAlignment = CellTextOrientationLayoutPlanner.ResolveEffectiveHorizontalAlignment(
                style?.HorizontalAlignment ?? CellHAlign.General,
                isNumeric: false,
                flowDirection == FlowDirection.RightToLeft);
            var textLeft = effectiveAlignment switch
            {
                CellHAlign.Right => left + colWidth - horizontalPadding - indent - textWidth,
                CellHAlign.Center => left + ((colWidth - textWidth) / 2),
                _ => left + horizontalPadding + indent,
            };
            var verticalAlignment = style?.VerticalAlignment ?? CellVAlign.Bottom;
            var textTop = verticalAlignment switch
            {
                CellVAlign.Top => top,
                CellVAlign.Center => top + Math.Max(0, (rowHeight - textHeight) / 2),
                _ => top + Math.Max(0, rowHeight - textHeight),
            };

            var cellRight = left + colWidth;
            if (effectiveAlignment is CellHAlign.Left or CellHAlign.General or CellHAlign.Center)
            {
                var rightLimit = ResolveOverflowRightLimit(
                    cell.Row,
                    colIndex,
                    cellRight,
                    cellsByAddress,
                    colMetrics,
                    zoomFactor);
                AddCellTextOverflowExtension(
                    layer,
                    cell,
                    style,
                    fontFamily,
                    fontWeight,
                    fontStyle,
                    fontSize,
                    foreground,
                    flowDirection,
                    textLeft,
                    textTop,
                    top,
                    rowHeight,
                    Math.Max(cellRight, textLeft),
                    Math.Min(rightLimit, textLeft + overflowExtentWidth),
                    richRuns);
            }

            if (effectiveAlignment is CellHAlign.Right or CellHAlign.Center)
            {
                var leftLimit = ResolveOverflowLeftLimit(
                    cell.Row,
                    colIndex,
                    left,
                    cellsByAddress,
                    colMetrics,
                    zoomFactor);
                AddCellTextOverflowExtension(
                    layer,
                    cell,
                    style,
                    fontFamily,
                    fontWeight,
                    fontStyle,
                    fontSize,
                    foreground,
                    flowDirection,
                    textLeft,
                    textTop,
                    top,
                    rowHeight,
                    Math.Max(leftLimit, textLeft),
                    Math.Min(left, textLeft + overflowExtentWidth),
                    richRuns);
            }
        }

        if (layer.Children.Count == 0)
            return;

        AvaloniaGrid.SetRow(layer, 0);
        AvaloniaGrid.SetRowSpan(layer, grid.RowDefinitions.Count);
        AvaloniaGrid.SetColumn(layer, 0);
        AvaloniaGrid.SetColumnSpan(layer, grid.ColumnDefinitions.Count);
        grid.Children.Add(layer);
    }

    private static int FindMetricIndex(IReadOnlyList<RowMetric> metrics, uint row)
    {
        for (var i = 0; i < metrics.Count; i++)
            if (metrics[i].Row == row)
                return i;
        return -1;
    }

    private static int FindMetricIndex(IReadOnlyList<ColMetric> metrics, uint col)
    {
        for (var i = 0; i < metrics.Count; i++)
            if (metrics[i].Col == col)
                return i;
        return -1;
    }

    private double ResolveOverflowRightLimit(
        uint row,
        int colIndex,
        double cellRight,
        IReadOnlyDictionary<(uint Row, uint Col), DisplayCell> cellsByAddress,
        IReadOnlyList<ColMetric> colMetrics,
        double zoomFactor)
    {
        var limit = cellRight;
        var frozenCols = _session.GetEffectiveFrozenCols();
        var previousCol = colMetrics[colIndex].Col;
        for (var index = colIndex + 1; index < colMetrics.Count; index++)
        {
            var col = colMetrics[index].Col;
            // Frozen/scrolled-body seam: when the sheet is scrolled, the combined colMetrics list
            // jumps straight from the last frozen column to the (far-away) first visible scrollable
            // column, with no entry for anything in between. Walking by list index alone cannot tell
            // that gap apart from an adjacent column, so it would draw the overflow straight across
            // the scrolled-off range. Excel's frozen pane is a separate clip region -- overflow must
            // stop at the pane boundary, so bail once we detect the column-number jump past it.
            if (frozenCols > 0 && previousCol <= frozenCols && col > frozenCols)
                break;
            if (IsOverflowOccupied(row, col, cellsByAddress))
                break;
            limit += GetDisplayedColumnWidth(colMetrics[index], zoomFactor);
            previousCol = col;
        }
        return limit;
    }

    private double ResolveOverflowLeftLimit(
        uint row,
        int colIndex,
        double cellLeft,
        IReadOnlyDictionary<(uint Row, uint Col), DisplayCell> cellsByAddress,
        IReadOnlyList<ColMetric> colMetrics,
        double zoomFactor)
    {
        var limit = cellLeft;
        var frozenCols = _session.GetEffectiveFrozenCols();
        var previousCol = colMetrics[colIndex].Col;
        for (var index = colIndex - 1; index >= 0; index--)
        {
            var col = colMetrics[index].Col;
            // Mirror of the seam check above: a scrollable-body cell's leftward overflow must not
            // tunnel backward across the scrolled-off gap into the frozen pane.
            if (frozenCols > 0 && previousCol > frozenCols && col <= frozenCols)
                break;
            if (IsOverflowOccupied(row, col, cellsByAddress))
                break;
            limit -= GetDisplayedColumnWidth(colMetrics[index], zoomFactor);
            previousCol = col;
        }
        return limit;
    }

    private bool IsOverflowOccupied(
        uint row,
        uint col,
        IReadOnlyDictionary<(uint Row, uint Col), DisplayCell> cellsByAddress)
    {
        var address = new CellAddress(_session.ActiveSheet.Id, row, col);
        if (_session.ActiveSheet.GetMergeRegion(address) is not null ||
            Equals(_inlineCellEditAddress, address))
        {
            return true;
        }

        return cellsByAddress.TryGetValue((row, col), out var cell) &&
            CellTextOverflowPlanner.IsOverflowOccupied(cell, _inlineCellEditAddress);
    }

    /// <summary>
    /// R72-meta-3: sums each resolved rich-text run's own <see cref="FormattedText"/> width, using
    /// the identical per-run font family/size/weight/style <see cref="CellRichTextInlinesBuilder.Build"/>
    /// applies to the rendered <c>Run</c> inlines -- so the overflow extent computed from this total
    /// matches what actually renders instead of a single uniform-style estimate over the whole
    /// <c>DisplayText</c> (which under-measures once any run is bolder/larger than the cell's base
    /// style).
    /// </summary>
    private static double MeasureRichRunsWidth(IReadOnlyList<ResolvedCellTextRun> runs, FlowDirection flowDirection)
    {
        var total = 0.0;
        foreach (var run in runs)
        {
            if (string.IsNullOrEmpty(run.Text))
                continue;

            var typeface = new Typeface(
                new FontFamily(run.FontName),
                run.Italic ? FontStyle.Italic : FontStyle.Normal,
                run.Bold ? FontWeight.Bold : FontWeight.Normal);
            var runFormatted = new FormattedText(
                run.Text,
                CultureInfo.CurrentCulture,
                flowDirection,
                typeface,
                run.RenderedFontSize,
                Brushes.Black);
            total += runFormatted.Width;
        }

        return total;
    }

    private static void AddCellTextOverflowExtension(
        Canvas layer,
        DisplayCell cell,
        CellStyle? style,
        FontFamily fontFamily,
        FontWeight fontWeight,
        FontStyle fontStyle,
        double fontSize,
        IBrush foreground,
        FlowDirection flowDirection,
        double textLeft,
        double textTop,
        double rowTop,
        double rowHeight,
        double clipLeft,
        double clipRight,
        IReadOnlyList<ResolvedCellTextRun>? richRuns = null)
    {
        if (clipRight - clipLeft <= 0.5)
            return;

        var host = new Canvas
        {
            Width = clipRight - clipLeft,
            Height = rowHeight,
            ClipToBounds = true,
            IsHitTestVisible = false,
        };
        var text = new TextBlock
        {
            FontFamily = fontFamily,
            FontSize = fontSize,
            FontWeight = fontWeight,
            FontStyle = fontStyle,
            Foreground = foreground,
            TextWrapping = TextWrapping.NoWrap,
            TextTrimming = TextTrimming.None,
            FlowDirection = flowDirection,
        };

        // Per-run rich text: populate Inlines (one Run per resolved run), matching the primary
        // cell content path in BuildCellContent/CreateInteractiveCellBorder. R72-meta-3: the extent
        // (clipLeft/clipRight) is now computed by the caller from MeasureRichRunsWidth's per-run
        // total instead of the plain display-text width, so this Width=clipRight-clipLeft,
        // ClipToBounds=true host no longer clips a bolder/larger run's tail short.
        if (CellRichTextInlinesBuilder.HasRuns(richRuns))
        {
            CellRichTextInlinesBuilder.Build(richRuns!, text.Inlines!, color => Brush(color));
        }
        else
        {
            text.Text = cell.DisplayText;
            text.TextDecorations = BuildTextDecorations(style);
        }

        Canvas.SetLeft(text, textLeft - clipLeft);
        Canvas.SetTop(text, textTop - rowTop);
        host.Children.Add(text);
        Canvas.SetLeft(host, clipLeft);
        Canvas.SetTop(host, rowTop);
        layer.Children.Add(host);
    }

    private bool IsSelectedColumn(uint col) =>
        _session.SelectedRanges.Any(range => range.Start.Col <= col && col <= range.End.Col);

    private bool IsSelectedRow(uint row) =>
        _session.SelectedRanges.Any(range => range.Start.Row <= row && row <= range.End.Row);

    private bool IsSelectedCell(CellAddress address) =>
        _session.SelectedRanges.Any(range => range.Contains(address));

    // Excel treats a merged region as a single selectable unit: if any selected range overlaps
    // any part of the merge, the whole merge (and therefore its lone rendered anchor cell) reads
    // as selected — matching the marching/selection highlight painting the full merged rectangle.
    private bool IsSelectedCell(CellAddress address, GridRange? mergeRegion) =>
        mergeRegion is { } merge
            ? _session.SelectedRanges.Any(range => range.Overlaps(merge))
            : IsSelectedCell(address);

    // Mirrors the WPF GridView's TryRenderSingleCellSelectedHeaders special case: a plain single-cell
    // selection (the common click-a-cell case) shows the same flat SelectionHeaderBackground on both
    // of its headers, so the active/selected distinction only matters once the selection spans more
    // than one cell.
    private bool IsMultiCellSelection() =>
        _session.SelectedRanges.Count > 1 ||
        (_session.SelectedRanges.Count == 1 && _session.SelectedRanges[0].CellCount > 1);

    // The active cell's own column/row header renders with ActiveSelectionHeaderBackground so the
    // user can locate the active cell at a glance within a multi-cell selection (matches WPF's
    // ActiveHeaderHighlightBrush behavior in GridView.Rendering.Headers.cs).
    private bool IsActiveHeaderColumn(uint col) =>
        IsMultiCellSelection() && _session.ActiveCell.Col == col;

    private bool IsActiveHeaderRow(uint row) =>
        IsMultiCellSelection() && _session.ActiveCell.Row == row;

    private Border CreateHeaderCell(string text, bool selected = false, bool isActive = false, double zoomFactor = 1) =>
        CreateCellBorder(
            text,
            isActive ? ActiveSelectionHeaderBackground : selected ? SelectionHeaderBackground : HeaderBackground,
            selected ? SelectionHeaderForeground : HeaderForeground,
            TextAlignment.Center,
            AvaloniaVerticalAlignment.Center,
            TextWrapping.NoWrap,
            FontWeight.SemiBold,
            FontStyle.Normal,
            fontSize: 11,
            textDecorations: null,
            selected: false,
            zoomFactor: zoomFactor,
            horizontalPadding: 2);

    private Control CreateSelectAllCornerCell(double zoomFactor)
    {
        var header = CreateHeaderCell("", zoomFactor: zoomFactor);
        header.Cursor = new Cursor(StandardCursorType.Hand);
        ToolTip.SetTip(header, "Select all");
        AutomationProperties.SetAutomationId(header, "WorksheetSelectAllCorner");
        AutomationProperties.SetName(header, "Select all cells");
        header.PointerPressed += (_, args) =>
        {
            var point = args.GetCurrentPoint(header);
            if (IsContextClick(point, args))
            {
                SelectAllCells();
                OpenWorksheetCellContextMenu(_sheetGridHost);
                args.Handled = true;
                return;
            }

            SelectAllCells();
            args.Handled = true;
        };
        return header;
    }

    /// <summary>
    /// Builds a clickable column header. Left-click selects the whole column (Shift extends from the
    /// active cell); right-click selects then opens the shared column-header context menu, so Hide/
    /// Unhide Columns and the other column commands act on the column the user clicked.
    /// </summary>
    private Control CreateColumnHeaderCell(uint col, ColMetric metric, bool selected, double zoomFactor)
    {
        var header = CreateHeaderCell(CellAddress.NumberToColumnName(col), selected, IsActiveHeaderColumn(col), zoomFactor);
        header.Padding = new Thickness(0, GetColumnOutlineGutterHeight(_session.Viewport, zoomFactor), 0, 0);
        header.Cursor = new Cursor(StandardCursorType.Hand);
        header.PointerPressed += (_, args) =>
        {
            var point = args.GetCurrentPoint(header);
            if (IsHeaderResizeHotspot(point.Position, header.Bounds, HeaderResizeKind.Column))
            {
                if (args.ClickCount >= 2)
                    AutoFitColumnFromHeader(col);
                else
                    BeginHeaderResize(args, header, HeaderResizeKind.Column, col, GetDisplayedColumnWidth(metric, zoomFactor));

                args.Handled = true;
                return;
            }

            if (IsContextClick(point, args))
            {
                if (!IsSelectedColumn(col))
                    SelectEntireColumn(col);
                OpenColumnHeaderContextMenu(_sheetGridHost);
                args.Handled = true;
                return;
            }

            if (!args.KeyModifiers.HasFlag(KeyModifiers.Shift) && args.KeyModifiers.HasFlag(KeyModifiers.Control))
            {
                // Ctrl+click a column header adds it as a disjoint area (Excel's multi-area
                // column selection), matching the WPF host's AddAdditionalColumnSelection
                // (R84-app-mouse-selection-5-1) instead of wiping the existing selection down
                // to just this column the way a plain click does.
                AddAdditionalColumnSelection(col);
                BeginHeaderSelectionDrag(args, header, HeaderResizeKind.Column, col);
                args.Handled = true;
                return;
            }

            SelectEntireColumn(col, extend: args.KeyModifiers.HasFlag(KeyModifiers.Shift));
            BeginHeaderSelectionDrag(args, header, HeaderResizeKind.Column, col);
            args.Handled = true;
        };
        header.PointerMoved += (_, args) => ContinueHeaderSelectionDrag(args, HeaderResizeKind.Column, col);
        header.PointerReleased += (_, args) => EndHeaderSelectionDrag(args);
        return AddColumnResizeHandle(header, col, metric, zoomFactor);
    }

    /// <summary>
    /// Builds a clickable row header. Left-click selects the whole row (Shift extends from the active
    /// cell); right-click selects then opens the shared row-header context menu, so Hide/Unhide Rows
    /// and the other row commands act on the row the user clicked.
    /// </summary>
    private Control CreateRowHeaderCell(uint row, RowMetric metric, bool selected, double zoomFactor)
    {
        var header = CreateHeaderCell(row.ToString(), selected, IsActiveHeaderRow(row), zoomFactor);
        header.Padding = new Thickness(GetRowOutlineGutterWidth(_session.Viewport, zoomFactor), 0, 0, 0);
        header.Cursor = new Cursor(StandardCursorType.Hand);
        header.PointerPressed += (_, args) =>
        {
            var point = args.GetCurrentPoint(header);
            if (IsHeaderResizeHotspot(point.Position, header.Bounds, HeaderResizeKind.Row))
            {
                if (args.ClickCount >= 2)
                    AutoFitRowFromHeader(row);
                else
                    BeginHeaderResize(args, header, HeaderResizeKind.Row, row, GetDisplayedRowHeight(metric, zoomFactor));

                args.Handled = true;
                return;
            }

            if (IsContextClick(point, args))
            {
                if (!IsSelectedRow(row))
                    SelectEntireRow(row);
                OpenRowHeaderContextMenu(_sheetGridHost);
                args.Handled = true;
                return;
            }

            if (!args.KeyModifiers.HasFlag(KeyModifiers.Shift) && args.KeyModifiers.HasFlag(KeyModifiers.Control))
            {
                // Row-header counterpart of the column-header Ctrl+click fix above
                // (R84-app-mouse-selection-5-1).
                AddAdditionalRowSelection(row);
                BeginHeaderSelectionDrag(args, header, HeaderResizeKind.Row, row);
                args.Handled = true;
                return;
            }

            SelectEntireRow(row, extend: args.KeyModifiers.HasFlag(KeyModifiers.Shift));
            BeginHeaderSelectionDrag(args, header, HeaderResizeKind.Row, row);
            args.Handled = true;
        };
        header.PointerMoved += (_, args) => ContinueHeaderSelectionDrag(args, HeaderResizeKind.Row, row);
        header.PointerReleased += (_, args) => EndHeaderSelectionDrag(args);
        return AddRowResizeHandle(header, row, metric, zoomFactor);
    }

    private static bool IsContextClick(PointerPoint point, PointerEventArgs args) =>
        point.Properties.PointerUpdateKind == PointerUpdateKind.RightButtonPressed ||
        point.Properties.IsRightButtonPressed ||
        (OperatingSystem.IsMacOS() &&
            (point.Properties.PointerUpdateKind == PointerUpdateKind.LeftButtonPressed ||
             point.Properties.IsLeftButtonPressed) &&
            args.KeyModifiers.HasFlag(KeyModifiers.Control));

    private static bool HasHyperlinkActivationModifier(KeyModifiers modifiers) =>
        OperatingSystem.IsMacOS()
            ? modifiers.HasFlag(KeyModifiers.Meta)
            : modifiers.HasFlag(KeyModifiers.Control);

    private static bool IsHeaderResizeHotspot(Point position, Rect bounds, HeaderResizeKind kind) =>
        kind == HeaderResizeKind.Column
            ? position.X >= Math.Max(0, bounds.Width - HeaderResizeHitThickness)
            : position.Y >= Math.Max(0, bounds.Height - HeaderResizeHitThickness);

    private void BeginCellSelectionDrag(PointerPressedEventArgs args, Control capture, CellAddress address)
    {
        // Defensive: drop any stale subscriptions left over from a drag that lost capture without a
        // PointerReleased (grid rebuild, alt-tab, context menu), so we never double-subscribe.
        DetachCellSelectionDragHandlers();
        // Also defensively clear stale drag-state flags so a stranded autofill/move drag cannot
        // accidentally commit against a stale source range on the next drag.
        _autofillDragging = false;
        _autofillSourceRange = null;
        _autofillTarget = null;
        _selectionMoveDragging = false;
        _selectionMoveSourceRange = null;
        _selectionMovePreviewRange = null;
        _cellDragFormulaPointCursor = null;
        _cellDragFormulaReferenceStart = null;
        _cellDragFormulaReferenceLength = null;
        _selectionExtensionAnchor = null;
        _selectionExtensionCursor = null;
        _cellSelectionDragShowedDimensionText = false;

        _cellDragSelectionAnchor = address;
        // Keep _cellDragSelectionCapture for Focus() — the per-cell border is the right focus target.
        _cellDragSelectionCapture = capture;
        _cellDragSelectionPointer = args.Pointer;
        capture.Focus();
        // Capture on _sheetGridHost — the persistent host that SURVIVES RefreshShell/BuildSheetGrid,
        // so the first ContinueCellSelectionDrag → SelectRangeFromAnchor → RefreshShell cannot
        // destroy the captured control and cause Avalonia to silently drop pointer capture.
        _sheetGridHost.PointerMoved += CellSelectionCapturePointerMoved;
        _sheetGridHost.PointerReleased += CellSelectionCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost += CellSelectionCapturePointerCaptureLost;
        args.Pointer.Capture(_sheetGridHost);
    }

    private void CellSelectionCapturePointerMoved(object? sender, PointerEventArgs args) =>
        ContinueCellSelectionDrag(args, _cellDragSelectionAnchor ?? default);

    private async void CellSelectionCapturePointerReleased(object? sender, PointerReleasedEventArgs args) =>
        await EndCellSelectionDragAsync(args);

    // If the OS revokes pointer capture mid-drag (grid rebuild, alt-tab, focus loss, a context menu),
    // abort the drag and clear all drag state without committing any fill/move — mirrors the
    // HeaderResizeCapturePointerCaptureLost cleanup pattern.
    private void CellSelectionCapturePointerCaptureLost(object? sender, PointerCaptureLostEventArgs args)
    {
        // Detach FIRST so the Capture(null) inside the cleanup below cannot re-raise
        // PointerCaptureLost back into this handler (which would re-enter indefinitely).
        DetachCellSelectionDragHandlers();
        // Do NOT commit autofill or selection-move: capture lost means the drag was interrupted,
        // so silently clear all drag state.
        _cellDragSelectionPointer?.Capture(null);
        _cellDragSelectionAnchor = null;
        _cellDragSelectionCapture = null;
        _cellDragSelectionPointer = null;
        _cellDragFormulaPointCursor = null;
        _cellDragFormulaReferenceStart = null;
        _cellDragFormulaReferenceLength = null;
        _selectionExtensionAnchor = null;
        _selectionExtensionCursor = null;
        _autofillDragging = false;
        _autofillSourceRange = null;
        _autofillTarget = null;
        _selectionMoveDragging = false;
        _selectionMoveSourceRange = null;
        _selectionMovePreviewRange = null;
        RevertNameBoxAfterCellSelectionDragEnd();
    }

    // While a plain mouse-drag selection was in progress, the Name Box showed a live dimension
    // readout instead of the range address (see SelectRangeFromAnchor); now that the drag has
    // ended (release or an interrupted capture loss), revert it to the plain range address,
    // matching Excel and the WPF host's CompleteDragSelectionStatusRefresh
    // (R69-render-active-cell-selection-6-2).
    private void RevertNameBoxAfterCellSelectionDragEnd()
    {
        if (!_cellSelectionDragShowedDimensionText)
            return;

        _cellSelectionDragShowedDimensionText = false;
        if (!_cellAddressBoxHasPendingEdit)
            _cellAddressText.Text = FormatRangeReference(_session.SelectedRange);
    }

    private void DetachCellSelectionDragHandlers()
    {
        _sheetGridHost.PointerMoved -= CellSelectionCapturePointerMoved;
        _sheetGridHost.PointerReleased -= CellSelectionCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost -= CellSelectionCapturePointerCaptureLost;
    }

    private void ContinueCellSelectionDrag(PointerEventArgs args, CellAddress address)
    {
        if (_cellDragSelectionAnchor is not { } anchor ||
            !args.GetCurrentPoint(_sheetGridHost).Properties.IsLeftButtonPressed)
        {
            return;
        }

        RequestCellDragAutoScroll(args);

        var target = TryResolveCellPointerAddress(args, out var pointerAddress)
            ? pointerAddress
            : address;

        if (_selectionMoveDragging)
        {
            ContinueSelectionMoveDrag(args, target);
            return;
        }

        if (_autofillDragging)
        {
            ContinueAutofillDrag(args, target);
            return;
        }

        if (TryContinueFormulaRangeSelectionDrag(target))
        {
            args.Handled = true;
            return;
        }

        if (target == _selectionExtensionCursor)
            return;

        _selectionExtensionAnchor = anchor;
        _selectionExtensionCursor = target;
        SelectRangeFromAnchor(anchor, target);
        args.Handled = true;
    }

    // WPF's GridView requests one viewport step whenever a captured worksheet drag reaches an
    // edge. Keep this on the persistent grid host so it also applies while the per-cell controls
    // are rebuilt after each scroll step.
    private void RequestCellDragAutoScroll(PointerEventArgs args)
    {
        var bounds = _sheetGridHost.Bounds;
        if (bounds.Width <= 0 || bounds.Height <= 0)
            return;

        var zoomFactor = GetActiveZoomFactor();
        var rowHeaderWidth = _session.IsShowingHeadings
            ? GetRowHeaderWidth(_session.Viewport, zoomFactor)
            : 0;
        var columnHeaderHeight = _session.IsShowingHeadings
            ? GetColumnHeaderHeight(_session.Viewport, zoomFactor)
            : 0;
        var pointer = args.GetPosition(_sheetGridHost);
        var request = GridAutofillPlanner.CalculateEdgeScrollIntent(
            pointer.X,
            pointer.Y,
            bounds.Width,
            bounds.Height,
            rowHeaderWidth,
            columnHeaderHeight);
        if (request.HasAnyDirection)
            ApplyCellDragAutoScroll(request);
    }

    private void ApplyCellDragAutoScroll(GridAutoScrollRequest request)
    {
        var sheet = _session.ActiveSheet;
        var oldHorizontalMaximum = _horizontalWorksheetScrollBar.Maximum;
        var oldHorizontalValue = _horizontalWorksheetScrollBar.Value;
        var oldVerticalMaximum = _verticalWorksheetScrollBar.Maximum;
        var oldVerticalValue = _verticalWorksheetScrollBar.Value;

        _isUpdatingWorksheetScrollBars = true;
        try
        {
            if (request.HorizontalDirection != 0)
            {
                var (maximum, value) = WorkbookViewportScrollPlanner.CalculateDragAutoScroll(
                    _horizontalWorksheetScrollBar.Value,
                    _horizontalWorksheetScrollBar.Maximum,
                    request.HorizontalDirection,
                    step: 1,
                    _horizontalWorksheetScrollBar.ViewportSize,
                    WorkbookViewportScrollPlanner.GetScrollableColumnLimit(sheet));
                _horizontalWorksheetScrollBar.Maximum = maximum;
                _horizontalWorksheetScrollBar.Value = value;
            }

            if (request.VerticalDirection != 0)
            {
                var (maximum, value) = WorkbookViewportScrollPlanner.CalculateDragAutoScroll(
                    _verticalWorksheetScrollBar.Value,
                    _verticalWorksheetScrollBar.Maximum,
                    request.VerticalDirection,
                    step: 1,
                    _verticalWorksheetScrollBar.ViewportSize,
                    WorkbookViewportScrollPlanner.GetScrollableRowLimit(sheet));
                _verticalWorksheetScrollBar.Maximum = maximum;
                _verticalWorksheetScrollBar.Value = value;
            }
        }
        finally
        {
            _isUpdatingWorksheetScrollBars = false;
        }

        var changed =
            Math.Abs(_horizontalWorksheetScrollBar.Maximum - oldHorizontalMaximum) > 0.001 ||
            Math.Abs(_horizontalWorksheetScrollBar.Value - oldHorizontalValue) > 0.001 ||
            Math.Abs(_verticalWorksheetScrollBar.Maximum - oldVerticalMaximum) > 0.001 ||
            Math.Abs(_verticalWorksheetScrollBar.Value - oldVerticalValue) > 0.001;
        if (!changed)
            return;

        var (topRow, leftCol) = WorkbookViewportScrollPlanner.CalculateViewportOrigin(
            sheet,
            _verticalWorksheetScrollBar.Value,
            _horizontalWorksheetScrollBar.Value);
        if (_session.SetViewportOrigin(topRow, leftCol))
        {
            RefreshShellForViewportPan("Ready");
            BroadcastScrollOffsetToSideBySidePartner();
        }
    }

    /// <summary>
    /// Test-only seam for the production drag auto-scroll application path. The pointer lifecycle
    /// calls <see cref="RequestCellDragAutoScroll"/>; this seam lets headless tests exercise the
    /// same scrollbar, viewport-origin, and render-refresh behavior without fabricating native
    /// pointer-capture state.
    /// </summary>
    internal void RaiseCellDragAutoScrollForTest(GridAutoScrollRequest request) =>
        ApplyCellDragAutoScroll(request);

    private async Task EndCellSelectionDragAsync(PointerReleasedEventArgs args)
    {
        var formulaRangeEditor = GetFormulaRangeEntryEditor();
        if (_autofillDragging)
            CommitAutofillDrag(args.KeyModifiers.HasFlag(KeyModifiers.Control));
        else if (_selectionMoveDragging)
            await CommitSelectionMoveDragAsync(args.KeyModifiers.HasFlag(KeyModifiers.Control));

        DetachCellSelectionDragHandlers();
        _cellDragSelectionPointer?.Capture(null);
        _cellDragSelectionAnchor = null;
        _cellDragSelectionCapture = null;
        _cellDragSelectionPointer = null;
        _cellDragFormulaPointCursor = null;
        _cellDragFormulaReferenceStart = null;
        _cellDragFormulaReferenceLength = null;
        _selectionExtensionAnchor = null;
        _selectionExtensionCursor = null;
        _autofillDragging = false;
        _autofillSourceRange = null;
        _autofillTarget = null;
        _selectionMoveDragging = false;
        _selectionMoveSourceRange = null;
        _selectionMovePreviewRange = null;
        RevertNameBoxAfterCellSelectionDragEnd();
        RecordNameBoxDropdownPhysicalEvidence(item: null, stage: "neutral-cell-selected");

        // In Draw Border mode the drag-release triggers the border apply (mirrors WPF MouseUp behaviour).
        if (_borderDrawModeActive)
            ApplyBorderDrawMode();

        RestoreFormulaRangeEditorFocusAfterDrag(formulaRangeEditor);

        args.Handled = true;
    }

    private bool TryResolveCellPointerAddress(PointerEventArgs args, out CellAddress address)
    {
        address = default;
        var pos = args.GetPosition(_sheetGridHost);
        return TryResolveCellAddressFromSheetGridPosition(pos, out address);
    }

    private void BeginHeaderSelectionDrag(PointerPressedEventArgs args, Control capture, HeaderResizeKind kind, uint index)
    {
        if (_headerResizeDrag is not null)
            return;

        // Defensive: drop any stale subscriptions left over from a drag that lost capture without a
        // PointerReleased (grid rebuild, alt-tab, context menu), so we never double-subscribe.
        DetachHeaderSelectionDragHandlers();
        // Also defensively clear shared drag-state so a stranded header-drag cannot anchor a later drag.
        _cellDragSelectionAnchor = null;
        _cellDragSelectionCapture = null;
        _cellDragSelectionPointer = null;

        _cellDragSelectionAnchor = kind == HeaderResizeKind.Column
            ? new CellAddress(_session.ActiveSheet.Id, 1, index)
            : new CellAddress(_session.ActiveSheet.Id, index, 1);
        // Keep capture for Focus() — the per-header border is the right focus target.
        _cellDragSelectionCapture = capture;
        _cellDragSelectionPointer = args.Pointer;
        _headerSelectionDragKind = kind;
        _headerSelectionDragAnchorIndex = index;
        capture.Focus();
        // Capture on _sheetGridHost — the persistent host that SURVIVES RefreshShell/BuildSheetGrid,
        // so a ContinueHeaderSelectionDrag → SelectEntireColumn/Row → RefreshShell cannot
        // destroy the captured header Border and cause Avalonia to silently drop pointer capture.
        _sheetGridHost.PointerMoved += HeaderSelectionCapturePointerMoved;
        _sheetGridHost.PointerReleased += HeaderSelectionCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost += HeaderSelectionCapturePointerCaptureLost;
        args.Pointer.Capture(_sheetGridHost);
    }

    private void HeaderSelectionCapturePointerMoved(object? sender, PointerEventArgs args) =>
        ContinueHeaderSelectionDrag(args, _headerSelectionDragKind, _headerSelectionDragAnchorIndex);

    private void HeaderSelectionCapturePointerReleased(object? sender, PointerReleasedEventArgs args) =>
        EndHeaderSelectionDrag(args);

    // If the OS revokes pointer capture mid-drag (grid rebuild, alt-tab, focus loss, a context menu),
    // abort the drag and clear all drag state — mirrors the CellSelectionCapturePointerCaptureLost
    // and HeaderResizeCapturePointerCaptureLost cleanup pattern.
    private void HeaderSelectionCapturePointerCaptureLost(object? sender, PointerCaptureLostEventArgs args)
    {
        // Detach FIRST so the Capture(null) below cannot re-raise PointerCaptureLost back into
        // this handler (which would re-enter indefinitely and hang the app).
        DetachHeaderSelectionDragHandlers();
        _cellDragSelectionPointer?.Capture(null);
        _cellDragSelectionAnchor = null;
        _cellDragSelectionCapture = null;
        _cellDragSelectionPointer = null;
        _headerSelectionDragAnchorIndex = 0;
    }

    private void DetachHeaderSelectionDragHandlers()
    {
        _sheetGridHost.PointerMoved -= HeaderSelectionCapturePointerMoved;
        _sheetGridHost.PointerReleased -= HeaderSelectionCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost -= HeaderSelectionCapturePointerCaptureLost;
    }

    private void ContinueHeaderSelectionDrag(PointerEventArgs args, HeaderResizeKind kind, uint index)
    {
        if (_cellDragSelectionCapture is null ||
            !args.GetCurrentPoint(_sheetGridHost).Properties.IsLeftButtonPressed)
        {
            return;
        }

        if (kind == HeaderResizeKind.Column)
        {
            var targetCol = TryResolveColumnHeaderPointerIndex(args, out var col) ? col : index;
            SelectEntireColumnFromHeaderDrag(targetCol, _headerSelectionDragAnchorIndex);
        }
        else
        {
            var targetRow = TryResolveRowHeaderPointerIndex(args, out var row) ? row : index;
            SelectEntireRowFromHeaderDrag(targetRow, _headerSelectionDragAnchorIndex);
        }
        args.Handled = true;
    }

    private bool TryResolveColumnHeaderPointerIndex(PointerEventArgs args, out uint col)
    {
        col = 0;
        if (!_session.IsShowingHeadings)
            return false;

        var zoomFactor = GetActiveZoomFactor();
        var pos = args.GetPosition(_sheetGridHost);
        if (pos.Y < 0 || pos.Y > GetColumnHeaderHeight(_session.Viewport, zoomFactor))
            return false;

        var left = GetRowHeaderWidth(_session.Viewport, zoomFactor);
        foreach (var metric in CombineSplitColumnMetrics(_session.Viewport))
        {
            var right = left + GetDisplayedColumnWidth(metric, zoomFactor);
            if (pos.X >= left && pos.X <= right)
            {
                col = metric.Col;
                return true;
            }

            left = right;
        }

        return false;
    }

    private bool TryResolveRowHeaderPointerIndex(PointerEventArgs args, out uint row)
    {
        row = 0;
        if (!_session.IsShowingHeadings)
            return false;

        var zoomFactor = GetActiveZoomFactor();
        var pos = args.GetPosition(_sheetGridHost);
        if (pos.X < 0 || pos.X > GetRowHeaderWidth(_session.Viewport, zoomFactor))
            return false;

        var top = GetColumnHeaderHeight(_session.Viewport, zoomFactor);
        foreach (var metric in CombineSplitRowMetrics(_session.Viewport))
        {
            var bottom = top + GetDisplayedRowHeight(metric, zoomFactor);
            if (pos.Y >= top && pos.Y <= bottom)
            {
                row = metric.Row;
                return true;
            }

            top = bottom;
        }

        return false;
    }

    private bool TryResolveCellAddressFromSheetGridPosition(Point pos, out CellAddress address)
    {
        address = default;
        var sheet = _session.ActiveSheet;
        var zoomFactor = GetActiveZoomFactor();
        var left = sheet.ShowHeadings ? GetRowHeaderWidth(_session.Viewport, zoomFactor) : 0;
        var top = sheet.ShowHeadings ? GetColumnHeaderHeight(_session.Viewport, zoomFactor) : 0;

        if (pos.X < left || pos.Y < top)
            return false;

        uint? col = null;
        var currentLeft = left;
        foreach (var metric in CombineSplitColumnMetrics(_session.Viewport))
        {
            var right = currentLeft + GetDisplayedColumnWidth(metric, zoomFactor);
            if (pos.X >= currentLeft && pos.X <= right)
            {
                col = metric.Col;
                break;
            }

            currentLeft = right;
        }

        if (!col.HasValue)
            return false;

        uint? row = null;
        var currentTop = top;
        foreach (var metric in CombineSplitRowMetrics(_session.Viewport))
        {
            var bottom = currentTop + GetDisplayedRowHeight(metric, zoomFactor);
            if (pos.Y >= currentTop && pos.Y <= bottom)
            {
                row = metric.Row;
                break;
            }

            currentTop = bottom;
        }

        if (!row.HasValue)
            return false;

        address = new CellAddress(sheet.Id, row.Value, col.Value);
        return true;
    }

    private void EndHeaderSelectionDrag(PointerReleasedEventArgs args)
    {
        if (_cellDragSelectionCapture is not null)
        {
            DetachHeaderSelectionDragHandlers();
            _cellDragSelectionPointer?.Capture(null);
            _cellDragSelectionCapture = null;
            _cellDragSelectionAnchor = null;
            _cellDragSelectionPointer = null;
            _headerSelectionDragAnchorIndex = 0;
            args.Handled = true;
        }
    }

    private void SelectRangeFromAnchor(CellAddress anchor, CellAddress address)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        ClearSelectedDrawingObject();
        // Pin the active cell to `anchor` (the pressed cell) rather than the range's normalized
        // top-left, so a drag that ran up/left keeps the active cell at the true starting corner --
        // which View > Split / Freeze Panes read after the gesture ends (split-creation-selection-anchor).
        _session.SelectAnchoredRange(anchor, address);
        RefreshShell(UiText.Format("MainLoc_SelectedX", FormatRangeReference(_session.SelectedRange)));
        // While a mouse-drag selection is in progress (this method is only ever invoked from
        // ContinueCellSelectionDrag), Excel's Name Box shows a live "{rows}R x {cols}C" dimension
        // readout instead of the range address, reverting to the address once the drag ends (see
        // EndCellSelectionDragAsync/CellSelectionCapturePointerCaptureLost) -- mirrors the WPF
        // host's ExtendSelection (R69-render-active-cell-selection-6-2).
        if (!_cellAddressBoxHasPendingEdit)
        {
            _cellAddressText.Text = FormatDragSelectionDimensionText(_session.SelectedRange);
            _cellSelectionDragShowedDimensionText = true;
        }
        RefreshTableContextualTab();
        ApplyFormatPainterAfterTargetSelection();
    }

    private Control AddColumnResizeHandle(Border header, uint col, ColMetric metric, double zoomFactor)
    {
        var handle = CreateHeaderResizeHandle(HeaderResizeKind.Column);
        handle.PointerPressed += (_, args) => BeginHeaderResize(args, handle, HeaderResizeKind.Column, col, GetDisplayedColumnWidth(metric, zoomFactor));
        handle.PointerMoved += (_, args) => ContinueHeaderResize(args);
        handle.PointerReleased += (_, args) => CommitHeaderResize(args);
        handle.DoubleTapped += (_, args) =>
        {
            AutoFitColumnFromHeader(col);
            args.Handled = true;
        };
        return CreateHeaderWithResizeHandle(header, handle);
    }

    private Control AddRowResizeHandle(Border header, uint row, RowMetric metric, double zoomFactor)
    {
        var handle = CreateHeaderResizeHandle(HeaderResizeKind.Row);
        handle.PointerPressed += (_, args) => BeginHeaderResize(args, handle, HeaderResizeKind.Row, row, GetDisplayedRowHeight(metric, zoomFactor));
        handle.PointerMoved += (_, args) => ContinueHeaderResize(args);
        handle.PointerReleased += (_, args) => CommitHeaderResize(args);
        handle.DoubleTapped += (_, args) =>
        {
            AutoFitRowFromHeader(row);
            args.Handled = true;
        };
        return CreateHeaderWithResizeHandle(header, handle);
    }

    private static Border CreateHeaderResizeHandle(HeaderResizeKind kind) =>
        new()
        {
            Width = kind == HeaderResizeKind.Column ? HeaderResizeHitThickness : double.NaN,
            Height = kind == HeaderResizeKind.Row ? HeaderResizeHitThickness : double.NaN,
            Background = Brushes.Transparent,
            HorizontalAlignment = kind == HeaderResizeKind.Column ? AvaloniaHorizontalAlignment.Right : AvaloniaHorizontalAlignment.Stretch,
            VerticalAlignment = kind == HeaderResizeKind.Row ? AvaloniaVerticalAlignment.Bottom : AvaloniaVerticalAlignment.Stretch,
            Cursor = new Cursor(kind == HeaderResizeKind.Column ? StandardCursorType.SizeWestEast : StandardCursorType.SizeNorthSouth),
        };

    private static AvaloniaGrid CreateHeaderWithResizeHandle(Border header, Border handle) =>
        new()
        {
            Children = { header, handle },
        };

    private void BeginHeaderResize(PointerPressedEventArgs args, Control capture, HeaderResizeKind kind, uint index, double displayedSize)
    {
        var point = args.GetCurrentPoint(capture);
        if (!point.Properties.IsLeftButtonPressed || args.KeyModifiers.HasFlag(KeyModifiers.Control))
            return;

        var sheet = _session.ActiveSheet;
        var pointer = kind == HeaderResizeKind.Column
            ? args.GetPosition(this).X
            : args.GetPosition(this).Y;
        // Dragging a header border resizes every row/column in a pre-existing multi-area
        // selection that spans `index`, not just the one header under the pointer -- matching
        // Excel and the WPF host's GridResizePreviewPlanner.GetColumnResizeRange/
        // GetRowResizeRange (R84-app-mouse-selection-5-2).
        var (startIndex, endIndex) = kind == HeaderResizeKind.Column
            ? GridResizePreviewPlanner.GetColumnResizeRange(sheet, _session.SelectedRange, index)
            : GridResizePreviewPlanner.GetRowResizeRange(sheet, _session.SelectedRange, index);
        var snapshot = kind == HeaderResizeKind.Column
            ? GridResizePreviewPlanner.CaptureColumnSnapshot(sheet, startIndex, endIndex)
            : GridResizePreviewPlanner.CaptureRowSnapshot(sheet, startIndex, endIndex);
        // Defensive: drop any stale subscription left over from a drag that lost capture without a
        // PointerReleased, so we never double-subscribe (which would run Continue/Commit twice per event).
        DetachHeaderResizeCaptureHandlers();
        _headerResizeDrag = new HeaderResizeDrag(kind, index, startIndex, endIndex, _sheetGridHost, args.Pointer, pointer, displayedSize, snapshot);
        _sheetGridHost.PointerMoved += HeaderResizeCapturePointerMoved;
        _sheetGridHost.PointerReleased += HeaderResizeCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost += HeaderResizeCapturePointerCaptureLost;
        args.Pointer.Capture(_sheetGridHost);
        args.Handled = true;
    }

    private void HeaderResizeCapturePointerMoved(object? sender, PointerEventArgs args) =>
        ContinueHeaderResize(args);

    private void HeaderResizeCapturePointerReleased(object? sender, PointerReleasedEventArgs args) =>
        CommitHeaderResize(args);

    // If the OS revokes pointer capture mid-drag (alt-tab, focus loss, a context menu), abort the resize
    // and restore the original size — mirrors the chart-drag PointerCaptureLost cleanup. Without this the
    // capture handlers stay subscribed and _headerResizeDrag stays set.
    private void HeaderResizeCapturePointerCaptureLost(object? sender, PointerCaptureLostEventArgs args)
    {
        // Detach FIRST so the Capture(null) inside CancelHeaderResizePreview cannot re-raise
        // PointerCaptureLost back into this handler (which would re-enter the cancel path indefinitely).
        DetachHeaderResizeCaptureHandlers();
        if (_headerResizeDrag is not null)
            CancelHeaderResizePreview();
    }

    private void ContinueHeaderResize(PointerEventArgs args)
    {
        if (_headerResizeDrag is not { } drag)
            return;

        var point = args.GetCurrentPoint(drag.Capture);
        if (!point.Properties.IsLeftButtonPressed)
        {
            CancelHeaderResizePreview();
            return;
        }

        var pointer = drag.Kind == HeaderResizeKind.Column
            ? args.GetPosition(this).X
            : args.GetPosition(this).Y;
        var requestedSize = drag.StartSize + pointer - drag.StartPointer;
        var clampedSize = drag.Kind == HeaderResizeKind.Column
            ? GridResizeSizePlanner.ClampColumnSize(requestedSize)
            : GridResizeSizePlanner.ClampRowSize(requestedSize);
        PreviewHeaderResize(drag, clampedSize);
        args.Handled = true;
    }

    private void CommitHeaderResize(PointerReleasedEventArgs args)
    {
        if (_headerResizeDrag is not { } drag)
            return;

        var pointer = drag.Kind == HeaderResizeKind.Column
            ? args.GetPosition(this).X
            : args.GetPosition(this).Y;
        var requestedSize = drag.StartSize + pointer - drag.StartPointer;
        var clampedSize = drag.Kind == HeaderResizeKind.Column
            ? GridResizeSizePlanner.ClampColumnSize(requestedSize)
            : GridResizeSizePlanner.ClampRowSize(requestedSize);

        RestoreHeaderResizeOriginal(drag);
        // Detach BEFORE releasing capture: drag.Pointer.Capture(null) synchronously raises
        // PointerCaptureLost, which would otherwise re-enter HeaderResizeCapturePointerCaptureLost (it sees
        // _headerResizeDrag still set) and run CancelHeaderResizePreview mid-commit/cancel.
        DetachHeaderResizeCaptureHandlers();
        _headerResizeDrag = null;
        drag.Pointer.Capture(null);

        if (drag.Kind == HeaderResizeKind.Column)
        {
            var result = _session.ExecuteReviewCommand(
                new SetColumnWidthCommand(
                    _session.ActiveSheet.Id,
                    drag.StartIndex,
                    drag.EndIndex,
                    ColumnWidthPixelMapper.PixelsToColumnWidth(clampedSize)),
                _session.ActiveCell);
            RefreshShell(result.Success
                ? UiText.Format("RowColumn_ColumnWidthApplied", FormatDimension(ColumnWidthPixelMapper.PixelsToColumnWidth(clampedSize)))
                : result.ErrorMessage ?? UiText.Get("RowColumn_ColumnWidthFailed"));
        }
        else
        {
            var result = _session.ExecuteReviewCommand(
                new SetRowHeightCommand(
                    _session.ActiveSheet.Id,
                    drag.StartIndex,
                    drag.EndIndex,
                    clampedSize),
                _session.ActiveCell);
            RefreshShell(result.Success
                ? UiText.Format("RowColumn_RowHeightApplied", FormatDimension(clampedSize))
                : result.ErrorMessage ?? UiText.Get("RowColumn_RowHeightFailed"));
        }

        args.Handled = true;
    }

    private void PreviewHeaderResize(HeaderResizeDrag drag, double clampedSize)
    {
        if (drag.Kind == HeaderResizeKind.Column)
            GridResizePreviewPlanner.ApplyColumnResizePreview(_session.ActiveSheet, drag.StartIndex, drag.EndIndex, clampedSize);
        else
            GridResizePreviewPlanner.ApplyRowResizePreview(_session.ActiveSheet, drag.StartIndex, drag.EndIndex, clampedSize);

        RefreshShell(UiText.Format("MainLoc_SelectedX", FormatRangeReference(_session.SelectedRange)));
    }

    private void CancelHeaderResizePreview()
    {
        if (_headerResizeDrag is not { } drag)
            return;

        RestoreHeaderResizeOriginal(drag);
        // Detach BEFORE releasing capture: drag.Pointer.Capture(null) synchronously raises
        // PointerCaptureLost, which would otherwise re-enter HeaderResizeCapturePointerCaptureLost (it sees
        // _headerResizeDrag still set) and run CancelHeaderResizePreview mid-commit/cancel.
        DetachHeaderResizeCaptureHandlers();
        _headerResizeDrag = null;
        drag.Pointer.Capture(null);
        RefreshShell(UiText.Format("MainLoc_SelectedX", FormatRangeReference(_session.SelectedRange)));
    }

    private void DetachHeaderResizeCaptureHandlers()
    {
        _sheetGridHost.PointerMoved -= HeaderResizeCapturePointerMoved;
        _sheetGridHost.PointerReleased -= HeaderResizeCapturePointerReleased;
        _sheetGridHost.PointerCaptureLost -= HeaderResizeCapturePointerCaptureLost;
    }

    private void RestoreHeaderResizeOriginal(HeaderResizeDrag drag)
    {
        if (drag.Kind == HeaderResizeKind.Column)
            GridResizePreviewPlanner.RestoreColumnResizePreview(_session.ActiveSheet, drag.Snapshot);
        else
            GridResizePreviewPlanner.RestoreRowResizePreview(_session.ActiveSheet, drag.Snapshot);
    }

    // Double-clicking a column header's resize border autofits the whole current selection's
    // column band when `col` falls inside a pre-existing multi-column selection, matching Excel
    // and the WPF host's OnColumnAutoFitRequested (GridResizePreviewPlanner.
    // GetSelectedColumnResizeRange) -- rather than collapsing that selection down to just `col`
    // first, which destroyed the multi-column selection before autofitting only `col`
    // (R84-app-mouse-selection-5-2).
    private void AutoFitColumnFromHeader(uint col)
    {
        var (startCol, endCol) = GridResizePreviewPlanner.GetSelectedColumnResizeRange(_session.SelectedRange, col);
        if (startCol != endCol)
        {
            var wideRange = SelectionRangeService.GetWholeColumns(new GridRange(
                new CellAddress(_session.ActiveSheet.Id, 1, startCol),
                new CellAddress(_session.ActiveSheet.Id, 1, endCol)));
            _session.SelectRange(wideRange);
        }
        else
        {
            SelectEntireColumn(col);
        }

        AutoFitSelectedColumnWidth();
    }

    /// <summary>Row-header counterpart of <see cref="AutoFitColumnFromHeader"/>.</summary>
    private void AutoFitRowFromHeader(uint row)
    {
        var (startRow, endRow) = GridResizePreviewPlanner.GetSelectedRowResizeRange(_session.SelectedRange, row);
        if (startRow != endRow)
        {
            var wideRange = SelectionRangeService.GetWholeRows(new GridRange(
                new CellAddress(_session.ActiveSheet.Id, startRow, 1),
                new CellAddress(_session.ActiveSheet.Id, endRow, 1)));
            _session.SelectRange(wideRange);
        }
        else
        {
            SelectEntireRow(row);
        }

        AutoFitSelectedRowHeight();
    }

    private bool TryBeginAutofillDrag(PointerPressedEventArgs args, Control capture, CellAddress address)
    {
        if (!EnableFillHandleAndCellDragAndDrop)
            return false;

        if (!args.GetCurrentPoint(capture).Properties.IsLeftButtonPressed ||
            !IsPointerOnAutofillHandle(args))
        {
            return false;
        }

        var source = _session.SelectedRange;

        // Excel's double-click-fill-handle gesture: extend straight down to match the populated
        // extent of the nearest non-blank adjacent column, matching the WPF host's
        // OnAutofillHandleDoubleClicked (MainWindow.xaml.cs). Handled immediately -- no drag starts.
        if (args.ClickCount >= 2)
        {
            CommitAutofillHandleDoubleClick(source);
            return true;
        }

        BeginCellSelectionDrag(args, capture, source.Start);
        // BeginCellSelectionDrag clears stale gesture state before establishing persistent pointer
        // capture, so arm autofill only after capture has been initialized.
        _autofillDragging = true;
        _autofillSourceRange = source;
        _autofillTarget = source.End;
        return true;
    }

    /// <summary>
    /// Handles a fill-handle double-click: fill straight down to match the populated extent of the
    /// nearest non-blank adjacent column (checked to the left first, then the right, matching
    /// Excel), stopping at the first blank row below the source. Mirrors the Windows host's
    /// autofill-handle double-click handler.
    /// </summary>
    private void CommitAutofillHandleDoubleClick(GridRange source)
    {
        var adjacentLastRow = ResolveAutofillAdjacentColumnLastPopulatedRow(_session.ActiveSheet, source);
        var fillRange = GridAutofillPlanner.CalculateDoubleClickFillRange(source, adjacentLastRow);
        if (fillRange is null)
            return;

        var completedSelection = GridAutofillPlanner.CalculateCompletedSelectionRange(source, fillRange.Value);
        ClearSelectedDrawingObject();
        var result = _session.AutofillDragRange(source, fillRange.Value, ctrlHeld: false);
        _session.SelectRange(completedSelection);
        RefreshShell(result.Success
            ? $"Autofilled {FormatRangeReference(completedSelection)}"
            : result.ErrorMessage ?? "Autofill failed.");
    }

    /// <summary>
    /// Finds the last populated row of the contiguous data run in the column immediately to the
    /// left of <paramref name="source"/> (checked first) or immediately to the right, starting
    /// from the row below the source's seed row and stopping at the first blank cell. Returns null
    /// when neither neighbor has any data immediately below the seed row.
    /// </summary>
    private static uint? ResolveAutofillAdjacentColumnLastPopulatedRow(Sheet sheet, GridRange source)
    {
        var seedRow = source.Start.Row;
        if (source.Start.Col > 1 &&
            ResolveAutofillColumnLastPopulatedRow(sheet, source.Start.Col - 1, seedRow) is { } leftRow)
        {
            return leftRow;
        }

        return ResolveAutofillColumnLastPopulatedRow(sheet, source.End.Col + 1, seedRow);
    }

    private static uint? ResolveAutofillColumnLastPopulatedRow(Sheet sheet, uint column, uint seedRow)
    {
        if (column > CellAddress.MaxCol || seedRow >= CellAddress.MaxRow)
            return null;

        if (sheet.GetValue(seedRow + 1, column) is BlankValue)
            return null;

        var lastRow = seedRow + 1;
        while (lastRow < CellAddress.MaxRow && sheet.GetValue(lastRow + 1, column) is not BlankValue)
            lastRow++;

        return lastRow;
    }

    private bool IsPointerOnAutofillHandle(PointerEventArgs args)
    {
        if (!EnableFillHandleAndCellDragAndDrop)
            return false;

        if (_autofillHandleVisual is not { } handle)
            return false;

        var size = handle.Bounds.Width > 0 ? handle.Bounds.Width : handle.Width;
        if (size <= 0)
            return false;

        var pos = args.GetPosition(handle);
        var hitPadding = Math.Max(
            AutofillHandleHitPadding,
            AutofillHandleHitPadding * GetActiveZoomFactor());
        return GridAutofillPlanner.IsOnHandle(
            new GridSelectionLayout(
                new GridRect(-(size / 2), -(size / 2), size, size),
                HasTopEdge: true,
                HasLeftEdge: true,
                HasBottomEdge: true,
                HasRightEdge: true),
            new GridPoint(pos.X, pos.Y),
            handleSize: size,
            hitPadding: hitPadding);
    }

    private void ContinueAutofillDrag(PointerEventArgs args, CellAddress target)
    {
        if (_autofillSourceRange is null)
            return;

        ContinueAutofillDragCore(target);
        args.Handled = true;
    }

    /// <summary>
    /// Core continuation logic shared by <see cref="ContinueAutofillDrag"/> and the test-only
    /// seam <see cref="RaiseContinueAutofillDragForTest"/>: updates <see cref="_autofillTarget"/>
    /// and, when it actually changed, rebuilds the grid so AddAutofillPreviewOverlayToGrid repaints
    /// the dashed preview rectangle at the new target -- mirrors the WPF host's InvalidateVisual
    /// call on every pointer move in GridView.Input.cs (Avalonia has no DrawingContext repaint
    /// here, so a targeted grid-content rebuild is the equivalent live-preview mechanism; see
    /// RefreshShellForGridPreview's doc comment for why this is scoped down from RefreshShell).
    /// </summary>
    private void ContinueAutofillDragCore(CellAddress target)
    {
        if (_autofillSourceRange is not { } source)
            return;

        var constrainedTarget = GridAutofillPlanner.ConstrainTarget(source, target);
        if (constrainedTarget == _autofillTarget)
            return;

        _autofillTarget = constrainedTarget;
        RefreshShellForGridPreview();
    }

    /// <summary>
    /// Test-only seam that drives the real fill-handle drag CONTINUATION path
    /// (ContinueAutofillDragCore) directly, bypassing pointer capture, so headless tests can
    /// assert the live drag-preview overlay appears mid-drag -- distinct from the pre-existing
    /// <see cref="RaiseAutofillDragForTest"/>, which only exercises the post-release commit path.
    /// Not used by production code paths.
    /// </summary>
    internal void RaiseContinueAutofillDragForTest(GridRange source, CellAddress target)
    {
        _autofillDragging = true;
        _autofillSourceRange = source;
        ContinueAutofillDragCore(target);
    }

    private void CommitAutofillDrag(bool ctrlHeld = false)
    {
        if (_autofillSourceRange is not { } source ||
            _autofillTarget is not { } target ||
            (GridAutofillPlanner.CalculateFillRange(source, target) ??
             GridAutofillPlanner.CalculateClearRange(source, target)) is not { } operationRange)
        {
            return;
        }

        var completedSelection = GridAutofillPlanner.CalculateCompletedSelectionRange(source, operationRange);
        ClearSelectedDrawingObject();
        // Unlike keyboard/menu Fill Down/Up/Left/Right (FillSelectedRange, which verbatim-copies
        // the source edge cell), the fill-handle drag gesture runs Excel-style series detection
        // (numeric/date linear-fit trend, list series) via AutofillCommand - mirroring the WPF
        // host's OnAutofillRequested. Holding Ctrl while dragging flips the fill behavior (forces
        // a plain copy of the last value instead of continuing the series, or forces an
        // increment-by-1 series for a single plain number), matching Excel/the WPF host.
        var result = _session.AutofillDragRange(source, operationRange, ctrlHeld);
        _session.SelectRange(completedSelection);
        RefreshShell(result.Success
            ? $"Autofilled {FormatRangeReference(completedSelection)}"
            : result.ErrorMessage ?? "Autofill failed.");
    }

    /// <summary>
    /// Test-only seam that drives the real fill-handle drag commit path (source/target set directly
    /// instead of via pointer capture), so headless tests can assert on the resulting cell
    /// values/formulas without simulating pointer input. Not used by production code paths.
    /// </summary>
    internal void RaiseAutofillDragForTest(GridRange source, CellAddress target, bool ctrlHeld = false)
    {
        _autofillSourceRange = source;
        _autofillTarget = target;
        CommitAutofillDrag(ctrlHeld);
    }

    /// <summary>
    /// Test-only seam that drives the real fill-handle double-click commit path directly (instead
    /// of simulating a double-click <see cref="PointerPressedEventArgs"/>), so headless tests can
    /// assert on the resulting cell values without constructing pointer input. Not used by
    /// production code paths.
    /// </summary>
    internal void RaiseAutofillHandleDoubleClickForTest(GridRange source) =>
        CommitAutofillHandleDoubleClick(source);

    private static FillCellsDirection ResolveAutofillDirection(GridRange source, GridRange fillRange)
    {
        if (fillRange.Start.Row > source.End.Row)
            return FillCellsDirection.Down;
        if (fillRange.End.Row < source.Start.Row)
            return FillCellsDirection.Up;
        if (fillRange.Start.Col > source.End.Col)
            return FillCellsDirection.Right;
        return FillCellsDirection.Left;
    }

    private bool TryBeginSelectionMoveDrag(PointerPressedEventArgs args, Control capture, CellAddress address)
    {
        if (!EnableFillHandleAndCellDragAndDrop)
            return false;

        // Excel's Ctrl+drag-to-copy gesture: holding Ctrl while dragging a selection's border
        // copies it to the destination instead of moving it (M33). The actual copy-vs-move
        // decision is resolved from the drop-time modifier state in EndCellSelectionDragAsync,
        // not here — the user may press/release Ctrl mid-drag, exactly like the existing
        // autofill-drag Ctrl handling.
        if (!args.GetCurrentPoint(capture).Properties.IsLeftButtonPressed ||
            (args.KeyModifiers != KeyModifiers.None && args.KeyModifiers != KeyModifiers.Control) ||
            !IsPointerOnSelectionMoveBorder(args) ||
            _session.SelectedRanges.Count > 1)
        {
            return false;
        }

        var source = _session.SelectedRange;
        var startCell = GridSelectionMovePlanner.ClampDragStartCell(source, address);
        BeginCellSelectionDrag(args, capture, source.Start);
        // BeginCellSelectionDrag clears stale gesture state before establishing persistent pointer
        // capture, so arm move/copy only after capture has been initialized.
        _selectionMoveDragging = true;
        _selectionMoveSourceRange = source;
        _selectionMoveStartCell = startCell;
        _selectionMovePreviewRange = source;
        return true;
    }

    private bool IsPointerOnSelectionMoveBorder(PointerEventArgs args)
    {
        if (!EnableFillHandleAndCellDragAndDrop)
            return false;

        if (IsPointerOnAutofillHandle(args))
            return false;

        if (_activeSelectionOutlineVisual is not { } outline ||
            outline.Bounds.Width <= 0 ||
            outline.Bounds.Height <= 0)
        {
            return false;
        }

        var pos = args.GetPosition(outline);
        var zoomFactor = GetActiveZoomFactor();
        var layout = new GridSelectionLayout(
            new GridRect(0, 0, outline.Bounds.Width, outline.Bounds.Height),
            _activeSelectionHasTopEdge,
            _activeSelectionHasLeftEdge,
            _activeSelectionHasBottomEdge,
            _activeSelectionHasRightEdge);
        return GridSelectionMovePlanner.IsOnMoveBorder(
            layout,
            _session.SelectedRanges.Count > 1 ? _session.SelectedRanges : null,
            new GridPoint(pos.X, pos.Y),
            handleSize: Math.Max(AutofillHandleSize, AutofillHandleSize * zoomFactor),
            handleHitPadding: Math.Max(AutofillHandleHitPadding, AutofillHandleHitPadding * zoomFactor));
    }

    private void ContinueSelectionMoveDrag(PointerEventArgs args, CellAddress target)
    {
        if (_selectionMoveSourceRange is null)
            return;

        ContinueSelectionMoveDragCore(target);
        args.Handled = true;
    }

    /// <summary>
    /// Core continuation logic shared by <see cref="ContinueSelectionMoveDrag"/> and the test-only
    /// seam <see cref="RaiseContinueSelectionMoveDragForTest"/>: updates
    /// <see cref="_selectionMovePreviewRange"/> and, when it actually changed, rebuilds the grid so
    /// AddSelectionMovePreviewOverlayToGrid repaints the destination outline live -- mirrors the
    /// WPF host's InvalidateVisual call in UpdateSelectionMovePreview.
    /// </summary>
    private void ContinueSelectionMoveDragCore(CellAddress target)
    {
        if (_selectionMoveSourceRange is not { } source ||
            GridSelectionMovePlanner.CalculateTargetRange(source, _selectionMoveStartCell, target) is not { } targetRange)
        {
            return;
        }

        if (targetRange.Equals(_selectionMovePreviewRange))
            return;

        _selectionMovePreviewRange = targetRange;
        RefreshShellForGridPreview();
    }

    /// <summary>
    /// Test-only seam that drives the real selection-border-move drag CONTINUATION path
    /// (ContinueSelectionMoveDragCore) directly, bypassing pointer capture, so headless tests can
    /// assert the live drag-preview overlay appears mid-drag -- distinct from the pre-existing
    /// <see cref="RaiseSelectionMoveDragForTest"/>, which only exercises the post-release commit
    /// path. Not used by production code paths.
    /// </summary>
    internal void RaiseContinueSelectionMoveDragForTest(GridRange source, CellAddress startCell, CellAddress target)
    {
        _selectionMoveDragging = true;
        _selectionMoveSourceRange = source;
        _selectionMoveStartCell = startCell;
        _selectionMovePreviewRange = source;
        ContinueSelectionMoveDragCore(target);
    }

    /// <summary>
    /// Test-only seam that drives the real border-drag-move commit path (source/target range set
    /// directly instead of via pointer capture), so headless tests can assert on the resulting cell
    /// values and on whether the overwrite confirmation was consulted. Not used by production code
    /// paths.
    /// </summary>
    internal Task RaiseSelectionMoveDragForTest(GridRange source, GridRange target, bool ctrlHeld = false)
    {
        _selectionMoveSourceRange = source;
        _selectionMovePreviewRange = target;
        return CommitSelectionMoveDragAsync(ctrlHeld);
    }

    private async Task CommitSelectionMoveDragAsync(bool ctrlHeld = false)
    {
        if (_selectionMoveSourceRange is not { } source ||
            _selectionMovePreviewRange is not { } target ||
            source == target)
        {
            return;
        }

        // Mirrors the WPF host's OnSelectionMoveRequested: dropping a border-dragged range onto
        // cells that already have content must prompt before overwriting them, matching Excel.
        if (SelectionMoveOverwritePlanner.HasOverwriteTargets(_session.ActiveSheet, source, target) &&
            !await (ConfirmSelectionMoveOverwriteOverrideForTest?.Invoke() ?? ConfirmSelectionMoveOverwriteAsync()))
        {
            return;
        }

        ClearSelectedDrawingObject();

        if (ctrlHeld)
        {
            // Excel's Ctrl+drag-to-copy: write the payload at the destination and leave the
            // source range untouched (M33), unlike a plain border drag which moves it.
            var copyResult = _session.ExecuteReviewCommand(
                new CopyRangeCommand(_session.ActiveSheet.Id, source, target.Start),
                fallbackAddress: target.Start);
            var copyStatus = copyResult.Success
                ? UiText.Format("MainLoc_SelectedX", FormatRangeReference(target))
                : copyResult.ErrorMessage ?? "Copy Cells failed.";
            // ExecuteReviewCommand intentionally collapses the session selection to the first
            // affected cell while applying a generic edit. Render that intermediate state, then
            // restore the complete destination range and rebuild the grid once more. Without the
            // second selection pass Avalonia can leave the visible marquee on the source range
            // even though the copy payload and session active cell have reached the destination.
            RefreshShell(copyStatus);
            if (copyResult.Success)
            {
                _session.SelectRange(target);
                RefreshShell(copyStatus);
            }
            return;
        }

        var result = _session.MoveSelectedRangeTo(source, target);
        RefreshShell(result.Success
            ? UiText.Format("MainLoc_SelectedX", FormatRangeReference(target))
            : result.ErrorMessage ?? "Move Cells failed.");
    }

    /// <summary>
    /// Yes/No confirmation shown before a border-drag range move would overwrite existing
    /// destination cell contents (mirrors WPF's <c>_messageService.AskYesNo</c> prompt using the
    /// shared "There's already data here. Do you want to replace it?" string).
    /// </summary>
    private async Task<bool> ConfirmSelectionMoveOverwriteAsync()
    {
        var dialog = new Window
        {
            Title = "Confirm",
            Width = 420,
            Height = 180,
            MinWidth = 380,
            MinHeight = 170,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var detailText = new TextBlock
        {
            Text = UiText.Get("MainWindowMessage_TextToColumnsReplaceDataPrompt"),
            TextWrapping = TextWrapping.Wrap,
        };

        var yesButton = new Button { Content = "Yes", MinWidth = 92, Padding = new Thickness(10, 4), IsDefault = true };
        AutomationProperties.SetAutomationId(yesButton, "SelectionMoveOverwriteYesButton");
        AutomationProperties.SetName(yesButton, "Yes");

        var noButton = new Button { Content = "No", MinWidth = 92, Padding = new Thickness(10, 4), IsCancel = true };
        AutomationProperties.SetAutomationId(noButton, "SelectionMoveOverwriteNoButton");
        AutomationProperties.SetName(noButton, "No");

        var confirmed = false;
        void Finish(bool value)
        {
            confirmed = value;
            dialog.Close();
        }

        yesButton.Click += (_, _) => Finish(true);
        noButton.Click += (_, _) => Finish(false);
        dialog.Opened += (_, _) => noButton.Focus();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Escape)
            {
                Finish(false);
                e.Handled = true;
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children = { noButton, yesButton },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(18),
            Spacing = 12,
            Children = { detailText, new Border { Height = 10 }, buttonRow },
        };

        await dialog.ShowDialog(this);
        return confirmed;
    }

    /// <summary>
    /// Test-only override for <see cref="ResolveDataValidationPrompt"/> -- headless tests inject a
    /// canned decision here instead of driving the real <see cref="ShowDataValidationPromptDialog"/>
    /// window. Not used by production code paths.
    /// </summary>
    internal Func<DataValidationPromptRequest, UserMessageResult>? DataValidationPromptOverrideForTest;

    /// <summary>
    /// Wired to <see cref="WorkbookSession.DataValidationPromptResolver"/> after every
    /// <c>_session</c> (re)assignment so a Warning/Information ("AskToContinue") data-validation
    /// alert gets a real owned dialog on this shell (R73-dv-warning-info-avalonia), mirroring the
    /// WPF host's <c>IUserMessageService.ShowMessage</c> prompt in
    /// <c>MainWindow.Editing.TryCreateCellFromEntryText</c>.
    /// </summary>
    private UserMessageResult ResolveDataValidationPrompt(DataValidationPromptRequest request) =>
        DataValidationPromptOverrideForTest?.Invoke(request) ?? ShowDataValidationPromptDialog(request);

    /// <summary>
    /// Owned modal alert for a Warning/Information data-validation violation, mirroring the WPF
    /// host's <c>ShowOwnedMessage</c> button sets: Warning offers Yes/No/Cancel (Yes commits the
    /// invalid entry, No leaves it in the editor to fix, Cancel discards it); Information offers
    /// OK/Cancel (OK commits, Cancel discards). <see cref="WorkbookSession.CommitCellText"/> calls
    /// <see cref="ResolveDataValidationPrompt"/> synchronously, so -- unlike every other owned
    /// dialog on this shell, which is awaited via <c>await dialog.ShowDialog(this)</c> -- this one
    /// is shown non-modally and the calling (UI) thread drains the dispatcher queue until it
    /// closes, since Avalonia has no synchronous nested-pump equivalent to WPF's blocking
    /// <c>MessageBox.Show</c>. The owner window is disabled for the duration to emulate modal
    /// blocking.
    /// </summary>
    private UserMessageResult ShowDataValidationPromptDialog(DataValidationPromptRequest request)
    {
        var isInformation = request.AlertStyle == DvAlertStyle.Information;
        var dialog = new Window
        {
            Title = request.Title,
            Width = 420,
            SizeToContent = SizeToContent.Height,
            MinHeight = 150,
            CanResize = false,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var messageText = new TextBlock
        {
            Text = request.Message,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(16, 16, 16, 20),
        };

        var decision = UserMessageResult.Cancel;
        var done = false;
        void Finish(UserMessageResult value)
        {
            decision = value;
            done = true;
            dialog.Close();
        }

        Button MakeButton(string content, UserMessageResult value, bool isDefault, bool isCancel)
        {
            var button = new Button
            {
                Content = content,
                MinWidth = 82,
                IsDefault = isDefault,
                IsCancel = isCancel,
                Margin = new Thickness(8, 0, 0, 0),
            };
            button.Click += (_, _) => Finish(value);
            return button;
        }

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(16, 0, 16, 16),
        };

        Button defaultButton;
        if (isInformation)
        {
            defaultButton = MakeButton("OK", UserMessageResult.Ok, isDefault: true, isCancel: false);
            buttonRow.Children.Add(defaultButton);
            buttonRow.Children.Add(MakeButton("Cancel", UserMessageResult.Cancel, isDefault: false, isCancel: true));
        }
        else
        {
            defaultButton = MakeButton("Yes", UserMessageResult.Yes, isDefault: true, isCancel: false);
            buttonRow.Children.Add(defaultButton);
            buttonRow.Children.Add(MakeButton("No", UserMessageResult.No, isDefault: false, isCancel: false));
            buttonRow.Children.Add(MakeButton("Cancel", UserMessageResult.Cancel, isDefault: false, isCancel: true));
        }

        dialog.Content = new StackPanel { Children = { messageText, buttonRow } };
        dialog.Opened += (_, _) => defaultButton.Focus();
        dialog.Closed += (_, _) => done = true;

        var wasEnabled = IsEnabled;
        IsEnabled = false;
        try
        {
            dialog.Show(this);
            while (!done)
            {
                Dispatcher.UIThread.RunJobs(DispatcherPriority.Input);
                if (!done)
                    System.Threading.Thread.Sleep(1);
            }
        }
        finally
        {
            IsEnabled = wasEnabled;
        }

        return decision;
    }

    /// <summary>
    /// Test-only override for <see cref="ResolveReadOnlyRecommendedPrompt"/> -- headless tests
    /// inject a canned decision here instead of driving the real
    /// <see cref="ShowReadOnlyRecommendedPromptDialog"/> window. Not used by production code paths.
