    private static double GetCellIndentPadding(CellStyle? style) =>
        style is null ? 0 : Math.Clamp(style.IndentLevel, 0, 15) * CellIndentLevelWidth;

    private static TextDecorationCollection? BuildTextDecorations(CellStyle? style)
    {
        if (style is null || (!style.Underline && !style.DoubleUnderline && !style.Strikethrough))
            return null;

        var decorations = new TextDecorationCollection();
        if (style.Underline || style.DoubleUnderline)
        {
            decorations.Add(new TextDecoration { Location = TextDecorationLocation.Underline });

            if (style.DoubleUnderline)
            {
                decorations.Add(new TextDecoration
                {
                    Location = TextDecorationLocation.Underline,
                    StrokeThickness = 1,
                    StrokeThicknessUnit = TextDecorationUnit.Pixel,
                    StrokeOffset = DoubleUnderlineSecondStrokeOffset,
                    StrokeOffsetUnit = TextDecorationUnit.Pixel,
                });
            }
        }

        if (style.Strikethrough)
            decorations.Add(new TextDecoration { Location = TextDecorationLocation.Strikethrough });

        return decorations;
    }

    private static TextDecorationCollection CreateTextDecorations(TextDecorationLocation location) =>
        [new TextDecoration { Location = location }];

    /// <summary>
    /// Maps a cell's horizontal alignment to an Avalonia <see cref="TextAlignment"/>. General
    /// alignment resolves to the "end"/"start" of the cell's effective reading order rather than a
    /// hardcoded Right/Left — matching Excel, where a right-to-left cell's General alignment mirrors
    /// (numeric/date content general-aligns left, text content general-aligns right). Explicit
    /// Left/Right/Center/Justify/Distributed do not mirror with reading order, matching
    /// <see cref="CellTextOrientationLayoutPlanner.ResolveEffectiveHorizontalAlignment"/>.
    /// </summary>
    private static TextAlignment MapCellTextAlignment(CellHAlign horizontalAlignment, bool isNumericOrDate, bool isEffectivelyRightToLeft) =>
        horizontalAlignment switch
        {
            CellHAlign.Left => TextAlignment.Left,
            CellHAlign.Center or CellHAlign.Justify or CellHAlign.Distributed => TextAlignment.Center,
            CellHAlign.Right => TextAlignment.Right,
            CellHAlign.General when isNumericOrDate => isEffectivelyRightToLeft ? TextAlignment.Left : TextAlignment.Right,
            CellHAlign.General => isEffectivelyRightToLeft ? TextAlignment.Right : TextAlignment.Left,
            _ => TextAlignment.Left
        };

    /// <summary>
    /// Maps a cell's effective reading order (<see cref="CellTextOrientationLayoutPlanner.ResolveIsEffectivelyRightToLeft"/>)
    /// to the Avalonia <see cref="FlowDirection"/> used for that cell's <see cref="TextBlock"/>, so
    /// bidi shaping/reordering (mixed Arabic/Hebrew + Latin/digit runs) matches Excel's base direction
    /// instead of always being forced LeftToRight.
    /// </summary>
    private static FlowDirection MapCellFlowDirection(bool isEffectivelyRightToLeft) =>
        isEffectivelyRightToLeft ? FlowDirection.RightToLeft : FlowDirection.LeftToRight;

    private static AvaloniaVerticalAlignment MapCellVerticalAlignment(CellVAlign verticalAlignment) =>
        verticalAlignment switch
        {
            CellVAlign.Top => AvaloniaVerticalAlignment.Top,
            CellVAlign.Bottom => AvaloniaVerticalAlignment.Bottom,
            _ => AvaloniaVerticalAlignment.Center
        };

    private void SelectCell(CellAddress address)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        ClearSelectionExtensionState();
        ClearSelectedDrawingObject();
        _session.SelectCell(address);
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
        ApplyFormatPainterAfterTargetSelection();
        // Avalonia does not transfer keyboard focus from a TextBox when a rebuilt cell Border is
        // selected by pointer. WPF's worksheet control does this as part of its native click route;
        // keep F2/Ctrl+S and subsequent text input on the selected worksheet cell as well.
        FocusShellRegion(ShellFocusTarget.Worksheet);
    }

    private void SelectRange(CellAddress address)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        // The old active cell is the anchor of the extended selection; keep it there (Shift+click
        // extends toward `address` without moving the anchor) so a downward-then-upward extend still
        // resolves the active cell to the original corner rather than the normalized top-left.
        var anchor = _session.ActiveCell;
        _selectionExtensionAnchor = anchor;
        _selectionExtensionCursor = address;
        ClearSelectedDrawingObject();
        _session.SelectAnchoredRange(anchor, address);
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
        ApplyFormatPainterAfterTargetSelection();
        FocusShellRegion(ShellFocusTarget.Worksheet);
    }

    /// <summary>
    /// Resolves a plain worksheet cell click to either an extend (<see cref="SelectRange"/>) or a
    /// collapse (<see cref="SelectCell"/>), matching Excel: a physical Shift+click always extends,
    /// and so does a plain click while F8 (Extend Selection mode, <see cref="ExcelSelectionMode.Extend"/>)
    /// is active -- mirroring the keyboard path (<c>TryHandleStickySelectionNavigation</c>), which
    /// likewise treats Extend mode as an implicit Shift on arrow-key navigation. Before this fix a
    /// plain click always collapsed the selection even with F8 armed (R68-app-selection-
    /// navigation-6-1).
    /// </summary>
    internal void SelectClickedCell(CellAddress address, KeyModifiers modifiers)
    {
        if (modifiers.HasFlag(KeyModifiers.Shift) || _keyboardSelectionMode == ExcelSelectionMode.Extend)
        {
            SelectRange(address);
            return;
        }

        // A plain click onto a locked cell on a protected sheet with "Select locked cells"
        // unchecked must be refused outright -- Excel neither moves the active cell there nor
        // opens it for editing (R75-services-protection-security-4-1). Shift-click/F8 extend
        // above is left ungated for now; CommandGuards.CanSelectCell already exists for exactly
        // this check (it returns true unconditionally on an unprotected sheet).
        if (!CommandGuards.CanSelectCell(_session.Workbook, _session.ActiveSheet, address))
            return;

        // Ctrl+click (without Shift, checked above) adds the clicked cell as a disjoint SECOND
        // (or later) selection area instead of collapsing the selection down to just this cell --
        // Excel's multi-area selection (select A1, Ctrl+click C3 -> "A1,C3", usable directly by a
        // formula like =SUM(A1,C3)). Before this fix Ctrl+click behaved identically to a plain
        // click here, discarding every prior area (R84-app-mouse-selection-5-1).
        if (modifiers.HasFlag(KeyModifiers.Control))
        {
            AddAdditionalCellSelection(address);
            return;
        }

        SelectCell(address);
    }

    /// <summary>
    /// Appends <paramref name="address"/> as a new disjoint selection area on top of whatever is
    /// already selected, mirroring the WPF host's AddOrMoveAdditionalSelection (MainWindow.
    /// Selection.cs) for a fresh (non-dragging) Ctrl+click. The active cell moves to the newly
    /// added area so subsequent editing/formula-bar state targets it, matching Excel.
    /// </summary>
    private void AddAdditionalCellSelection(CellAddress address)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        ClearSelectionExtensionState();
        ClearSelectedDrawingObject();
        var newRange = new GridRange(address, address);
        var ranges = new List<GridRange>(_session.SelectedRanges) { newRange };
        _session.SelectRanges(newRange, ranges, address);
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
        ApplyFormatPainterAfterTargetSelection();
        FocusShellRegion(ShellFocusTarget.Worksheet);
    }

    private void ClearSelectionExtensionState()
    {
        _selectionExtensionAnchor = null;
        _selectionExtensionCursor = null;
    }

    private void SelectSheet(SheetId sheetId)
        => SelectSheet(sheetId, selectRange: false, toggle: false);

    // internal (not private) so headless regression tests can drive the sheet-tab context-menu
    // group-preservation behavior directly (see F21 in FormatCellsDialogNumberFormatSeedTests-
    // adjacent test suite: SheetTabContextCommandGroupPreservationTests).
    internal bool SelectSheetForContextCommand(SheetId sheetId)
    {
        if (!TryCommitPendingFormulaEdit())
            return false;

        // F21: when the right-clicked tab is already part of the active multi-sheet GROUP
        // selection, keep the group (mirrors the WPF host's SheetTab_MouseRightButtonDown);
        // only collapse to a single tab when the clicked tab is outside the current selection.
        var changed = _session.IsSheetInActiveGroupSelection(sheetId)
            ? _session.SelectSheetPreservingGroup(sheetId)
            : _session.SelectSheet(sheetId);
        if (changed)
        {
            ClearSelectedDrawingObject();
            RefreshShell(UiText.Format("MainLoc_SelectedX", _session.ActiveSheet.Name));
        }

        return true;
    }

    private void HandleSheetTabKeyDown(SheetId sheetId, Button button, KeyEventArgs args)
    {
        OpenSheetTabContextMenuFromKeyboard(sheetId, button, args);
        if (args.Handled)
            return;

        NavigateSheetTabFromKeyboard(sheetId, args);
    }

    private void OpenSheetTabContextMenuFromKeyboard(SheetId sheetId, Button button, KeyEventArgs args)
    {
        if (!IsSheetTabContextMenuKey(args))
            return;

        args.Handled = true;
        if (!SelectSheetForContextCommand(sheetId))
            return;

        if (FindSheetTabButton(sheetId) is { } refreshedButton)
            button = refreshedButton;

        if (button.ContextMenu is { } contextMenu)
        {
            contextMenu.Opened -= SheetTabContextMenu_Opened;
            contextMenu.Opened += SheetTabContextMenu_Opened;
            contextMenu.Open(button);
        }
    }

    private static bool IsSheetTabContextMenuKey(KeyEventArgs args) =>
        args.Key == Key.Apps ||
        args.Key == Key.F10 && args.KeyModifiers == KeyModifiers.Shift;

    private void NavigateSheetTabFromKeyboard(SheetId sheetId, KeyEventArgs args)
    {
        if (args.KeyModifiers != KeyModifiers.None)
            return;

        var targetSheetId = args.Key switch
        {
            Key.Left => GetAdjacentSheetTabId(sheetId, direction: -1),
            Key.Right => GetAdjacentSheetTabId(sheetId, direction: 1),
            Key.Home => GetEdgeSheetTabId(first: true),
            Key.End => GetEdgeSheetTabId(first: false),
            _ => null
        };
        if (targetSheetId is null)
            return;

        args.Handled = true;
        SelectSheetTabFromKeyboard(targetSheetId.Value, selectRange: false);
    }

    private bool SelectAdjacentVisibleSheetFromKeyboard(int direction, bool selectRange)
    {
        var targetSheetId = GetAdjacentSheetTabId(_session.ActiveSheet.Id, direction);
        if (targetSheetId is null)
            return false;

        SelectSheetTabFromKeyboard(targetSheetId.Value, selectRange);
        return true;
    }

    private void SelectSheetTabFromKeyboard(SheetId sheetId, bool selectRange)
    {
        SelectSheet(sheetId, selectRange, toggle: false);

        FocusActiveSheetTab();
    }

    private SheetId? GetAdjacentSheetTabId(SheetId sheetId, int direction)
        => SheetTabFocusPlanner.AdjacentTab(_session.SheetTabs, sheetId, direction, static tab => tab.Id);

    private SheetId? GetEdgeSheetTabId(bool first)
        => SheetTabFocusPlanner.EdgeTab(_session.SheetTabs, first, static tab => tab.Id);

    private bool FocusActiveSheetTab()
        => FocusSheetTab(_session.ActiveSheet.Id);

    private bool FocusSheetTab(SheetId sheetId)
    {
        if (FindSheetTabButton(sheetId) is not { } button)
            return false;

        button.Focus();
        return button.IsFocused;
    }

    private static void SheetTabContextMenu_Opened(object? sender, RoutedEventArgs args)
    {
        if (sender is not ContextMenu contextMenu ||
            contextMenu.ItemsSource is not IEnumerable<Control> items)
        {
            return;
        }

        FocusFirstEnabledSheetTabMenuItem(items);
    }

    private static void FocusFirstEnabledSheetTabMenuItem(IEnumerable<Control> items)
    {
        foreach (var item in items)
        {
            if (item is MenuItem { IsEnabled: true } menuItem)
            {
                menuItem.Focus();
                return;
            }
        }
    }

    private Button? FindSheetTabButton(SheetId sheetId)
    {
        if (_sheetTabsHost.Content is not StackPanel panel)
            return null;

        foreach (var child in panel.Children)
        {
            if (child is Button button &&
                button.Tag is SheetId tag &&
                tag == sheetId)
            {
                return button;
            }
        }

        return null;
    }

    private void SelectSheet(SheetId sheetId, bool selectRange, bool toggle)
    {
        // Preserve both Point-mode and existing formula Edit-mode sessions. A qualified formula
        // reference can only be resized after its referenced sheet becomes active, and ending an
        // existing formula edit here would commit before the user can reach that sheet.
        if (GetFormulaReferenceHighlightEditor() is not null)
        {
            var changed = _session.SelectSheetForFormulaEdit(sheetId, selectRange, toggle);
            CloseAutoFilterFlyout();
            if (changed)
            {
                ClearSelectedDrawingObject();
                RefreshShell(UiText.Format("MainLoc_SelectedX", _session.ActiveSheet.Name));
            }
            return;
        }

        if (!TryCommitPendingFormulaEdit())
            return;

        if (!_session.SelectSheetFromTab(sheetId, selectRange, toggle))
            return;

        CloseAutoFilterFlyout();
        ClearSelectedDrawingObject();
        RefreshShell(UiText.Format("MainLoc_SelectedX", _session.ActiveSheet.Name));
    }

