        GoToSpecialDialogPlanner.BuildChoices().ToArray();

    private bool SelectGoToSpecial(GoToSpecialKind kind, GoToSpecialOptions? options = null)
    {
        if (!TryCommitPendingFormulaEdit())
            return false;

        ClearSelectedDrawingObject();
        var result = _session.GoToSpecial(kind, options);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_GoToSpecialFailed"));
            return false;
        }

        // R92-render-localization-chrome-5-4: the multi-range branch previously spliced a raw
        // English "cells" noun into this otherwise-localized status; route it through the shared
        // catalog (MainLoc_CellsCount) like the single-range branch's own FormatRangeReference,
        // which is already culture-neutral.
        var selectedText = result.SelectedRanges.Count == 1
            ? FormatRangeReference(result.SelectedRange!.Value)
            : UiText.Format("MainLoc_CellsCount", result.MatchCount);
        RefreshShell(UiText.Format("MainLoc_SelectedX", selectedText));
        return true;
    }

    private async Task ShowInsertHyperlinkDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowInsertHyperlinkInputDialogAsync();
        if (plan is null)
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var result = _session.SetSelectedRangeHyperlink(plan);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? "Insert Hyperlink failed.");
            return;
        }

        RefreshShell(UiText.Format("MainLoc_InsertedHyperlinkFor", rangeReference));
    }

    private async Task<HyperlinkDialogPlan?> ShowInsertHyperlinkInputDialogAsync()
    {
        HyperlinkDialogPlan? result = null;
        var prefill = _session.GetSelectedRangeHyperlinkDialogPrefill();
        var linkTypeChoices = CreateHyperlinkTypeChoices();
        var selectedLinkType = linkTypeChoices[0];
        foreach (var choice in linkTypeChoices)
        {
            if (choice.Value != prefill.LinkType)
                continue;

            selectedLinkType = choice;
            break;
        }

        var dialog = new Window
        {
            Title = UiText.Get("Hyperlink_InsertHyperlink"),
            Width = HyperlinkDialogPlanner.Width,
            Height = HyperlinkDialogPlanner.Height,
            MinWidth = HyperlinkDialogPlanner.MinWidth,
            MinHeight = HyperlinkDialogPlanner.MinHeight,
            CanResize = false,
            Background = Brushes.White,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontFamily = FormulaBarFontFamily,
            FontSize = 12,
        };
        AutomationProperties.SetAutomationId(dialog, "HyperlinkCompactDialog");

        var linkTypeBox = new ListBox
        {
            ItemsSource = linkTypeChoices,
            SelectedItem = selectedLinkType,
            MinWidth = HyperlinkDialogPlanner.LinkTypeColumnWidth,
            Width = HyperlinkDialogPlanner.LinkTypeColumnWidth,
            Height = HyperlinkDialogPlanner.LinkTypeListHeight,
        };
        AutomationProperties.SetName(linkTypeBox, UiText.Get("Hyperlink_LinkTo2"));
        AutomationProperties.SetAutomationId(linkTypeBox, "HyperlinkLinkTypeBox");

        var displayBox = new TextBox
        {
            Text = prefill.DisplayText,
        };
        AutomationProperties.SetName(displayBox, UiText.Get("Hyperlink_TextToDisplay"));
        AutomationProperties.SetAutomationId(displayBox, "HyperlinkDisplayTextBox");
        ApplyDialogTextBoxChrome(displayBox);

        var targetLabel = new TextBlock();
        var targetBox = new TextBox
        {
            Text = prefill.Target,
        };
        AutomationProperties.SetAutomationId(targetBox, "HyperlinkTargetTextBox");
        ApplyDialogTextBoxChrome(targetBox);

        // ScreenTip / Bookmark are surfaced as buttons on Windows (not inline fields).
        // These backing text boxes hold the current values but are not added to the
        // visible tree; the buttons below edit them via small popup prompts.
        var screenTipBox = new TextBox
        {
            Text = prefill.ScreenTip,
        };
        AutomationProperties.SetName(screenTipBox, UiText.Get("Hyperlink_ScreenTipTextLabel"));
        AutomationProperties.SetAutomationId(screenTipBox, "HyperlinkScreenTipTextBox");
        ApplyDialogTextBoxChrome(screenTipBox);

        var bookmarkBox = new TextBox
        {
            Text = prefill.Bookmark,
        };
        AutomationProperties.SetName(bookmarkBox, UiText.Get("Hyperlink_BookmarkOrCellReferenceLabel"));
        AutomationProperties.SetAutomationId(bookmarkBox, "HyperlinkBookmarkTextBox");
        ApplyDialogTextBoxChrome(bookmarkBox);

        var screenTipButton = new Button { Content = StripDisplayMnemonic(UiText.Get("Hyperlink_ScreenTip")) };
        ApplyDialogButtonChrome(screenTipButton, width: HyperlinkDialogPlanner.SecondaryButtonWidth);
        AutomationProperties.SetName(screenTipButton, "ScreenTip");
        AutomationProperties.SetAutomationId(screenTipButton, "HyperlinkScreenTipButton");
        AutomationProperties.SetHelpText(screenTipButton, "Set the ScreenTip text shown when hovering the hyperlink.");

        var bookmarkButton = new Button { Content = StripDisplayMnemonic(UiText.Get("Hyperlink_Bookmark")) };
        ApplyDialogButtonChrome(bookmarkButton, width: HyperlinkDialogPlanner.SecondaryButtonWidth);
        AutomationProperties.SetName(bookmarkButton, "Bookmark");
        AutomationProperties.SetAutomationId(bookmarkButton, "HyperlinkBookmarkButton");
        AutomationProperties.SetHelpText(bookmarkButton, "Choose a bookmark or cell reference within the destination.");

        var validationText = new TextBlock
        {
            MinHeight = 20,
            Foreground = Brush(143, 74, 18),
            IsVisible = false,
        };
        AutomationProperties.SetAutomationId(validationText, "HyperlinkValidationText");

        var okButton = new Button
        {
            Content = UiText.Get("Common_Ok"),
            MinWidth = HyperlinkDialogPlanner.ActionButtonWidth,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(okButton, "HyperlinkOkButton");
        ApplyDialogButtonChrome(okButton, isDefault: true);

        var cancelButton = new Button
        {
            Content = UiText.Get("Common_Cancel"),
            MinWidth = HyperlinkDialogPlanner.ActionButtonWidth,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(cancelButton, "HyperlinkCancelButton");
        ApplyDialogButtonChrome(cancelButton);

        HyperlinkTargetKind CurrentLinkType() =>
            linkTypeBox.SelectedItem is SortDialogComboItem<HyperlinkTargetKind> choice
                ? choice.Value
                : HyperlinkTargetKind.ExistingFileOrWebPage;

        void RefreshTargetField()
        {
            var linkType = CurrentLinkType();
            targetLabel.Text = GetHyperlinkTargetLabel(linkType);
            AutomationProperties.SetName(targetBox, targetLabel.Text);
            AutomationProperties.SetHelpText(targetBox, GetHyperlinkTargetHelpText(linkType));
        }

        void Accept()
        {
            if (!HyperlinkDialogPlanner.TryPlan(
                    targetBox.Text,
                    displayBox.Text,
                    CurrentLinkType(),
                    screenTipBox.Text,
                    bookmarkBox.Text,
                    out var plan,
                    out var validationError))
            {
                validationText.Text = GetHyperlinkValidationErrorText(validationError);
                validationText.IsVisible = true;
                targetBox.Focus();
                targetBox.SelectAll();
                return;
            }

            result = plan;
            dialog.Close();
        }

        linkTypeBox.SelectionChanged += (_, _) => RefreshTargetField();
        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        screenTipButton.Click += async (_, _) =>
        {
            var value = await ShowHyperlinkSubPromptAsync(
                dialog,
                UiText.Get("Hyperlink_SetHyperlinkScreenTipTitle"),
                StripDisplayMnemonic(UiText.Get("Hyperlink_ScreenTipTextLabel")),
                screenTipBox.Text);
            if (value is not null)
                screenTipBox.Text = value;
        };
        bookmarkButton.Click += async (_, _) =>
        {
            var value = await ShowHyperlinkSubPromptAsync(
                dialog,
                StripDisplayMnemonic(UiText.Get("Hyperlink_Bookmark")).Replace(".", string.Empty).Trim(),
                StripDisplayMnemonic(UiText.Get("Hyperlink_BookmarkOrCellReferenceLabel")),
                bookmarkBox.Text);
            if (value is not null)
                bookmarkBox.Text = value;
        };
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = HyperlinkDialogPlanner.ButtonGap,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };

        // Keep the category column and detail grid aligned with the WPF dialog:
        // labels share a fixed column with their editors instead of stacking above them.
        var linkToLabel = new TextBlock
        {
            Text = UiText.Get("Hyperlink_LinkTo2") + ":",
            Margin = new Thickness(0, 0, 0, HyperlinkDialogPlanner.FieldBottomMargin),
        };
        var linkToColumn = new StackPanel
        {
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
            Children =
            {
                linkToLabel,
                linkTypeBox,
            },
        };

        // Right detail area: "Text to display" + "Address" + screen-tip/bookmark fields,
        // arranged as the WPF label/editor rows.
        targetBox.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
        displayBox.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
        targetBox.Height = HyperlinkDialogPlanner.FieldHeight;
        displayBox.Height = HyperlinkDialogPlanner.FieldHeight;

        // ScreenTip... + Bookmark... sit on one right-aligned row beneath the Address
        // field (as buttons, not inline fields), matching the Windows dialog.
        var hyperlinkButtonsRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = HyperlinkDialogPlanner.ButtonGap,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Left,
            Margin = new Thickness(0, 0, 0, 12),
            Children = { screenTipButton, bookmarkButton },
        };

        var detailArea = new AvaloniaGrid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions
            {
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LabelColumnWidth) },
                new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) },
            },
        };
        AddHyperlinkFieldRow(detailArea, 0, UiText.Get("Hyperlink_TextToDisplay"), displayBox);
        AddHyperlinkFieldRow(detailArea, 1, targetLabel, targetBox);
        detailArea.Children.Add(hyperlinkButtonsRow);
        AvaloniaGrid.SetRow(hyperlinkButtonsRow, 2);
        AvaloniaGrid.SetColumn(hyperlinkButtonsRow, 1);
        detailArea.Children.Add(buttonRow);
        AvaloniaGrid.SetRow(buttonRow, 3);
        AvaloniaGrid.SetColumn(buttonRow, 1);

        var bodyGrid = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions
            {
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LinkTypeColumnWidth) },
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LinkTypeColumnGap) },
                new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) },
            },
        };
        bodyGrid.Children.Add(linkToColumn);
        AvaloniaGrid.SetColumn(linkToColumn, 0);
        detailArea.Margin = new Thickness(
            HyperlinkDialogPlanner.DialogMargin,
            HyperlinkDialogPlanner.DialogMargin,
            HyperlinkDialogPlanner.DialogMargin,
            0);
        bodyGrid.Children.Add(detailArea);
        AvaloniaGrid.SetColumn(detailArea, 2);

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(HyperlinkDialogPlanner.DialogMargin),
            Children =
            {
                bodyGrid,
                validationText,
            },
        };
        dialog.Opened += (_, _) =>
        {
            RefreshTargetField();
            targetBox.Focus();
            targetBox.SelectAll();
        };

        await dialog.ShowDialog(this);
        return result;
    }

    // Small modal prompt used by the Insert Hyperlink "ScreenTip..." / "Bookmark..."
    // buttons to edit their value, mirroring the Windows secondary dialogs.
    private static async Task<string?> ShowHyperlinkSubPromptAsync(
        Window owner,
        string title,
        string label,
        string? initialValue)
    {
        string? result = null;
        var prompt = new Window
        {
            Title = title,
            Width = 380,
            Height = 160,
            MinWidth = 340,
            MinHeight = 150,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontFamily = FormulaBarFontFamily,
            FontSize = 12,
        };

        var inputBox = new TextBox { Text = initialValue ?? string.Empty, MinWidth = 300 };
        ApplyDialogTextBoxChrome(inputBox);
        AutomationProperties.SetName(inputBox, label);

        var okButton = new Button { Content = UiText.Get("Common_Ok") };
        ApplyDialogButtonChrome(okButton, width: 84, isDefault: true);
        var cancelButton = new Button { Content = UiText.Get("Common_Cancel") };
        ApplyDialogButtonChrome(cancelButton, width: 84);

        void Accept()
        {
            result = inputBox.Text ?? string.Empty;
            prompt.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => prompt.Close();
        prompt.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter) { e.Handled = true; Accept(); }
            else if (e.Key == Key.Escape) { e.Handled = true; prompt.Close(); }
        };

        prompt.Content = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 8,
            Children =
            {
                new TextBlock { Text = label },
                inputBox,
                new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 8,
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                    Margin = new Thickness(0, 8, 0, 0),
                    Children = { okButton, cancelButton },
                },
            },
        };
        prompt.Opened += (_, _) => { inputBox.Focus(); inputBox.SelectAll(); };

        await prompt.ShowDialog(owner);
        return result;
    }

    private static SortDialogComboItem<HyperlinkTargetKind>[] CreateHyperlinkTypeChoices() =>
    [
        new(UiText.Get("Hyperlink_LinkTypeExistingFileOrWebPage"), HyperlinkTargetKind.ExistingFileOrWebPage),
        new(UiText.Get("Hyperlink_LinkTypeCreateNewDocument"), HyperlinkTargetKind.CreateNewDocument),
        new(UiText.Get("Hyperlink_LinkTypePlaceInThisDocument"), HyperlinkTargetKind.PlaceInThisDocument),
        new(UiText.Get("Hyperlink_LinkTypeEmailAddress"), HyperlinkTargetKind.EmailAddress),
    ];

    private static void AddHyperlinkFieldRow(AvaloniaGrid grid, int row, string label, Control control) =>
        AddHyperlinkFieldRow(grid, row, new TextBlock { Text = StripDisplayMnemonic(label) }, control);

    private static void AddHyperlinkFieldRow(AvaloniaGrid grid, int row, Control label, Control control)
    {
        label.VerticalAlignment = AvaloniaVerticalAlignment.Center;
        label.Margin = new Thickness(0, 0, HyperlinkDialogPlanner.ButtonGap, HyperlinkDialogPlanner.FieldBottomMargin);
        grid.Children.Add(label);
        AvaloniaGrid.SetRow(label, row);
        AvaloniaGrid.SetColumn(label, 0);

        control.Margin = new Thickness(0, 0, 0, HyperlinkDialogPlanner.FieldBottomMargin);
        grid.Children.Add(control);
        AvaloniaGrid.SetRow(control, row);
        AvaloniaGrid.SetColumn(control, 1);
    }

    private static string StripDisplayMnemonic(string text) =>
        (text ?? string.Empty).Replace("_", string.Empty, StringComparison.Ordinal);

    // CheckBox/RadioButton in this Avalonia shell render their string Content literally
    // (no AccessText, see MainWindow.ParityCapture access-key note), so WPF mnemonic
    // markers ("_Show legend") would show the underscore. Strip it for string content;
    // leave non-string content (panels, etc.) untouched. Safe no-op without underscores.
    private static void StripContentMnemonic(ContentControl control)
    {
        if (control.Content is string text)
            control.Content = StripDisplayMnemonic(text);
    }

    private static string GetHyperlinkTargetLabel(HyperlinkTargetKind linkType) =>
        StripDisplayMnemonic(linkType switch
        {
            HyperlinkTargetKind.PlaceInThisDocument => UiText.Get("Hyperlink_CellReferenceLabel"),
            HyperlinkTargetKind.CreateNewDocument => UiText.Get("Hyperlink_NewDocumentLabel"),
            HyperlinkTargetKind.EmailAddress => UiText.Get("Hyperlink_EmailAddressLabel"),
            _ => UiText.Get("Hyperlink_Address"),
        });

    private static string GetHyperlinkTargetHelpText(HyperlinkTargetKind linkType) =>
        linkType switch
        {
            HyperlinkTargetKind.PlaceInThisDocument => "Enter a workbook location such as Sheet1!A1.",
            HyperlinkTargetKind.CreateNewDocument => "Enter the document name to store with this hyperlink.",
            HyperlinkTargetKind.EmailAddress => "Enter an email address or mailto link.",
            _ => "Enter a web page or file address."
        };

    private static string GetHyperlinkValidationErrorText(HyperlinkDialogValidationError error) =>
        error switch
        {
            HyperlinkDialogValidationError.MissingDocumentLocation => "Enter a cell reference or defined name.",
            HyperlinkDialogValidationError.MissingEmailAddress => "Enter an email address.",
            HyperlinkDialogValidationError.MissingNewDocumentName => "Enter a new document name.",
            HyperlinkDialogValidationError.InvalidEmailAddress => "Enter a valid email address.",
            _ => "Enter an address."
        };

    private async Task ShowWorkbookStatisticsDialogAsync()
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        var statistics = WorkbookStatisticsService.GetStatistics(_session.Workbook);
        var dialog = new Window
        {
            Title = "Workbook Statistics",
            Width = WorkbookStatisticsDialogPlanner.Width,
            Height = WorkbookStatisticsDialogPlanner.Height,
            MinWidth = WorkbookStatisticsDialogPlanner.MinWidth,
            MinHeight = WorkbookStatisticsDialogPlanner.MinHeight,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "WorkbookStatisticsDialog");

        var okButton = new Button
        {
            Content = "OK",
            MinWidth = 84,
            Padding = new Thickness(10, 4),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        AutomationProperties.SetName(okButton, "OK");
        AutomationProperties.SetAutomationId(okButton, "WorkbookStatisticsOkButton");
        AutomationProperties.SetHelpText(okButton, "Close workbook statistics.");

        var copyToClipboardButton = new Button
        {
            Content = "Copy to Clipboard",
            MinWidth = 120,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetName(copyToClipboardButton, "Copy to Clipboard");
        AutomationProperties.SetAutomationId(copyToClipboardButton, "WorkbookStatisticsCopyButton");
        AutomationProperties.SetHelpText(copyToClipboardButton, "Copy workbook statistics to the clipboard.");
        ApplyDialogButtonChrome(copyToClipboardButton);

        var statsText = FormatWorkbookStatistics(statistics);
        copyToClipboardButton.Click += async (_, _) =>
        {
            if (TopLevel.GetTopLevel(dialog)?.Clipboard is { } clipboard)
                await clipboard.SetTextAsync(statsText);
        };

        okButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key is Key.Enter or Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        dialog.Content = CreateWorkbookStatisticsDialogContent(statistics, okButton, copyToClipboardButton);
        dialog.Opened += (_, _) => okButton.Focus();
        await dialog.ShowDialog(this);
    }

    private static Control CreateWorkbookStatisticsDialogContent(WorkbookStatistics statistics, Button okButton, Button? copyToClipboardButton = null)
    {
        var statisticsBlock = new TextBox
        {
            Text = FormatWorkbookStatistics(statistics),
            IsReadOnly = true,
            AcceptsReturn = true,
            TextWrapping = TextWrapping.Wrap,
            Background = Brushes.White,
            BorderBrush = Brush(171, 171, 171),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(6, 4),
            VerticalContentAlignment = AvaloniaVerticalAlignment.Top,
        };
        AutomationProperties.SetName(statisticsBlock, "Workbook Statistics");
        AutomationProperties.SetAutomationId(statisticsBlock, "WorkbookStatisticsSummary");
        AutomationProperties.SetHelpText(statisticsBlock, "Summarizes sheet, cell, formula, comment, and object counts for the workbook.");

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 12, 0, 0),
        };
        if (copyToClipboardButton is not null)
            buttonRow.Children.Add(copyToClipboardButton);
        buttonRow.Children.Add(okButton);

        var root = new DockPanel
        {
            Margin = new Thickness(16),
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);
        root.Children.Add(buttonRow);
        root.Children.Add(statisticsBlock);

        return root;
    }

    private static string FormatWorkbookStatistics(WorkbookStatistics statistics) =>
        WorkbookStatisticsFormatter.Format(statistics);

    private async Task ShowReviewSummaryDialogAsync(bool focusAccessibility = false)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = _session.GetReviewWorkflowPlan();
        var dialog = new Window
        {
            Title = focusAccessibility ? "Accessibility Check" : "Review Summary",
            Width = 640,
            Height = 520,
            MinWidth = 520,
            MinHeight = 420,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "ReviewSummaryDialog");

        var summaryBlock = new TextBlock
        {
            Text = FormatReviewWorkflowSummary(plan),
            TextWrapping = TextWrapping.Wrap,
            LineHeight = 21,
        };
        AutomationProperties.SetName(summaryBlock, "Review Summary");
        AutomationProperties.SetAutomationId(summaryBlock, "ReviewSummaryText");
        AutomationProperties.SetHelpText(summaryBlock, "Summarizes workbook statistics and review item counts.");

        var spellingList = CreateReviewPreviewList(
            "Spelling issues",
            "ReviewSpellingIssuesList",
            FormatReviewSpellingIssues(plan.SpellingIssues));
        var accessibilityList = CreateReviewPreviewList(
            "Accessibility issues",
            "ReviewAccessibilityIssuesList",
            FormatReviewAccessibilityIssues(plan.AccessibilityIssues));
        var notesList = CreateReviewPreviewList(
            "Notes",
            "ReviewNotesList",
            FormatReviewCommentItems(plan.Notes, "No notes on the active sheet."));
        var commentsList = CreateReviewPreviewList(
            "Threaded comments",
            "ReviewCommentsList",
            FormatReviewCommentItems(plan.ThreadedComments, "No threaded comments on the active sheet."));

        var closeButton = new Button
        {
            Content = "Close",
            MinWidth = 84,
            Padding = new Thickness(10, 4),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        AutomationProperties.SetName(closeButton, "Close");
        AutomationProperties.SetAutomationId(closeButton, "ReviewCloseButton");
        AutomationProperties.SetHelpText(closeButton, "Close review summary.");
        closeButton.Click += (_, _) => dialog.Close();

        dialog.KeyDown += (_, e) =>
        {
            if (e.Key is Key.Enter or Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 12, 0, 0),
            Children =
            {
                closeButton,
            },
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);

        dialog.Content = new DockPanel
        {
            Margin = new Thickness(16),
            Children =
            {
                buttonRow,
                new ScrollViewer
                {
                    HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
                    VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            summaryBlock,
                            CreateReviewPreviewSection("Spelling", spellingList),
                            CreateReviewPreviewSection("Accessibility", accessibilityList),
                            CreateReviewPreviewSection("Notes", notesList),
                            CreateReviewPreviewSection("Comments", commentsList),
                        },
                    },
                },
            },
        };
        dialog.Opened += (_, _) =>
        {
            if (focusAccessibility)
                accessibilityList.Focus();
            else
                closeButton.Focus();
        };

        await dialog.ShowDialog(this);
    }

    private void NavigateReviewNote(bool previous) =>
        NavigateReviewTarget(
            () => ReviewSessionController.NavigateNote(previous),
            previous ? "previous note" : "next note",
            previous ? "Previous note was not found." : "Next note was not found.");

    private void NavigateReviewThreadedComment(bool previous) =>
        NavigateReviewTarget(
            () => ReviewSessionController.NavigateThreadedComment(previous),
            previous ? "previous comment" : "next comment",
            previous ? "Previous threaded comment was not found." : "Next threaded comment was not found.");

    private void NavigateReviewTarget(
        Func<PresentationReviewNavigationResult> navigate,
        string statusLabel,
        string fallbackMessage)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        ClearSelectedDrawingObject();
        var result = navigate();
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? fallbackMessage);
            return;
        }

        if (result.Target is null)
        {
            ShowEditIssue(UiText.Get("MainLoc_ReviewTargetNotSelected"));
            return;
        }

        ApplyReviewRefreshPlan(
            result.RefreshPlan,
            $"Selected {FormatRangeReference(_session.SelectedRange)} ({statusLabel})");
    }

    private static string FormatReviewWorkflowSummary(ReviewWorkflowPlan plan)
    {
        var statistics = plan.Statistics;
        return string.Join(Environment.NewLine,
            $"Sheets: {statistics.WorksheetCount}",
            $"Cells with data: {statistics.CellCount}",
            $"Formulas: {statistics.FormulaCount}",
            $"Workbook comments: {statistics.CommentCount}",
            $"Charts: {statistics.ChartCount}",
            $"Pictures: {statistics.PictureCount}",
            $"Shapes and text boxes: {statistics.ShapeCount}",
            $"Named ranges: {statistics.NamedRangeCount}",
            "",
            $"Spelling issues: {plan.SpellingIssues.Count}",
            $"Accessibility issues: {plan.AccessibilityIssues.Count}",
            $"Notes on active sheet: {plan.Notes.Count}",
            $"Threaded comments on active sheet: {plan.ThreadedComments.Count}");
    }

    private static StackPanel CreateReviewPreviewSection(string header, ListBox list) =>
        new()
        {
            Spacing = 4,
            Children =
            {
                new TextBlock
                {
                    Text = StripDisplayMnemonic(header),
                    FontWeight = FontWeight.SemiBold,
                },
                list,
            },
        };

    private static ListBox CreateReviewPreviewList(
        string name,
        string automationId,
        IReadOnlyList<string> items)
    {
        var list = new ListBox
        {
            ItemsSource = items,
            MinHeight = 56,
            MaxHeight = 96,
        };
        AutomationProperties.SetName(list, name);
        AutomationProperties.SetAutomationId(list, automationId);
        return list;
    }

    private static IReadOnlyList<string> FormatReviewSpellingIssues(IReadOnlyList<SpellingIssue> issues) =>
        CreateReviewPreviewItems(
            issues,
            issue =>
            {
                var suggestion = string.IsNullOrWhiteSpace(issue.Suggestion) ? "no suggestion" : issue.Suggestion;
                return $"{FormatCellReference(issue.Address)}: {issue.Word} -> {suggestion} ({FormatSpellingIssueSource(issue.Source)})";
            },
            "No spelling issues.");

    private static IReadOnlyList<string> FormatReviewAccessibilityIssues(IReadOnlyList<AccessibilityIssue> issues) =>
        CreateReviewPreviewItems(
            issues,
            issue => $"{TrimReviewPreview(issue.SheetName)}!{TrimReviewPreview(issue.Location)}: {TrimReviewPreview(issue.Message)}",
            "No accessibility issues.");

    private static IReadOnlyList<string> FormatReviewCommentItems(
        IReadOnlyList<ReviewCommentListItem> items,
        string emptyMessage) =>
        CreateReviewPreviewItems(
            items,
            item => $"{FormatCellReference(item.Address)}: {TrimReviewPreview(item.PreviewText)}",
            emptyMessage);

    private static IReadOnlyList<string> CreateReviewPreviewItems<T>(
        IReadOnlyList<T> items,
        Func<T, string> format,
        string emptyMessage)
    {
        if (items.Count == 0)
            return [emptyMessage];

        const int previewLimit = 6;
        var preview = items
            .Take(previewLimit)
            .Select(format)
            .ToList();
        if (items.Count > preview.Count)
            preview.Add($"... and {items.Count - preview.Count} more");

        return preview;
    }

    private static string FormatSpellingIssueSource(SpellingIssueSource source) =>
        source switch
        {
            SpellingIssueSource.CellText => "cell text",
            SpellingIssueSource.Note => "note",
            SpellingIssueSource.ThreadedComment => "threaded comment",
            SpellingIssueSource.ThreadedCommentReply => "threaded reply",
            _ => "spelling"
        };

    private static string TrimReviewPreview(string text)
    {
        var normalized = string.Join(
            " ",
            text.Split(['\r', '\n', '\t'], StringSplitOptions.RemoveEmptyEntries)).Trim();
        if (string.IsNullOrWhiteSpace(normalized))
            return "(blank)";

        const int maxLength = 96;
        return normalized.Length <= maxLength
            ? normalized
            : normalized[..(maxLength - 3)] + "...";
    }

    private async Task ShowFormatCellsDialogAsync(int initialTabIndex = 0)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        var selection = await ShowFormatCellsInputDialogAsync(initialTabIndex: initialTabIndex);
        if (selection is null)
            return;

        if (!FormatCellsCompactPlanner.TryPlan(selection.Request, out var diff, out var errorMessage))
        {
            ShowEditIssue(errorMessage);
            return;
        }

        ClearSelectedDrawingObject();
        var range = _session.SelectedRange;
        var mergeContentResolution = MergeCellContentResolution.KeepFirstCell;
        if (selection.Request.MergeCells == true)
        {
            var contentPlan = CellMergePlanner.AnalyzeContent(_session.ActiveSheet, range);
            if (contentPlan.WouldLoseContent)
            {
                var choice = await ShowMergeCellsContentWarningDialogAsync(contentPlan);
                if (choice == MergeCellsWarningChoice.Cancel)
                {
                    RefreshShell(_statusText.Text ?? "Ready");
                    return;
                }

                mergeContentResolution = choice == MergeCellsWarningChoice.ConcatenateAllCells
                    ? MergeCellContentResolution.ConcatenateAllCells
                    : MergeCellContentResolution.KeepFirstCell;
            }
        }

        var rangeReference = FormatRangeReference(range);
        var result = _session.ApplySelectedRangeCompactFormat(
            diff,
            selection.BorderPreset,
            selection.BorderStyle,
            selection.BorderColor,
            selection.Request.MergeCells,
            mergeContentResolution);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_FormatCellsFailed"));
            return;
        }

        RefreshShell(UiText.Format("MainLoc_FormattedX", rangeReference));
    }

    internal Task<FormatCellsDialogResult?> ShowFormatCellsInputDialogAsync(
        Action<FormatCellsDialogSmokeProbe>? launchSmokeProbe = null,
        int initialTabIndex = 0) =>
        ShowFormatCellsInputDialogCoreAsync(launchSmokeProbe, initialTabIndex, numberFormatOverride: null);

    internal Task<FormatCellsDialogResult?> ShowPivotNumberFormatInputDialogAsync(
        string? currentNumberFormat,
        Action<FormatCellsDialogSmokeProbe>? launchSmokeProbe = null) =>
        ShowFormatCellsInputDialogCoreAsync(launchSmokeProbe, initialTabIndex: 0, currentNumberFormat);

    private async Task<FormatCellsDialogResult?> ShowFormatCellsInputDialogCoreAsync(
        Action<FormatCellsDialogSmokeProbe>? launchSmokeProbe = null,
        int initialTabIndex = 0,
        string? numberFormatOverride = null)
    {
        const double formatCellsDialogWidth = 620;
        const double formatCellsDefaultDialogHeight = 540;
        const double formatCellsBorderDialogHeight = 596.5;

        FormatCellsDialogResult? result = null;
        var currentNumberFormat = numberFormatOverride ?? _session.SelectedRangeStartNumberFormat;
        var currentHorizontalAlignment = _session.SelectedRangeStartHorizontalAlignment;
        var currentVerticalAlignment = _session.SelectedRangeStartVerticalAlignment;
        var currentMergeCells = _session.IsSelectedRangeMerged;
        var currentFontSize = _session.SelectedRangeStartFontSize;
        var currentStyle = _session.CreateFormatDiffFromActiveCell() ?? StyleDiff.FromStyle(CellStyle.Default);
        var currentUnderline = currentStyle.Underline ?? CellStyle.Default.Underline;
        var currentDoubleUnderline = currentStyle.DoubleUnderline ?? _session.IsSelectedRangeStartDoubleUnderline;
        var currentShrinkToFit = currentStyle.ShrinkToFit ?? CellStyle.Default.ShrinkToFit;
        var currentIndentLevel = currentStyle.IndentLevel ?? _session.SelectedRangeStartIndentLevel;
        var currentTextRotation = currentStyle.TextRotation ?? _session.SelectedRangeStartTextRotation;
        var currentFontName = currentStyle.FontName ?? CellStyle.Default.FontName;
        var currentLocked = currentStyle.Locked ?? CellStyle.Default.Locked;
        var currentHidden = currentStyle.Hidden ?? CellStyle.Default.Hidden;
        var currentSuperscript = currentStyle.Superscript ?? CellStyle.Default.Superscript;
        var currentSubscript = currentStyle.Subscript ?? CellStyle.Default.Subscript;
        var currentFillStyle = _session.SelectedRangeStartStyle;

        var dialog = new FormatCellsDialogWindow
        {
            Title = UiText.Get("FormatCells_Title"),
            Width = formatCellsDialogWidth,
            Height = formatCellsDefaultDialogHeight,
            MinWidth = formatCellsDialogWidth,
            MinHeight = formatCellsDefaultDialogHeight,
            CanResize = false,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "FormatCellsCompactDialog");

        // The number-format catalog + format-code composition is the shared, portable
        // FormatCellsNumberFormatPlanner (same source the WPF dialog uses), so the Avalonia
        // Number tab composes Excel-style codes from decimal places / currency symbol /
        // negative-number style rather than a narrow fixed list.
        var numberCategories = FormatCellsNumberFormatPlanner.Categories;
        var currentNumberOption = FormatCellsNumberFormatPlanner.FindOption(currentNumberFormat);
        var currentNumberCategory = currentNumberOption?.Category
            ?? (string.IsNullOrWhiteSpace(currentNumberFormat)
                || string.Equals(currentNumberFormat, "General", StringComparison.OrdinalIgnoreCase)
                    ? "General"
                    : "Custom");
        var numberCategoryList = new ListBox
        {
            ItemsSource = numberCategories,
            SelectedItem = numberCategories.Contains(currentNumberCategory)
                ? currentNumberCategory
                : numberCategories[0],
            MinWidth = 150,
            Height = 278,
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
        };
        AutomationProperties.SetName(numberCategoryList, "Category");
        AutomationProperties.SetAutomationId(numberCategoryList, "FormatCellsNumberCategoryList");
        numberCategoryList.FontSize = 12;
        numberCategoryList.FontFamily = FormulaBarFontFamily;

        var numberFormatBox = new ComboBox
        {
            MinWidth = 260,
        };
        AutomationProperties.SetName(numberFormatBox, "Type");
        AutomationProperties.SetAutomationId(numberFormatBox, "FormatCellsNumberFormatBox");
        ApplyDialogComboBoxChrome(numberFormatBox);

        var numberDecimalPlacesBox = new TextBox
        {
            Text = FormatCellsNumberFormatPlanner.DecimalPlacesForFormat(currentNumberFormat)
                .ToString(CultureInfo.InvariantCulture),
            MinWidth = 100,
        };
        AutomationProperties.SetName(numberDecimalPlacesBox, "Decimal places");
        AutomationProperties.SetAutomationId(numberDecimalPlacesBox, "FormatCellsNumberDecimalPlacesBox");
        ApplyDialogTextBoxChrome(numberDecimalPlacesBox);

        // Derives which entry in FormatCellsNumberFormatPlanner.NegativeOptions matches the
        // negative (second) section of a Number/Currency format code, mirroring the encoding
        // FormatCellsNumberFormatPlanner.ApplyNegativeFormat uses when building these codes:
        // 0 = plain, 1 = "[Red]-", 2 = "(...)", 3 = "[Red](...)". Falls back to 0 (no negative
        // section, or a format this dialog doesn't otherwise recognize as Number/Currency).
        static int NegativeIndexForFormat(string? format)
        {
            if (string.IsNullOrWhiteSpace(format))
                return 0;

            var sections = format.Split(';');
            if (sections.Length < 2)
                return 0;

            var negativeSection = sections[1];
            var hasRed = negativeSection.Contains("[Red]", StringComparison.OrdinalIgnoreCase);
            var hasParens = negativeSection.Contains('(', StringComparison.Ordinal)
                && negativeSection.Contains(')', StringComparison.Ordinal);

            return (hasRed, hasParens) switch
            {
                (false, false) => 0,
                (true, false) => 1,
                (false, true) => 2,
                (true, true) => 3,
            };
        }

        // Derives the currency symbol seed for the Symbol combo from a Currency/Accounting
        // format's actual leading (or accounting-style embedded) symbol, so a no-edit OK
        // round-trips e.g. a Euro/Pound/Yen cell instead of silently coercing it to "$". Only
        // checks the plain single-symbol/code entries (e.g. "$", "€", "EUR") that
        // FormatCellsNumberFormatPlanner.Symbols always includes verbatim (see
        // BuildSymbolLabelMap) - those are exactly the raw symbols BuildCurrencyFormat /
        // BuildAccountingFormat embed into the code, so they round-trip losslessly as both the
        // seed and the resolved format's symbol.
        static string? SymbolForFormat(string? format)
        {
            if (string.IsNullOrWhiteSpace(format))
                return null;

            foreach (var symbol in new[] { "$", "€", "£", "¥", "EUR", "GBP", "JPY" })
            {
                if (format.Contains(symbol, StringComparison.Ordinal)
                    && FormatCellsNumberFormatPlanner.Symbols.Contains(symbol))
                    return symbol;
            }

            return null;
        }

        // Seed the symbol/negative-style controls from the cell's ACTUAL current format code
        // (same rationale as the Custom-code seeding above - see F10): a no-edit open+OK must
        // round-trip the cell's real currency symbol and red/parentheses negative style instead
        // of silently coercing them to "$" / the plain "-1234.10" default.
        var currentNumberNegativeIndex = NegativeIndexForFormat(currentNumberFormat);
        var currentNumberSymbol = SymbolForFormat(currentNumberFormat);

        var numberSymbols = FormatCellsNumberFormatPlanner.Symbols;
        var numberSymbolBox = new ComboBox
        {
            ItemsSource = numberSymbols,
            SelectedItem = currentNumberSymbol is { } seededSymbol && numberSymbols.Contains(seededSymbol)
                ? seededSymbol
                : (numberSymbols.Contains("$") ? "$" : (numberSymbols.Count > 0 ? numberSymbols[0] : null)),
            MinWidth = 220,
        };
        AutomationProperties.SetName(numberSymbolBox, "Symbol");
        AutomationProperties.SetAutomationId(numberSymbolBox, "FormatCellsNumberSymbolBox");
        ApplyDialogComboBoxChrome(numberSymbolBox);

        var numberNegativeBox = new ListBox
        {
            ItemsSource = FormatCellsNumberFormatPlanner.NegativeOptions,
            SelectedIndex = currentNumberNegativeIndex,
            MinWidth = 200,
            Height = 96,
        };
        AutomationProperties.SetName(numberNegativeBox, "Negative numbers");
        AutomationProperties.SetAutomationId(numberNegativeBox, "FormatCellsNumberNegativeBox");

        var numberPreview = new TextBlock
        {
            Text = FormatCellsNumberFormatPlanner.PreviewForFormat(currentNumberFormat),
            MinHeight = 28,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
            FontWeight = FontWeight.Bold,
        };
        AutomationProperties.SetAutomationId(numberPreview, "FormatCellsNumberPreview");

        var numberGeneralDescription = new TextBlock
        {
            Text = UiText.Get("FormatCells_GeneralFormatDescription"),
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 0),
        };
        AutomationProperties.SetAutomationId(numberGeneralDescription, "FormatCellsGeneralDescription");

        var syncingNumberControls = false;
        StackPanel? numberTypeField = null;
        StackPanel? numberDecimalPlacesField = null;
        StackPanel? numberSymbolField = null;
        StackPanel? numberNegativeNumbersField = null;

        string? ResolveSelectedNumberFormatCode()
        {
            return FormatCellsNumberFormatPlanner.ResolveSelectedNumberFormat(
                numberCategoryList.SelectedItem as string,
                numberFormatBox.SelectedItem as string ?? string.Empty,
                numberFormatBox.SelectedIndex,
                numberDecimalPlacesBox.Text,
                numberSymbolBox.SelectedItem as string ?? numberSymbolBox.Text,
                numberNegativeBox.SelectedIndex);
        }

        void RefreshNumberPreview()
        {
            var typeText = numberFormatBox.SelectedItem as string ?? string.Empty;
            var resolved = ResolveSelectedNumberFormatCode();
            numberPreview.Text = FormatCellsNumberFormatPlanner.PreviewForFormat(
                resolved ?? (string.IsNullOrEmpty(typeText) ? currentNumberFormat : typeText));
        }

        void ApplyNumberControlAvailability()
        {
            var availability = FormatCellsNumberControlPlanner.Plan(numberCategoryList.SelectedItem as string);
            numberGeneralDescription.IsVisible = availability.ShowsGeneralDescription;
            if (numberTypeField is not null)
                numberTypeField.IsVisible = availability.ShowsType;
            if (numberDecimalPlacesField is not null)
                numberDecimalPlacesField.IsVisible = availability.UsesDecimals;
            if (numberSymbolField is not null)
                numberSymbolField.IsVisible = availability.UsesSymbol;
            if (numberNegativeNumbersField is not null)
                numberNegativeNumbersField.IsVisible = availability.UsesNegativeOptions;
            numberDecimalPlacesBox.IsEnabled = availability.UsesDecimals;
            numberSymbolBox.IsEnabled = availability.UsesSymbol;
            numberNegativeBox.IsEnabled = availability.UsesNegativeOptions;
        }

        void RefreshNumberTypeChoices()
        {
            var category = numberCategoryList.SelectedItem as string ?? currentNumberCategory;
            var labels = FormatCellsNumberFormatPlanner.LabelsForCategory(category);
            // Seed with the cell's ACTUAL current format code even when it isn't one of the
            // fixed presets (e.g. a custom code like "0.0000"), so a no-edit open+OK round-trips
            // it unchanged instead of silently coercing it to the first preset in the category
            // (data loss - see F10).
            if (string.Equals(category, currentNumberCategory, StringComparison.Ordinal)
                && currentNumberOption is null
                && !string.IsNullOrWhiteSpace(currentNumberFormat)
                && !labels.Contains(currentNumberFormat))
            {
                labels = labels.Append(currentNumberFormat).ToArray();
            }
            var previous = numberFormatBox.SelectedItem as string;
            numberFormatBox.ItemsSource = labels;
            numberFormatBox.SelectedItem = previous is not null && labels.Contains(previous)
                ? previous
                : (string.Equals(category, currentNumberCategory, StringComparison.Ordinal)
                    && currentNumberOption is null
                    && labels.Contains(currentNumberFormat)
                        ? currentNumberFormat
                        : (labels.Count > 0 ? labels[0] : null));
        }

        void SyncDecimalPlacesFromType()
        {
            if (syncingNumberControls || numberFormatBox.SelectedItem is not string label)
                return;
            if (!FormatCellsNumberControlPlanner.Plan(numberCategoryList.SelectedItem as string).UsesDecimals)
                return;
            var code = FormatCellsNumberFormatPlanner.ResolveNumberFormat(label, numberFormatBox.SelectedIndex);
            if (code is null)
                return;
            syncingNumberControls = true;
            numberDecimalPlacesBox.Text = FormatCellsNumberFormatPlanner.DecimalPlacesForFormat(code)
                .ToString(CultureInfo.InvariantCulture);
            syncingNumberControls = false;
        }

        // Same round-trip rationale as RefreshNumberTypeChoices/SyncDecimalPlacesFromType above:
        // re-derive the symbol/negative-style seeds from the cell's actual format only while the
        // Category selection is still the cell's original category, so switching away and back
        // restores the real seed instead of leaving behind a default picked for another category.
        void SyncSymbolAndNegativeFromCategory()
        {
            var category = numberCategoryList.SelectedItem as string ?? currentNumberCategory;
            var isOriginalCategory = string.Equals(category, currentNumberCategory, StringComparison.Ordinal);

            var negativeIndex = isOriginalCategory ? currentNumberNegativeIndex : 0;
            if (numberNegativeBox.SelectedIndex != negativeIndex)
                numberNegativeBox.SelectedIndex = negativeIndex;

            var symbol = isOriginalCategory && currentNumberSymbol is { } seededSymbol && numberSymbols.Contains(seededSymbol)
                ? seededSymbol
                : (numberSymbols.Contains("$") ? "$" : (numberSymbols.Count > 0 ? numberSymbols[0] : null));
            if (!Equals(numberSymbolBox.SelectedItem, symbol))
                numberSymbolBox.SelectedItem = symbol;
        }

        numberCategoryList.SelectionChanged += (_, _) =>
        {
            RefreshNumberTypeChoices();
            SyncSymbolAndNegativeFromCategory();
            ApplyNumberControlAvailability();
            RefreshNumberPreview();
        };
        numberFormatBox.SelectionChanged += (_, _) =>
        {
            SyncDecimalPlacesFromType();
            RefreshNumberPreview();
        };
        numberDecimalPlacesBox.TextChanged += (_, _) =>
        {
            if (!syncingNumberControls)
                RefreshNumberPreview();
        };
        numberSymbolBox.SelectionChanged += (_, _) => RefreshNumberPreview();
        numberNegativeBox.SelectionChanged += (_, _) => RefreshNumberPreview();

        RefreshNumberTypeChoices();
        if (currentNumberOption is { } currentOption
            && FormatCellsNumberFormatPlanner.LabelsForCategory(currentNumberCategory).Contains(currentOption.Label))
        {
            numberFormatBox.SelectedItem = currentOption.Label;
        }
        ApplyNumberControlAvailability();
        RefreshNumberPreview();

        var horizontalAlignmentBox = CreateFormatCellsComboBox(
            "FormatCellsHorizontalAlignmentBox",
            CreateFormatCellsHorizontalAlignmentChoices(),
            currentHorizontalAlignment);
        horizontalAlignmentBox.Width = 564;
        var verticalAlignmentBox = CreateFormatCellsComboBox(
            "FormatCellsVerticalAlignmentBox",
            CreateFormatCellsVerticalAlignmentChoices(),
            currentVerticalAlignment);
        verticalAlignmentBox.Width = 564;
        var wrapTextBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_WrapText"), "FormatCellsWrapTextBox", _session.IsSelectedRangeStartWrapText);
        var shrinkToFitBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_ShrinkToFit"), "FormatCellsShrinkToFitBox", currentShrinkToFit);
        var mergeCellsBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_MergeCells"), "FormatCellsMergeCellsBox", currentMergeCells);
        var indentLevelBox = new TextBox
        {
            Text = currentIndentLevel.ToString(CultureInfo.InvariantCulture),
            MinWidth = 100,
            Width = 564,
        };
        AutomationProperties.SetName(indentLevelBox, "Indent level");
        AutomationProperties.SetAutomationId(indentLevelBox, "FormatCellsIndentLevelBox");
        ApplyDialogTextBoxChrome(indentLevelBox);

        var textRotationBox = new TextBox
        {
            Text = currentTextRotation.ToString(CultureInfo.InvariantCulture),
            MinWidth = 100,
            Width = 564,
        };
        AutomationProperties.SetName(textRotationBox, "Text rotation");
        AutomationProperties.SetAutomationId(textRotationBox, "FormatCellsTextRotationBox");
        ApplyDialogTextBoxChrome(textRotationBox);

        var boldBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Bold"), "FormatCellsBoldBox", _session.IsSelectedRangeStartBold);
        var italicBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Italic"), "FormatCellsItalicBox", _session.IsSelectedRangeStartItalic);
        var underlineBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Underline"), "FormatCellsUnderlineBox", currentUnderline);
        var doubleUnderlineBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_DoubleUnderline"), "FormatCellsDoubleUnderlineBox", currentDoubleUnderline);
        var strikethroughBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Strikethrough"), "FormatCellsStrikethroughBox", _session.IsSelectedRangeStartStrikethrough);
        var superscriptBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Superscript"), "FormatCellsSuperscriptBox", currentSuperscript);
        var subscriptBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Subscript"), "FormatCellsSubscriptBox", currentSubscript);
        superscriptBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty && superscriptBox.IsChecked == true)
                subscriptBox.IsChecked = false;
        };
        subscriptBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty && subscriptBox.IsChecked == true)
                superscriptBox.IsChecked = false;
        };

        var fontNameBox = new TextBox
        {
            Text = currentFontName,
            MinWidth = 180,
        };
        AutomationProperties.SetName(fontNameBox, "Font");
        AutomationProperties.SetAutomationId(fontNameBox, "FormatCellsFontNameBox");
        ApplyDialogTextBoxChrome(fontNameBox);

        var fontSizeBox = new TextBox
        {
            Text = currentFontSize.ToString("0.##", CultureInfo.InvariantCulture),
            MinWidth = 100,
        };
        AutomationProperties.SetName(fontSizeBox, "Size");
        AutomationProperties.SetAutomationId(fontSizeBox, "FormatCellsFontSizeBox");
        ApplyDialogTextBoxChrome(fontSizeBox);

        // Windows shows the font name + size as selectable LISTS. We keep the existing text
        // boxes as the value sink that feeds the result (FontName/FontSize), and add list
        // pickers as the primary selectors that write the chosen value into those boxes.
        var fontNameChoices = new[]
        {
            "Calibri", "Arial", "Times New Roman", "Verdana", "Tahoma", "Segoe UI",
            "Courier New", "Georgia", "Cambria", "Consolas", "Comic Sans MS", "Trebuchet MS",
        };
        var fontNameList = new ListBox
        {
            ItemsSource = fontNameChoices,
            SelectedItem = Array.Find(fontNameChoices, n => string.Equals(n, currentFontName, StringComparison.OrdinalIgnoreCase)),
            Height = 120,
            MinWidth = 180,
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };
        AutomationProperties.SetName(fontNameList, "Font");
        AutomationProperties.SetAutomationId(fontNameList, "FormatCellsFontNameList");
        fontNameList.SelectionChanged += (_, _) =>
        {
            if (fontNameList.SelectedItem is string name)
                fontNameBox.Text = name;
        };

        var fontSizeChoices = new[] { "8", "9", "10", "11", "12", "14", "16", "18", "20", "24", "28", "36", "48", "72" };
        var fontSizeList = new ListBox
        {
            ItemsSource = fontSizeChoices,
            SelectedItem = Array.Find(fontSizeChoices, s => s == currentFontSize.ToString("0.##", CultureInfo.InvariantCulture)),
            Height = 120,
            MinWidth = 70,
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };
        AutomationProperties.SetName(fontSizeList, "Size");
        AutomationProperties.SetAutomationId(fontSizeList, "FormatCellsFontSizeList");
        fontSizeList.SelectionChanged += (_, _) =>
        {
            if (fontSizeList.SelectedItem is string size)
                fontSizeBox.Text = size;
        };

        var fontColorBox = CreateFormatCellsColorPicker(UiText.Get("FormatCells_NoChange"), includeClear: false, UiText.Get("FormatCells_MoreFontColors"));
        AutomationProperties.SetName(fontColorBox, "Font color");
        AutomationProperties.SetAutomationId(fontColorBox, "FormatCellsFontColorBox");
        var normalFontBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_NormalFont"), "FormatCellsNormalFontBox", false);
        normalFontBox.PropertyChanged += (_, e) =>
        {
            if (e.Property != ToggleButton.IsCheckedProperty || normalFontBox.IsChecked != true)
                return;

            var normal = CellStyle.Default;
            fontNameBox.Text = normal.FontName;
            fontSizeBox.Text = normal.FontSize.ToString("0.##", CultureInfo.InvariantCulture);
            boldBox.IsChecked = normal.Bold;
            italicBox.IsChecked = normal.Italic;
            underlineBox.IsChecked = normal.Underline;
            doubleUnderlineBox.IsChecked = normal.DoubleUnderline;
            strikethroughBox.IsChecked = normal.Strikethrough;
            superscriptBox.IsChecked = normal.Superscript;
            subscriptBox.IsChecked = normal.Subscript;
            SelectFormatCellsColor(fontColorBox, normal.FontColor);
        };

        // Live font preview: a sample TextBlock reflecting bold/italic/underline/size/color as the
        // user edits, mirroring the WPF preview.
        var fontPreview = new TextBlock
        {
            Text = "AaBbCcYyZz",
            MinHeight = 36,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
        };
        AutomationProperties.SetAutomationId(fontPreview, "FormatCellsFontPreview");

        void RefreshFontPreview()
        {
            if (normalFontBox.IsChecked == true)
            {
                var normal = CellStyle.Default;
                fontPreview.FontWeight = FontWeight.Normal;
                fontPreview.FontStyle = FontStyle.Normal;
                fontPreview.TextDecorations = null;
                fontPreview.FontSize = normal.FontSize;
                fontPreview.FontFamily = FontFamily.Default;
                fontPreview.Foreground = Brush(normal.FontColor);
                return;
            }

            fontPreview.FontWeight = boldBox.IsChecked == true ? FontWeight.Bold : FontWeight.Normal;
            fontPreview.FontStyle = italicBox.IsChecked == true ? FontStyle.Italic : FontStyle.Normal;

            var decorations = new TextDecorationCollection();
            if (underlineBox.IsChecked == true || doubleUnderlineBox.IsChecked == true)
                decorations.Add(new TextDecoration { Location = TextDecorationLocation.Underline });
            if (strikethroughBox.IsChecked == true)
                decorations.Add(new TextDecoration { Location = TextDecorationLocation.Strikethrough });
            fontPreview.TextDecorations = decorations.Count > 0 ? decorations : null;

            if (double.TryParse(fontSizeBox.Text?.Trim(), NumberStyles.Float, CultureInfo.CurrentCulture, out var size)
                && double.IsFinite(size) && size > 0)
            {
                fontPreview.FontSize = Math.Clamp(size, 6, 72);
            }

            var fontName = fontNameBox.Text?.Trim();
            fontPreview.FontFamily = string.IsNullOrWhiteSpace(fontName)
                ? FontFamily.Default
                : new FontFamily(fontName);

            var color = (fontColorBox.SelectedItem as FormatCellsColorChoice)?.Color;
            fontPreview.Foreground = color is { } chosen ? Brush(chosen) : PrimaryInk;
        }

        boldBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        italicBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        underlineBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        doubleUnderlineBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        strikethroughBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        normalFontBox.IsCheckedChanged += (_, _) => RefreshFontPreview();
        fontSizeBox.TextChanged += (_, _) => RefreshFontPreview();
        fontNameBox.TextChanged += (_, _) => RefreshFontPreview();
        fontColorBox.SelectionChanged += (_, _) => RefreshFontPreview();
        RefreshFontPreview();

        var fillEditor = new FormatCellsFillEditor(
            _recentColors,
            ShowMoreColorsDialogAsync,
            UiText.Get,
            _session.Workbook.Theme,
            currentFillStyle);
        var fillColorBox = fillEditor.FillColorPicker;
        var fillPatternStyleBox = fillEditor.FillPatternStyleBox;
        var fillPatternColorBox = fillEditor.PatternColorPicker;

        var borderPresetBox = new ComboBox
        {
            ItemsSource = CreateFormatCellsBorderPresetChoices(),
            SelectedIndex = 0,
            MinWidth = 220,
        };
        AutomationProperties.SetName(borderPresetBox, "Border preset");
        AutomationProperties.SetAutomationId(borderPresetBox, "FormatCellsBorderPresetBox");
        ApplyDialogComboBoxChrome(borderPresetBox);
        // Windows renders the line style as a scrollable textual list, not a combo.
        // Keep the FormatCellsBorderStyleBox automation id + the FormatCellsNullableChoice
        // SelectedItem contract so Accept()/SelectedBorderLineStyle() are unchanged.
        var borderStyleBox = CreateFormatCellsBorderStyleListBox(
            "FormatCellsBorderStyleBox",
            BorderStyle.Thin);
        var borderColorBox = CreateFormatCellsColorPicker(UiText.Get("FormatCells_NoChange"), includeClear: false, UiText.Get("FormatCells_MoreBorderColors"));
        borderColorBox.ConfigureCompactPickButton();
        borderColorBox.BorderBrush = Brush(112, 112, 112);
        borderColorBox.CornerRadius = new CornerRadius(0);
        AutomationProperties.SetName(borderColorBox, "Border color");
        AutomationProperties.SetAutomationId(borderColorBox, "FormatCellsBorderColorBox");

        TextBox CreateBorderColorTextBox(FormatCellsColorPicker picker, string automationId)
        {
            var box = new TextBox
            {
                Text = FormatRgb(CellColor.Black),
                Width = 120,
                Height = 24,
                FontSize = 12,
                FontFamily = FormulaBarFontFamily,
            };
            AutomationProperties.SetAutomationId(box, automationId);
            ApplyDialogTextBoxChrome(box);
            box.BorderBrush = Brush(171, 173, 179);
            picker.SelectionChanged += (_, _) =>
            {
                if (picker.SelectedColor is { } color)
                    box.Text = FormatRgb(color);
            };
            box.LostFocus += (_, _) =>
            {
                if (TryParseRgb(box.Text, out var color))
                    picker.SelectColor(color);
            };
            return box;
        }

        var borderColorTextBox = CreateBorderColorTextBox(borderColorBox, "FormatCellsBorderColorTextBox");
        borderColorTextBox.Width = 118;

        // Per-side border controls mirror WPF: each edge is a toggle honoring the selected line
        // style + color, composed alongside the whole-cell preset buttons (None/Outline/Inside).
        // The toggle state and the chosen line style/color flow into the shared
        // FormatCellsCompactRequest per-side fields so WPF/macOS map identically.
        var borderTopToggle = CreateFormatCellsBorderSideToggle("Top", "FormatCellsBorderTopToggle");
        var borderBottomToggle = CreateFormatCellsBorderSideToggle("Bottom", "FormatCellsBorderBottomToggle");
        var borderLeftToggle = CreateFormatCellsBorderSideToggle("Left", "FormatCellsBorderLeftToggle");
        var borderRightToggle = CreateFormatCellsBorderSideToggle("Right", "FormatCellsBorderRightToggle");
        var borderInsideHorizontalToggle = CreateFormatCellsBorderSideToggle("Inside horizontal", "FormatCellsBorderInsideHorizontalToggle");
        var borderInsideVerticalToggle = CreateFormatCellsBorderSideToggle("Inside vertical", "FormatCellsBorderInsideVerticalToggle");
        // WPF exposes interior borders through the Inside preset and renders the resulting
        // lines in the preview; it does not expose separate Inside horizontal/vertical buttons.
        // Keep these state holders for the shared planner, but do not put them in the visual tree.
        borderInsideHorizontalToggle.IsVisible = false;
        borderInsideVerticalToggle.IsVisible = false;

        // Per-edge "Individual border details": each outer edge (Top/Right/Bottom/Left) gets its
        // OWN style ComboBox (a "None" entry + the BorderStyle values) and its OWN color picker, so
        // every edge can carry an independent Style + Color into FormatCellsCompactRequest (mirrors
        // Excel's "Individual border details" grid). These are the source of truth read in Accept();
        // the diagram toggles + Line group stay in two-way sync with them below.
        var borderEdgeStyleChoices = CreateFormatCellsBorderStyleListChoices();
        ComboBox CreateBorderEdgeStyleBox(string automationId)
        {
            var box = new ComboBox
            {
                ItemsSource = borderEdgeStyleChoices,
                SelectedIndex = 0, // "None"
                MinWidth = 150,
                Width = 150,
            };
            AutomationProperties.SetAutomationId(box, automationId);
            ApplyDialogComboBoxChrome(box);
            box.Background = Brush(240, 240, 240);
            box.BorderBrush = Brush(171, 173, 179);
            return box;
        }
        var borderTopStyleBox = CreateBorderEdgeStyleBox("FormatCellsBorderTopStyleBox");
        var borderRightStyleBox = CreateBorderEdgeStyleBox("FormatCellsBorderRightStyleBox");
        var borderBottomStyleBox = CreateBorderEdgeStyleBox("FormatCellsBorderBottomStyleBox");
        var borderLeftStyleBox = CreateBorderEdgeStyleBox("FormatCellsBorderLeftStyleBox");

        FormatCellsColorPicker CreateBorderEdgeColorBox(string automationId)
        {
            var box = CreateFormatCellsColorPicker(UiText.Get("FormatCells_NoChange"), includeClear: false, UiText.Get("FormatCells_MoreBorderColors"));
            box.ConfigureCompactPickButton();
            box.BorderBrush = Brush(112, 112, 112);
            box.CornerRadius = new CornerRadius(0);
            AutomationProperties.SetAutomationId(box, automationId);
            return box;
        }
        var borderTopColorBox = CreateBorderEdgeColorBox("FormatCellsBorderTopColorBox");
        var borderRightColorBox = CreateBorderEdgeColorBox("FormatCellsBorderRightColorBox");
        var borderBottomColorBox = CreateBorderEdgeColorBox("FormatCellsBorderBottomColorBox");
        var borderLeftColorBox = CreateBorderEdgeColorBox("FormatCellsBorderLeftColorBox");
        var borderTopColorTextBox = CreateBorderColorTextBox(borderTopColorBox, "FormatCellsBorderTopColorTextBox");
        var borderRightColorTextBox = CreateBorderColorTextBox(borderRightColorBox, "FormatCellsBorderRightColorTextBox");
        var borderBottomColorTextBox = CreateBorderColorTextBox(borderBottomColorBox, "FormatCellsBorderBottomColorTextBox");
        var borderLeftColorTextBox = CreateBorderColorTextBox(borderLeftColorBox, "FormatCellsBorderLeftColorTextBox");

        // Re-entrancy guard so diagram-toggle <-> per-edge-style two-way sync doesn't loop.
        var borderSyncing = false;

        var borderPreview = new Border
        {
            Width = 96,
            Height = 64,
            Background = Brushes.White,
            BorderBrush = Brush(112, 112, 112),
            BorderThickness = new Thickness(1),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Left,
        };
        AutomationProperties.SetAutomationId(borderPreview, "FormatCellsBorderPreview");
        var borderPreviewGrid = new AvaloniaGrid
        {
            Width = 96,
            Height = 64,
            ColumnDefinitions = new ColumnDefinitions("*,*"),
            RowDefinitions = new RowDefinitions("*,*"),
        };
        borderPreview.Child = borderPreviewGrid;

        CellColor SelectedBorderLineColor() =>
            (borderColorBox.SelectedItem as FormatCellsColorChoice)?.Color ?? CellColor.Black;
        BorderStyle SelectedBorderLineStyle() =>
            borderStyleBox.SelectedItem is FormatCellsNullableChoice<BorderStyle> { Value: { } style }
                ? style
                : BorderStyle.Thin;
        CellBorder SelectedBorderLine() => new(SelectedBorderLineStyle(), SelectedBorderLineColor());

        // The real BorderStyle selected in an edge's style box, or null when the box is on "None".
        static BorderStyle? EdgeStyle(ComboBox box) =>
            box.SelectedItem is FormatCellsNullableChoice<BorderStyle> choice ? choice.Value : null;
        // The color chosen in an edge's color picker, falling back to the shared Line color when unset.
        CellColor EdgeColor(FormatCellsColorPicker box) =>
            box.SelectedColor ?? SelectedBorderLineColor();
        // Compose this edge's per-edge value. Returns null (no change) while the edge still matches the
        // value the dialog seeded from the cell's current border, so an untouched edge never re-applies
        // the active cell's border across a mixed-border range; an explicit edit applies its style+colour.
        CellBorder? ReadBorderSide(ComboBox styleBox, FormatCellsColorPicker colorBox, (BorderStyle? Style, CellColor Color) seeded)
        {
            var style = EdgeStyle(styleBox);
            var color = EdgeColor(colorBox);
            if (style == seeded.Style && (style is null || color == seeded.Color))
                return null;
            return style is { } s ? new CellBorder(s, color) : null;
        }

        // Select the "None"/style entry in an edge's style box by BorderStyle (null => None).
        void SetEdgeStyle(ComboBox box, BorderStyle? style)
        {
            foreach (var choice in borderEdgeStyleChoices)
            {
                if (choice.Value == style)
                {
                    box.SelectedItem = choice;
                    return;
                }
            }
            box.SelectedIndex = 0;
        }

        void RenderBorderPreview()
        {
            borderPreviewGrid.Children.Clear();
            var insideLine = SelectedBorderLine();
            var insideBrush = Brush(insideLine.Color);
            var insideThickness = FormatCellsBorderPreviewThickness(insideLine.Style);

            // Each outer edge draws with ITS OWN style + color (from the per-edge boxes); falls back to
            // the shared Line selection for color so the swatch still reads when no edge color was picked.
            void AddEdge(BorderStyle? style, IBrush brush, double left, double top, double right, double bottom)
            {
                if (style is not { } edgeStyle)
                    return;
                var t = FormatCellsBorderPreviewThickness(edgeStyle);
                var edge = new Border
                {
                    BorderBrush = brush,
                    BorderThickness = new Thickness(left > 0 ? t : 0, top > 0 ? t : 0, right > 0 ? t : 0, bottom > 0 ? t : 0),
                    IsHitTestVisible = false,
                    [AvaloniaGrid.RowProperty] = 0,
                    [AvaloniaGrid.ColumnProperty] = 0,
                    [AvaloniaGrid.RowSpanProperty] = 2,
                    [AvaloniaGrid.ColumnSpanProperty] = 2,
                };
                borderPreviewGrid.Children.Add(edge);
            }

            AddEdge(EdgeStyle(borderTopStyleBox), Brush(EdgeColor(borderTopColorBox)), 0, 1, 0, 0);
            AddEdge(EdgeStyle(borderBottomStyleBox), Brush(EdgeColor(borderBottomColorBox)), 0, 0, 0, 1);
            AddEdge(EdgeStyle(borderLeftStyleBox), Brush(EdgeColor(borderLeftColorBox)), 1, 0, 0, 0);
            AddEdge(EdgeStyle(borderRightStyleBox), Brush(EdgeColor(borderRightColorBox)), 0, 0, 1, 0);
            if (borderInsideVerticalToggle.IsChecked == true)
            {
                borderPreviewGrid.Children.Add(new Border
                {
                    BorderBrush = insideBrush,
                    BorderThickness = new Thickness(insideThickness, 0, 0, 0),
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
                    IsHitTestVisible = false,
                    [AvaloniaGrid.RowProperty] = 0,
                    [AvaloniaGrid.ColumnProperty] = 1,
                    [AvaloniaGrid.RowSpanProperty] = 2,
                });
            }
            if (borderInsideHorizontalToggle.IsChecked == true)
            {
                borderPreviewGrid.Children.Add(new Border
                {
                    BorderBrush = insideBrush,
                    BorderThickness = new Thickness(0, insideThickness, 0, 0),
                    VerticalAlignment = AvaloniaVerticalAlignment.Center,
                    IsHitTestVisible = false,
                    [AvaloniaGrid.RowProperty] = 1,
                    [AvaloniaGrid.ColumnProperty] = 0,
                    [AvaloniaGrid.ColumnSpanProperty] = 2,
                });
            }
        }

        // Toggle ON an outer edge => set its style box to the shared Line style + its color to the
        // shared Line color; toggle OFF => set its style box to "None". Guarded against re-entrancy.
        void SyncEdgeFromToggle(ToggleButton toggle, ComboBox styleBox, FormatCellsColorPicker colorBox)
        {
            if (borderSyncing)
                return;
            borderSyncing = true;
            try
            {
                if (toggle.IsChecked == true)
                {
                    SetEdgeStyle(styleBox, SelectedBorderLineStyle());
                    colorBox.SelectColor(SelectedBorderLineColor());
                }
                else
                {
                    SetEdgeStyle(styleBox, null);
                }
            }
            finally
            {
                borderSyncing = false;
            }
            RenderBorderPreview();
        }

        // A real style in an edge's style box checks its diagram toggle; "None" unchecks it.
        void SyncToggleFromEdge(ComboBox styleBox, ToggleButton toggle)
        {
            if (borderSyncing)
                return;
            borderSyncing = true;
            try
            {
                toggle.IsChecked = EdgeStyle(styleBox) is not null;
            }
            finally
            {
                borderSyncing = false;
            }
            RenderBorderPreview();
        }

        void SetBorderSidesChecked(bool top, bool bottom, bool left, bool right, bool insideHorizontal, bool insideVertical)
        {
            // Drive BOTH the diagram toggles and the per-edge style boxes consistently. An edge that is
            // turned on adopts the current shared Line style/color; an edge turned off becomes "None".
            borderSyncing = true;
            try
            {
                var sharedStyle = SelectedBorderLineStyle();
                var sharedColor = SelectedBorderLineColor();
                void Apply(bool on, ToggleButton toggle, ComboBox styleBox, FormatCellsColorPicker colorBox)
                {
                    toggle.IsChecked = on;
                    if (on)
                    {
                        SetEdgeStyle(styleBox, sharedStyle);
                        colorBox.SelectColor(sharedColor);
                    }
                    else
                    {
                        SetEdgeStyle(styleBox, null);
                    }
                }
                Apply(top, borderTopToggle, borderTopStyleBox, borderTopColorBox);
                Apply(bottom, borderBottomToggle, borderBottomStyleBox, borderBottomColorBox);
                Apply(left, borderLeftToggle, borderLeftStyleBox, borderLeftColorBox);
                Apply(right, borderRightToggle, borderRightStyleBox, borderRightColorBox);
                borderInsideHorizontalToggle.IsChecked = insideHorizontal;
                borderInsideVerticalToggle.IsChecked = insideVertical;
            }
            finally
            {
                borderSyncing = false;
            }
            RenderBorderPreview();
        }

        var borderNoneButton = new Button { Content = UiText.Get("FormatCells_BorderPresetNone"), MinWidth = 70 };
        AutomationProperties.SetAutomationId(borderNoneButton, "FormatCellsBorderPresetNoneButton");
        ApplyDialogButtonChrome(borderNoneButton);
        borderNoneButton.Click += (_, _) => SetBorderSidesChecked(false, false, false, false, false, false);
        var borderOutlineButton = new Button { Content = UiText.Get("FormatCells_BorderPresetOutline"), MinWidth = 70 };
        AutomationProperties.SetAutomationId(borderOutlineButton, "FormatCellsBorderPresetOutlineButton");
        ApplyDialogButtonChrome(borderOutlineButton);
        borderOutlineButton.Click += (_, _) => SetBorderSidesChecked(true, true, true, true, false, false);
        var borderInsideButton = new Button { Content = UiText.Get("FormatCells_BorderPresetInside"), MinWidth = 70 };
        AutomationProperties.SetAutomationId(borderInsideButton, "FormatCellsBorderPresetInsideButton");
        ApplyDialogButtonChrome(borderInsideButton);
        borderInsideButton.Click += (_, _) => SetBorderSidesChecked(false, false, false, false, true, true);

        // Two-way diagram-toggle <-> per-edge-style sync.
        borderTopToggle.IsCheckedChanged += (_, _) => SyncEdgeFromToggle(borderTopToggle, borderTopStyleBox, borderTopColorBox);
        borderBottomToggle.IsCheckedChanged += (_, _) => SyncEdgeFromToggle(borderBottomToggle, borderBottomStyleBox, borderBottomColorBox);
        borderLeftToggle.IsCheckedChanged += (_, _) => SyncEdgeFromToggle(borderLeftToggle, borderLeftStyleBox, borderLeftColorBox);
        borderRightToggle.IsCheckedChanged += (_, _) => SyncEdgeFromToggle(borderRightToggle, borderRightStyleBox, borderRightColorBox);
        borderInsideHorizontalToggle.IsCheckedChanged += (_, _) => RenderBorderPreview();
        borderInsideVerticalToggle.IsCheckedChanged += (_, _) => RenderBorderPreview();
        borderTopStyleBox.SelectionChanged += (_, _) => SyncToggleFromEdge(borderTopStyleBox, borderTopToggle);
        borderBottomStyleBox.SelectionChanged += (_, _) => SyncToggleFromEdge(borderBottomStyleBox, borderBottomToggle);
        borderLeftStyleBox.SelectionChanged += (_, _) => SyncToggleFromEdge(borderLeftStyleBox, borderLeftToggle);
        borderRightStyleBox.SelectionChanged += (_, _) => SyncToggleFromEdge(borderRightStyleBox, borderRightToggle);
        borderTopColorBox.SelectionChanged += (_, _) => RenderBorderPreview();
        borderBottomColorBox.SelectionChanged += (_, _) => RenderBorderPreview();
        borderLeftColorBox.SelectionChanged += (_, _) => RenderBorderPreview();
        borderRightColorBox.SelectionChanged += (_, _) => RenderBorderPreview();
        borderStyleBox.SelectionChanged += (_, _) => RenderBorderPreview();
        borderColorBox.SelectionChanged += (_, _) => RenderBorderPreview();

        // Seed the per-edge controls from the active cell's current borders (matching the WPF host) so
        // opening Format Cells shows the existing borders. Guarded by borderSyncing so the two-way
        // toggle/style handlers don't fight while seeding; the seeded values are captured so an
        // untouched edge reads back as "no change" (see ReadBorderSide).
        void SeedBorderEdge(ComboBox styleBox, FormatCellsColorPicker colorBox, ToggleButton toggle, CellBorder? border)
        {
            if (border is { } b && b.Style != BorderStyle.None)
            {
                SetEdgeStyle(styleBox, b.Style);
                colorBox.SelectColor(b.Color);
                toggle.IsChecked = true;
            }
            else
            {
                SetEdgeStyle(styleBox, null);
                toggle.IsChecked = false;
            }
        }

        borderSyncing = true;
        try
        {
            SeedBorderEdge(borderTopStyleBox, borderTopColorBox, borderTopToggle, currentStyle.BorderTop);
            SeedBorderEdge(borderRightStyleBox, borderRightColorBox, borderRightToggle, currentStyle.BorderRight);
            SeedBorderEdge(borderBottomStyleBox, borderBottomColorBox, borderBottomToggle, currentStyle.BorderBottom);
            SeedBorderEdge(borderLeftStyleBox, borderLeftColorBox, borderLeftToggle, currentStyle.BorderLeft);
        }
        finally
        {
            borderSyncing = false;
        }

        var seededTopBorder = (EdgeStyle(borderTopStyleBox), EdgeColor(borderTopColorBox));
        var seededRightBorder = (EdgeStyle(borderRightStyleBox), EdgeColor(borderRightColorBox));
        var seededBottomBorder = (EdgeStyle(borderBottomStyleBox), EdgeColor(borderBottomColorBox));
        var seededLeftBorder = (EdgeStyle(borderLeftStyleBox), EdgeColor(borderLeftColorBox));

        RenderBorderPreview();

        var lockedBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Locked"), "FormatCellsLockedBox", currentLocked);
        var hiddenBox = CreateFormatCellsCheckBox(UiText.Get("FormatCells_Hidden"), "FormatCellsHiddenBox", currentHidden);
        var protectionExplanationText = new TextBlock
        {
            Text = UiText.Get("FormatCells_ProtectionExplanation"),
            Foreground = HeaderForeground,
            TextWrapping = TextWrapping.Wrap,
        };
        AutomationProperties.SetAutomationId(protectionExplanationText, "FormatCellsProtectionExplanationText");

        var okButton = new Button
        {
            Content = UiText.Get("Common_Ok"),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(okButton, "FormatCellsOkButton");
        ApplyDialogButtonChrome(okButton, width: 74, isDefault: true);
        okButton.Background = Brush(221, 221, 221);
        okButton.BorderBrush = Brush(112, 112, 112);
        okButton.CornerRadius = new CornerRadius(0);

        var cancelButton = new Button
        {
            Content = UiText.Get("Common_Cancel"),
            IsCancel = true,
            MinWidth = 74,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(cancelButton, "FormatCellsCancelButton");
        ApplyDialogButtonChrome(cancelButton, width: 74);
        cancelButton.Background = Brush(221, 221, 221);
        cancelButton.BorderBrush = Brush(112, 112, 112);
        cancelButton.CornerRadius = new CornerRadius(0);

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
            IsVisible = false,
        };

        void ShowFormatCellsError(string message)
        {
            errorText.Text = message;
            errorText.IsVisible = true;
        }

        void Accept()
        {
            if (!fillEditor.TryCommitInput(out var fillValidationMessage, out var invalidFillControl))
            {
                ShowFormatCellsError(fillValidationMessage);
                invalidFillControl?.Focus();
                return;
            }

            var normalFont = normalFontBox.IsChecked == true;
            var normalStyle = CellStyle.Default;
            string message;
            double? fontSize;
            if (normalFont)
            {
                fontSize = normalStyle.FontSize;
            }
            else if (!TryReadFormatCellsFontSize(fontSizeBox.Text, currentFontSize, out fontSize, out message))
            {
                ShowFormatCellsError(message);
                return;
            }
            if (!TryReadFormatCellsIndentLevel(indentLevelBox.Text, currentIndentLevel, out var indentLevel, out message))
            {
                ShowFormatCellsError(message);
                return;
            }
            if (!TryReadFormatCellsTextRotation(textRotationBox.Text, currentTextRotation, out var textRotation, out message))
            {
                ShowFormatCellsError(message);
                return;
            }

            var numberAvailability = FormatCellsNumberControlPlanner.Plan(numberCategoryList.SelectedItem as string);
            if (numberAvailability.UsesDecimals
                && (!int.TryParse(numberDecimalPlacesBox.Text?.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var decimalPlaces)
                    || decimalPlaces is < 0 or > 30))
            {
                ShowFormatCellsError("Decimal places must be a whole number between 0 and 30.");
                return;
            }

            var resolvedNumberFormat = ResolveSelectedNumberFormatCode();
            var numberFormat = resolvedNumberFormat is { } resolvedFormat &&
                !string.Equals(resolvedFormat, currentNumberFormat, StringComparison.Ordinal)
                    ? resolvedFormat
                    : null;
            var clearFill = fillEditor.ClearFill;
            var borderChoice = borderPresetBox.SelectedItem as FormatCellsNullableChoice<CellBorderPreset>;
            var borderStyle = borderStyleBox.SelectedItem is FormatCellsNullableChoice<BorderStyle> { Value: { } selectedBorderStyle }
                ? selectedBorderStyle
                : BorderStyle.Thin;
            var borderColor = (borderColorBox.SelectedItem as FormatCellsColorChoice)?.Color;
            var borderTopSide = ReadBorderSide(borderTopStyleBox, borderTopColorBox, seededTopBorder);
            var borderBottomSide = ReadBorderSide(borderBottomStyleBox, borderBottomColorBox, seededBottomBorder);
            var borderLeftSide = ReadBorderSide(borderLeftStyleBox, borderLeftColorBox, seededLeftBorder);
            var borderRightSide = ReadBorderSide(borderRightStyleBox, borderRightColorBox, seededRightBorder);
            // Inner horizontal/vertical edges aren't single-cell StyleDiff edges; carry them via
            // the shared Inside preset (applied per-cell by the session) when no explicit preset
            // was chosen in the preset combo.
            var hasInsideToggle = borderInsideHorizontalToggle.IsChecked == true
                || borderInsideVerticalToggle.IsChecked == true;
            var borderPreset = borderChoice?.Value
                ?? (hasInsideToggle ? CellBorderPreset.Inside : (CellBorderPreset?)null);
            var request = new FormatCellsCompactRequest(
                NumberFormat: numberFormat,
                HorizontalAlignment: ReadChangedFormatCellsValue(currentHorizontalAlignment, horizontalAlignmentBox),
                VerticalAlignment: ReadChangedFormatCellsValue(currentVerticalAlignment, verticalAlignmentBox),
                WrapText: ReadChangedFormatCellsBool(_session.IsSelectedRangeStartWrapText, wrapTextBox),
                Bold: normalFont ? normalStyle.Bold : ReadChangedFormatCellsBool(_session.IsSelectedRangeStartBold, boldBox),
                Italic: normalFont ? normalStyle.Italic : ReadChangedFormatCellsBool(_session.IsSelectedRangeStartItalic, italicBox),
                Underline: normalFont ? normalStyle.Underline : ReadChangedFormatCellsBool(currentUnderline, underlineBox),
                Strikethrough: normalFont ? normalStyle.Strikethrough : ReadChangedFormatCellsBool(_session.IsSelectedRangeStartStrikethrough, strikethroughBox),
                DoubleUnderline: normalFont ? normalStyle.DoubleUnderline : ReadChangedFormatCellsBool(currentDoubleUnderline, doubleUnderlineBox),
                Superscript: normalFont ? normalStyle.Superscript : ReadChangedFormatCellsBool(currentSuperscript, superscriptBox),
                Subscript: normalFont ? normalStyle.Subscript : ReadChangedFormatCellsBool(currentSubscript, subscriptBox),
                FontName: normalFont ? normalStyle.FontName : ReadChangedFormatCellsText(currentFontName, fontNameBox),
                FontSize: fontSize,
                FillColor: fillEditor.FillColor,
                ClearFill: clearFill,
                FillPatternStyle: clearFill ? null : ReadChangedFormatCellsValue(currentFillStyle.FillPatternStyle, fillPatternStyleBox),
                FillPatternColor: clearFill ? null : fillEditor.PatternColor,
                FontColor: normalFont ? normalStyle.FontColor : (fontColorBox.SelectedItem as FormatCellsColorChoice)?.Color,
                ShrinkToFit: ReadChangedFormatCellsBool(currentShrinkToFit, shrinkToFitBox),
                MergeCells: ReadChangedFormatCellsBool(currentMergeCells, mergeCellsBox),
                IndentLevel: indentLevel,
                TextRotation: textRotation,
                Locked: ReadChangedFormatCellsBool(currentLocked, lockedBox),
                Hidden: ReadChangedFormatCellsBool(currentHidden, hiddenBox),
                BorderTop: borderTopSide,
                BorderRight: borderRightSide,
                BorderBottom: borderBottomSide,
                BorderLeft: borderLeftSide);
            result = new FormatCellsDialogResult(request, borderPreset, borderStyle, borderColor);
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        // Number tab body: a two-column Grid matching the WPF Format Cells dialog. The
        // shared control-availability planner hides whole option panels for categories
        // such as General, rather than leaving disabled controls visible.
        var numberCategoryLabel = new TextBlock { Text = StripDisplayMnemonic(UiText.Get("FormatCells_Category")), Margin = new Thickness(0, 0, 0, 4) };
        DockPanel.SetDock(numberCategoryLabel, Dock.Top);
        var numberCategoryField = new DockPanel
        {
            LastChildFill = true,
            VerticalAlignment = AvaloniaVerticalAlignment.Stretch,
            Children =
            {
                numberCategoryLabel,
                numberCategoryList,
            },
        };
        numberTypeField = CreateFormatCellsField(UiText.Get("FormatCells_Type"), numberFormatBox);
        numberDecimalPlacesField = CreateFormatCellsField(UiText.Get("FormatCells_DecimalPlaces"), numberDecimalPlacesBox);
        numberSymbolField = CreateFormatCellsField(UiText.Get("FormatCells_Symbol"), numberSymbolBox);
        numberNegativeNumbersField = CreateFormatCellsField(UiText.Get("FormatCells_NegativeNumbers"), numberNegativeBox);
        ApplyNumberControlAvailability();
        var numberRightColumn = new StackPanel
        {
            Spacing = 10,
            Children =
            {
                new StackPanel
                {
                    Spacing = 4,
                    Children =
                    {
                        new TextBlock { Text = UiText.Get("FormatCells_Sample"), FontWeight = FontWeight.SemiBold },
                        new Border
                        {
                            BorderBrush = FormulaBarControlBorder,
                            BorderThickness = new Thickness(1),
                            Padding = new Thickness(8, 6),
                            Width = 94,
                            Height = 36,
                            HorizontalAlignment = AvaloniaHorizontalAlignment.Left,
                            Child = numberPreview,
                        },
                    },
                },
                numberGeneralDescription,
                numberTypeField!,
                numberDecimalPlacesField!,
                numberSymbolField!,
                numberNegativeNumbersField!,
            },
        };
        var numberBodyGrid = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,*"),
            ColumnSpacing = 12,
        };
        numberBodyGrid.Children.Add(numberCategoryField);
        AvaloniaGrid.SetColumn(numberCategoryField, 0);
        numberBodyGrid.Children.Add(numberRightColumn);
        AvaloniaGrid.SetColumn(numberRightColumn, 1);
        var numberTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabNumber"),
            "FormatCellsNumberTab",
            numberBodyGrid);
        var alignmentTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabAlignment"),
            "FormatCellsAlignmentTab",
            new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    CreateFormatCellsField(UiText.Get("FormatCells_HorizontalAlignment"), horizontalAlignmentBox),
                    CreateFormatCellsField(UiText.Get("FormatCells_VerticalAlignment"), verticalAlignmentBox),
                    wrapTextBox,
                    shrinkToFitBox,
                    mergeCellsBox,
                    CreateFormatCellsField(UiText.Get("FormatCells_IndentLevel015"), indentLevelBox),
                    CreateFormatCellsField(UiText.Get("FormatCells_TextRotation90To90Or255"), textRotationBox),
                },
            });
        // Font tab: Windows shows Font NAME + Size as selectable lists side by side. The
        // lists drive the existing name/size text boxes (kept below for free entry + as the
        // value sink the result reads), preserving the FontName/FontSize wiring.
        var fontNameColumn = new StackPanel
        {
            Spacing = 4,
            Children =
            {
                new TextBlock { Text = StripDisplayMnemonic(UiText.Get("FormatCells_Font")) },
                fontNameList,
                fontNameBox,
            },
        };
        var fontSizeColumn = new StackPanel
        {
            Spacing = 4,
            Children =
            {
                new TextBlock { Text = StripDisplayMnemonic(UiText.Get("FormatCells_Size")) },
                fontSizeList,
                fontSizeBox,
            },
        };
        var fontTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabFont"),
            "FormatCellsFontTab",
            new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 16,
                        Children = { fontNameColumn, fontSizeColumn },
                    },
                    new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 12,
                        Children =
                        {
                            boldBox,
                            italicBox,
                            underlineBox,
                            doubleUnderlineBox,
                            strikethroughBox,
                        },
                    },
                    new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 12,
                        Children =
                        {
                            superscriptBox,
                            subscriptBox,
                        },
                    },
                    CreateFormatCellsField(UiText.Get("FormatCells_Color"), fontColorBox),
                    normalFontBox,
                    CreateFormatCellsField(UiText.Get("FormatCells_Preview"), fontPreview),
                },
            });
        var fillTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabFill"),
            "FormatCellsFillTab",
            fillEditor.View);
        // --- Border tab rebuilt to mirror the Windows/Excel layout: three side-by-side
        // groups (Presets | Line | Border) above an "Individual border details" row. The
        // existing controls (preset buttons, style list, color picker, per-side toggles,
        // preview) are repositioned only; their wiring and automation ids are unchanged.

        // LEFT: Presets group — None/Outline/Inside stacked vertically.
        foreach (var presetButton in new[] { borderNoneButton, borderOutlineButton, borderInsideButton })
        {
            presetButton.HorizontalAlignment = AvaloniaHorizontalAlignment.Left;
            presetButton.Width = 110;
            presetButton.Height = 28;
            presetButton.MinHeight = 28;
            presetButton.MaxHeight = 28;
            presetButton.Background = Brush(221, 221, 221);
            presetButton.BorderBrush = Brush(112, 112, 112);
            presetButton.CornerRadius = new CornerRadius(0);
        }
        var borderPresetsGroup = CreateFormatCellsBorderGroup(
            UiText.Get("FormatCells_Presets"),
            new StackPanel
            {
                Spacing = 6,
                Children = { borderNoneButton, borderOutlineButton, borderInsideButton },
            });
        borderPresetsGroup.Margin = new Thickness(1, 0, 11, 0);

        // MIDDLE: Line group — scrollable line-sample list + color picker.
        Control CreateBorderPalette(FormatCellsColorPicker picker)
        {
            var palette = CellColorPalettePlanner.BuildDefaultSwatches();
            var wanted = new (byte R, byte G, byte B)[]
            {
                (0, 0, 0), (127, 127, 127), (255, 0, 0), (255, 192, 0),
                (0, 176, 80), (0, 176, 240), (0, 112, 192), (112, 48, 160),
            };
            var swatches = wanted
                .Select(rgb => palette.FirstOrDefault(s => s.Color is { R: var r, G: var g, B: var b } && r == rgb.R && g == rgb.G && b == rgb.B))
                .Where(swatch => swatch is not null)
                .Cast<CellColorSwatch>()
                .ToList();
            var row = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 1,
                Height = 20,
            };
            foreach (var swatch in swatches)
            {
                var swatchButton = new Button
                {
                    Width = 22,
                    Height = 18,
                    Padding = new Thickness(0),
                    Background = new SolidColorBrush(Color.FromRgb(swatch.Color.R, swatch.Color.G, swatch.Color.B)),
                    BorderBrush = Brushes.Gray,
                    BorderThickness = new Thickness(1),
                };
                AutomationProperties.SetName(swatchButton, swatch.Hex);
                swatchButton.Click += (_, _) => picker.SelectColor(swatch.Color);
                row.Children.Add(swatchButton);
            }
            var moreButton = new Button { Content = "...", Width = 22, Height = 18, Padding = new Thickness(0) };
            AutomationProperties.SetName(moreButton, UiText.Get("FormatCells_MoreBorderColors"));
            moreButton.Click += (_, _) => picker.Flyout?.ShowAt(moreButton);
            row.Children.Add(moreButton);
            return row;
        }

        var borderLineColorRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 6,
            Children = { borderColorTextBox, borderColorBox },
        };

        var borderLineGroup = CreateFormatCellsBorderGroup(
            UiText.Get("FormatCells_Line"),
            new StackPanel
            {
                Spacing = 0,
                Children =
                {
                    new TextBlock
                    {
                        Text = StripDisplayMnemonic(UiText.Get("FormatCells_Style")),
                        Margin = new Thickness(0, 0, 0, 2),
                    },
                    borderStyleBox,
                    new TextBlock
                    {
                        Text = StripDisplayMnemonic(UiText.Get("FormatCells_Color")),
                        Margin = new Thickness(0, 8, 0, 2),
                    },
                    borderLineColorRow,
                    new Border
                    {
                        Margin = new Thickness(0, 6, 0, 0),
                        Child = CreateBorderPalette(borderColorBox),
                    },
                    new Border
                    {
                        Height = 20,
                        Width = 178,
                        Background = Brushes.Black,
                        BorderBrush = Brushes.Gray,
                        BorderThickness = new Thickness(1),
                        Margin = new Thickness(0, 20, 0, 0),
                    },
                },
            });
        borderStyleBox.Width = 178;
        borderStyleBox.Height = 124;
        borderLineGroup.Margin = new Thickness(1, 0, 11, 0);

        // RIGHT: Border group — interactive diagram. Edge toggles surround a central
        // white "Text" preview box (Top above, Bottom below, Left/Right at the sides),
        // with the inside toggles as small buttons beneath.
        var textPreviewLabel = new TextBlock
        {
            Text = "Text",
            HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
            IsHitTestVisible = false,
        };
        var borderDiagramGrid = new AvaloniaGrid
        {
            Width = 244,
            Height = 164,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
            ColumnDefinitions = new ColumnDefinitions("50,144,50"),
            RowDefinitions = new RowDefinitions("32,100,32"),
        };
        // Top toggle: row 0, center column.
        borderDiagramGrid.Children.Add(borderTopToggle);
        AvaloniaGrid.SetRow(borderTopToggle, 0);
        AvaloniaGrid.SetColumn(borderTopToggle, 1);
        // Left toggle: row 1, column 0.
        borderDiagramGrid.Children.Add(borderLeftToggle);
        AvaloniaGrid.SetRow(borderLeftToggle, 1);
        AvaloniaGrid.SetColumn(borderLeftToggle, 0);
        // Center "Text" preview box.
        var borderPreviewHost = new AvaloniaGrid { Width = 144, Height = 100 };
        borderPreviewHost.Children.Add(borderPreview);
        borderPreviewHost.Children.Add(textPreviewLabel);
        borderPreview.Width = 144;
        borderPreview.Height = 100;
        borderDiagramGrid.Children.Add(borderPreviewHost);
        AvaloniaGrid.SetRow(borderPreviewHost, 1);
        AvaloniaGrid.SetColumn(borderPreviewHost, 1);
        // Right toggle: row 1, column 2.
        borderDiagramGrid.Children.Add(borderRightToggle);
        AvaloniaGrid.SetRow(borderRightToggle, 1);
        AvaloniaGrid.SetColumn(borderRightToggle, 2);
        // Bottom toggle: row 2, center column.
        borderDiagramGrid.Children.Add(borderBottomToggle);
        AvaloniaGrid.SetRow(borderBottomToggle, 2);
        AvaloniaGrid.SetColumn(borderBottomToggle, 1);
        foreach (var toggle in new[] { borderTopToggle, borderBottomToggle })
        {
            toggle.Width = 144;
            toggle.Height = 32;
            toggle.MinHeight = 32;
            toggle.MaxHeight = 32;
            toggle.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
            toggle.VerticalAlignment = AvaloniaVerticalAlignment.Stretch;
        }
        foreach (var toggle in new[] { borderLeftToggle, borderRightToggle })
        {
            toggle.Width = 50;
            toggle.Height = 100;
            toggle.MinWidth = 50;
            toggle.MaxWidth = 50;
            toggle.MinHeight = 100;
            toggle.MaxHeight = 100;
            toggle.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
            toggle.VerticalAlignment = AvaloniaVerticalAlignment.Stretch;
        }
        foreach (var toggle in new[] { borderTopToggle, borderBottomToggle, borderLeftToggle, borderRightToggle })
        {
            toggle.Background = Brush(221, 221, 221);
            toggle.BorderBrush = Brush(112, 112, 112);
            toggle.BorderThickness = new Thickness(1);
            toggle.CornerRadius = new CornerRadius(0);
        }

        var borderGroup = CreateFormatCellsBorderGroup(
            UiText.Get("FormatCells_Border"),
            new StackPanel
            {
                Spacing = 6,
                Children =
                {
                    borderDiagramGrid,
                },
            });

        // "Individual border details": four labeled rows (Top / Right / Bottom / Left), each with a
        // per-edge Style dropdown and a per-edge Color (R,G,B) picker — matching Excel's grid. The
        // legacy preset combo is preserved above the grid as "Preset" so the borderPresetBox wiring
        // (read in Accept as borderChoice) is unchanged.
        var borderDetailsGrid = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions("80,*,*"),
            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto,Auto"),
            ColumnSpacing = 0,
            RowSpacing = 0,
        };
        void AddDetailHeader(string text, int column)
        {
            var header = new TextBlock
            {
                Text = text,
                Margin = column == 1
                    ? new Thickness(0, 0, 8, 4)
                    : new Thickness(0, 0, 0, 4),
            };
            AvaloniaGrid.SetRow(header, 0);
            AvaloniaGrid.SetColumn(header, column);
            borderDetailsGrid.Children.Add(header);
        }
        AddDetailHeader(StripDisplayMnemonic(UiText.Get("FormatCells_Style")), 1);
        AddDetailHeader(StripDisplayMnemonic(UiText.Get("FormatCells_Color")), 2);
        void AddDetailRow(int row, string labelKey, ComboBox styleBox, TextBox colorTextBox, FormatCellsColorPicker colorPicker)
        {
            var label = new TextBlock
            {
                Text = StripDisplayMnemonic(UiText.Get(labelKey)) + ":",
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
                Margin = row < 4 ? new Thickness(0, 0, 8, 6) : new Thickness(0, 0, 8, 0),
            };
            styleBox.Width = double.NaN;
            styleBox.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
            styleBox.Margin = row < 4 ? new Thickness(2, 0, 8, 6) : new Thickness(2, 0, 8, 0);
            AvaloniaGrid.SetRow(label, row);
            AvaloniaGrid.SetColumn(label, 0);
            borderDetailsGrid.Children.Add(label);
            AvaloniaGrid.SetRow(styleBox, row);
            AvaloniaGrid.SetColumn(styleBox, 1);
            borderDetailsGrid.Children.Add(styleBox);
            var colorRow = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = row < 4 ? new Thickness(0, 0, 0, 6) : new Thickness(0),
                Children = { colorTextBox, colorPicker },
            };
            AvaloniaGrid.SetRow(colorRow, row);
            AvaloniaGrid.SetColumn(colorRow, 2);
            borderDetailsGrid.Children.Add(colorRow);
        }
        AddDetailRow(1, "FormatCells_Top", borderTopStyleBox, borderTopColorTextBox, borderTopColorBox);
        AddDetailRow(2, "FormatCells_Right", borderRightStyleBox, borderRightColorTextBox, borderRightColorBox);
        AddDetailRow(3, "FormatCells_Bottom", borderBottomStyleBox, borderBottomColorTextBox, borderBottomColorBox);
        AddDetailRow(4, "FormatCells_Left", borderLeftStyleBox, borderLeftColorTextBox, borderLeftColorBox);

        // The three visible buttons are the WPF preset surface. Keep the planner-backed selector
        // in the visual tree for existing automation and Accept() readback without a second row.
        borderPresetBox.IsVisible = false;

        var borderDetailsExpander = new Expander
        {
            Margin = new Thickness(4, 14, 0, 0),
            Header = StripDisplayMnemonic(UiText.Get("FormatCells_IndividualBorderDetails")),
            IsExpanded = true,
            Content = new Border
            {
                Margin = new Thickness(-3, 8, 0, 0),
                Child = borderDetailsGrid,
            },
        };
        AutomationProperties.SetAutomationId(borderDetailsExpander, "FormatCellsBorderDetailsExpander");
        AvaloniaCompactDialogChrome.ApplyWpfExpander(borderDetailsExpander);

        var borderTabLayout = new AvaloniaGrid
        {
            Margin = new Thickness(8),
            ColumnDefinitions = new ColumnDefinitions("122,190,*"),
            RowDefinitions = new RowDefinitions("Auto,*"),
            Children =
            {
                borderPresetsGroup,
                borderLineGroup,
                borderGroup,
                borderDetailsExpander,
            },
        };
        AvaloniaGrid.SetRowSpan(borderPresetsGroup, 2);
        AvaloniaGrid.SetColumn(borderLineGroup, 1);
        AvaloniaGrid.SetColumn(borderGroup, 2);
        AvaloniaGrid.SetRow(borderDetailsExpander, 1);
        AvaloniaGrid.SetColumn(borderDetailsExpander, 1);
        AvaloniaGrid.SetColumnSpan(borderDetailsExpander, 2);

        var borderTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabBorder"),
            "FormatCellsBorderTab",
            borderTabLayout);
        var protectionTab = CreateFormatCellsTab(
            UiText.Get("FormatCells_TabProtection"),
            "FormatCellsProtectionTab",
            new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    lockedBox,
                    hiddenBox,
                    protectionExplanationText,
                },
            });
        var tabStrip = new TabControl
        {
            SelectedIndex = Math.Clamp(initialTabIndex, 0, 5),
            Padding = new Thickness(0),
            Margin = new Thickness(0, 0, 0, 8),
            ItemsSource = new[]
            {
                numberTab,
                alignmentTab,
                fontTab,
                borderTab,
                fillTab,
                protectionTab,
            },
        };
        AutomationProperties.SetAutomationId(tabStrip, "FormatCellsTabStrip");
        AvaloniaCompactDialogChrome.ApplyClassicTabChrome(tabStrip);

        void ApplyFormatCellsDialogFrameForSelectedTab()
        {
            var targetHeight = tabStrip.SelectedIndex == 3
                ? formatCellsBorderDialogHeight
                : formatCellsDefaultDialogHeight;
            var targetSize = new Size(formatCellsDialogWidth, targetHeight);
            dialog.Width = formatCellsDialogWidth;
            dialog.MinHeight = targetHeight;
            dialog.Height = targetHeight;
            // Width/Height update layout constraints, but an already-open non-resizable X11
            // top-level does not reliably turn that change into a native resize request.
            // ClientSize is the Avalonia top-level API that drives IWindowImpl.Resize.
            dialog.ResizeClient(targetSize);
        }

        tabStrip.SelectionChanged += (_, _) => ApplyFormatCellsDialogFrameForSelectedTab();
        ApplyFormatCellsDialogFrameForSelectedTab();

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };

        var root = new AvaloniaGrid
        {
            Margin = new Thickness(10, 10, 24, 48),
            RowDefinitions = new RowDefinitions("*,Auto,Auto"),
            RowSpacing = 0,
            Children =
            {
                tabStrip,
                errorText,
                buttonRow,
            },
        };
        AvaloniaGrid.SetRow(tabStrip, 0);
        AvaloniaGrid.SetRow(errorText, 1);
        AvaloniaGrid.SetRow(buttonRow, 2);
        ConfigureDialogTabCycle(dialog, root);
        dialog.Content = root;
        dialog.Opened += (_, _) =>
        {
            Control target = tabStrip.SelectedIndex switch
            {
                1 => horizontalAlignmentBox,
                2 => fontNameBox,
                3 => borderStyleBox,
                4 => fillColorBox,
                5 => lockedBox,
                _ => numberCategoryList,
            };
            target.Focus();
        };
        if (launchSmokeProbe is not null)
        {
            dialog.Opened += (_, _) =>
            {
                RunLaunchSmokeDialogProbe(
                    dialog,
                    () => launchSmokeProbe(new FormatCellsDialogSmokeProbe(
                        dialog,
                        tabStrip,
                        numberTab,
                        alignmentTab,
                        fontTab,
                        fillTab,
                        borderTab,
                        protectionTab,
                        numberCategoryList,
                        numberFormatBox,
                        numberPreview,
                        okButton,
                        cancelButton)));
            };
        }

        await dialog.ShowDialog(this);
        return result;
    }

    private static TabItem CreateFormatCellsTab(string header, string automationId, Control content)
    {
        var tab = new TabItem
        {
            Header = StripDisplayMnemonic(header),
            Content = new ScrollViewer
            {
                Content = content,
                HorizontalContentAlignment = AvaloniaHorizontalAlignment.Stretch,
                VerticalContentAlignment = AvaloniaVerticalAlignment.Stretch,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            },
        };
        AutomationProperties.SetAutomationId(tab, automationId);
        return tab;
    }

    private static StackPanel CreateFormatCellsField(string label, Control control) =>
        new()
        {
            Spacing = 4,
            Children =
            {
                new TextBlock { Text = StripDisplayMnemonic(label) },
                control,
            },
        };

    private static ComboBox CreateFormatCellsComboBox<T>(
        string automationId,
        IReadOnlyList<FormatCellsNullableChoice<T>> choices,
        T currentValue)
        where T : struct
    {
        var selected = choices[0];
        foreach (var choice in choices)
        {
            if (choice.Value.HasValue &&
                EqualityComparer<T>.Default.Equals(choice.Value.Value, currentValue))
            {
                selected = choice;
                break;
            }
        }

        var comboBox = new ComboBox
        {
            ItemsSource = choices,
            SelectedItem = selected,
            MinWidth = 180,
        };
        AutomationProperties.SetAutomationId(comboBox, automationId);
        ApplyDialogComboBoxChrome(comboBox);
        return comboBox;
    }

    private static ToggleButton CreateFormatCellsBorderSideToggle(string label, string automationId)
    {
        var toggle = new ToggleButton
        {
            Content = label,
            MinWidth = 70,
            Height = 24,
            MinHeight = 24,
            MaxHeight = 24,
            Padding = new Thickness(4, 1),
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };
        AutomationProperties.SetName(toggle, label);
        AutomationProperties.SetAutomationId(toggle, automationId);
        return toggle;
    }

    private static double FormatCellsBorderPreviewThickness(BorderStyle style) =>
        style switch
        {
            BorderStyle.None => 0,
            BorderStyle.Medium => 2,
            BorderStyle.Thick => 3,
            BorderStyle.Double => 3,
            _ => 1,
        };

    private static CheckBox CreateFormatCellsCheckBox(string label, string automationId, bool isChecked)
    {
        var checkBox = new CheckBox
        {
            Content = label,
            IsChecked = isChecked,
        };
        AutomationProperties.SetAutomationId(checkBox, automationId);
        ApplyDialogCheckBoxChrome(checkBox);
        return checkBox;
    }

