        };
        AvaloniaCompactDialogChrome.ApplyButton(closeButton, dialogChrome, ScenarioManagerDialogLayout.CloseButtonWidth);
        AutomationProperties.SetName(closeButton, StripDisplayMnemonic(UiText.Get("ScenarioManager_Close")));
        AutomationProperties.SetAutomationId(closeButton, "ScenarioManagerCloseButton");
        AutomationProperties.SetHelpText(closeButton, "Close Scenario Manager.");

        string? CurrentScenarioName() =>
            scenarioList.SelectedItem is ScenarioManagerDialogScenarioItem item
                ? item.Choice.Name
                : selectedScenarioName;

        void RefreshSelectionDetails()
        {
            var selected = scenarioList.SelectedItem is ScenarioManagerDialogScenarioItem item
                ? item.Choice
                : null;
            selectedScenarioName = selected?.Name;
            showButton.IsEnabled = selected is not null;
            deleteButton.IsEnabled = selected is not null;
            editButton.IsEnabled = selected is not null;
            AvaloniaCompactDialogChrome.ApplyButton(showButton, dialogChrome, ScenarioManagerDialogLayout.ActionButtonWidth, isDefault: selected is not null);

            var selectedDialogItem = selected is null
                ? null
                : ScenarioManagerDialogPlanner.BuildItems(_session.Workbook)
                    .FirstOrDefault(item => string.Equals(item.Name, selected.Name, StringComparison.OrdinalIgnoreCase));
            var fields = ScenarioManagerDialogPlanner.ProjectSelectionFields(
                selectedDialogItem,
                nameBox.Text ?? "",
                CreateScenarioManagerDefaultName(plan.Scenarios));
            if (fields is not null)
            {
                nameBox.Text = fields.ScenarioName;
                changingCellsBox.Text = fields.ChangingCellsText;
                resultCellsBox.Text = fields.ResultCellsText;
                commentBox.Text = fields.CommentText;
                preventChangesBox.IsChecked = fields.Locked;
                hideBox.IsChecked = fields.Hidden;
            }
        }

        void RefreshDialogPlan(string? preferredScenarioName = null)
        {
            plan = ScenarioManagerPlanner.CreateDialogPlan(_session.Workbook, preferredScenarioName ?? selectedScenarioName);
            var items = plan.Scenarios
                .Select(choice => new ScenarioManagerDialogScenarioItem(choice))
                .ToArray();
            scenarioList.ItemsSource = items;
            ScenarioManagerDialogScenarioItem? selectedItem = null;
            foreach (var item in items)
            {
                if (item.Choice.IsSelected)
                {
                    selectedItem = item;
                    break;
                }
            }

            scenarioList.SelectedItem = selectedItem;
            changingCellsBox.Text = FormatRangeReference(_session.SelectedRange);
            summaryButton.IsEnabled = items.Length > 0;
            RefreshSelectionDetails();
        }

        SheetId? ResolveScenarioManagerSheetIdByName(string sheetName) =>
            _session.Workbook.Sheets.FirstOrDefault(
                sheet => string.Equals(sheet.Name, sheetName, StringComparison.OrdinalIgnoreCase))?.Id;

        Control ValidationTarget(ScenarioManagerDialogValidationField field) =>
            field switch
            {
                ScenarioManagerDialogValidationField.ScenarioName => nameBox,
                ScenarioManagerDialogValidationField.ChangingCells => changingCellsBox,
                ScenarioManagerDialogValidationField.ResultCells => resultCellsBox,
                _ => nameBox,
            };

        bool ValidateScenarioManagerFields(ScenarioManagerDialogAction action)
        {
            var failure = ScenarioManagerDialogPlanner.ValidateAcceptRequest(
                action,
                nameBox.Text,
                changingCellsBox.Text,
                resultCellsBox.Text,
                _session.ActiveSheet.Id,
                ResolveScenarioManagerSheetIdByName);
            if (failure is null)
                return true;

            var message = failure.Error switch
            {
                ScenarioManagerDialogValidationError.EnterScenarioName =>
                    UiText.Get("ScenarioManager_EnterScenarioName"),
                ScenarioManagerDialogValidationError.EnterValidChangingCellsReference =>
                    UiText.Get("ScenarioManager_EnterValidChangingCellsReference"),
                ScenarioManagerDialogValidationError.EnterValidResultCellsReference =>
                    UiText.Get("ScenarioManager_EnterValidResultCellsReference"),
                _ => UiText.Get("ScenarioManager_EnterScenarioDetails"),
            };
            errorText.Text = message;
            errorText.IsVisible = true;
            ShowEditIssue(message);
            var target = ValidationTarget(failure.Field);
            target.Focus();
            if (target is TextBox textBox)
                textBox.SelectAll();
            return false;
        }

        bool TryReadScenarioManagerRanges(
            string? text,
            out IReadOnlyList<GridRange> ranges)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                ranges = [_session.SelectedRange];
                return true;
            }

            return WorkbookRangeTextCodec.TryParseMany(
                _session.ActiveSheet.Id,
                text,
                ResolveScenarioManagerSheetIdByName,
                out ranges);
        }

        void ReportScenarioManagerFailure(WorkbookCellEditResult result)
        {
            var message = result.ErrorMessage ?? "Scenario Manager failed.";
            errorText.Text = message;
            errorText.IsVisible = true;
            ShowEditIssue(message);
        }

        bool ApplyScenarioManagerResult(WorkbookCellEditResult result, string status)
        {
            if (!result.Success)
            {
                ReportScenarioManagerFailure(result);
                return false;
            }

            errorText.Text = "";
            errorText.IsVisible = false;
            RefreshShell(status);
            return true;
        }

        void SaveCurrentValues(ScenarioManagerDialogAction action)
        {
            if (!ValidateScenarioManagerFields(action))
                return;

            if (!TryReadScenarioManagerRanges(changingCellsBox.Text, out var ranges))
            {
                var message = UiText.Get("ScenarioManager_EnterValidChangingCellsReference");
                errorText.Text = message;
                errorText.IsVisible = true;
                ShowEditIssue(message);
                changingCellsBox.Focus();
                changingCellsBox.SelectAll();
                return;
            }

            var changingCells = CaptureScenarioManagerChangingCells(ranges);
            var selectedDialogItem = ScenarioManagerDialogPlanner.BuildItems(_session.Workbook)
                .FirstOrDefault(item => string.Equals(
                    item.Name,
                    CurrentScenarioName(),
                    StringComparison.OrdinalIgnoreCase));
            var accepted = ScenarioManagerDialogPlanner.ProjectAcceptResult(
                action,
                selectedDialogItem,
                nameBox.Text ?? "",
                changingCellsBox.Text ?? "",
                resultCellsBox.Text ?? "",
                commentBox.Text ?? "",
                preventChangesBox.IsChecked == true,
                hideBox.IsChecked == true);
            var acceptedName = accepted.NewScenarioName.Trim();
            var request = new ScenarioManagerSaveRequest(
                acceptedName,
                changingCells,
                ReplaceScenarioName: accepted.Action == ScenarioManagerDialogAction.Edit
                    ? accepted.SelectedScenarioName
                    : null,
                Comment: accepted.CommentText,
                Hidden: accepted.Hidden,
                Locked: accepted.Locked);
            var savePlan = ScenarioManagerPlanner.CreateSavePlan(_session.Workbook, request);
            var result = _session.ExecuteScenarioManagerSavePlan(savePlan, request);
            if (!ApplyScenarioManagerResult(
                    result,
                    $"Saved scenario '{acceptedName}' ({changingCells.Count} {FormatCountLabel(changingCells.Count, "cell")})"))
            {
                var target = action == ScenarioManagerDialogAction.Edit
                    ? nameBox
                    : changingCellsBox;
                target.Focus();
                target.SelectAll();
                return;
            }

            RefreshDialogPlan(acceptedName);
            nameBox.Text = CreateScenarioManagerDefaultName(plan.Scenarios);
            commentBox.Text = "";
        }

        void ShowSelectedScenario()
        {
            var scenarioName = CurrentScenarioName();
            var showPlan = ScenarioManagerPlanner.CreateShowPlan(_session.Workbook, scenarioName);
            var result = _session.ExecuteScenarioManagerShowPlan(showPlan);
            if (!ApplyScenarioManagerResult(
                    result,
                    $"Showed scenario '{showPlan.SelectedScenario?.Name ?? scenarioName}'"))
                return;

            RefreshDialogPlan(showPlan.SelectedScenario?.Name ?? scenarioName);
        }

        void DeleteSelectedScenario()
        {
            var scenarioName = CurrentScenarioName();
            var deletePlan = ScenarioManagerPlanner.CreateDeletePlan(_session.Workbook, scenarioName);
            var deletedName = deletePlan.SelectedScenario?.Name ?? scenarioName ?? "scenario";
            var result = _session.ExecuteScenarioManagerDeletePlan(deletePlan);
            if (!ApplyScenarioManagerResult(result, $"Deleted scenario '{deletedName}'"))
                return;

            RefreshDialogPlan();
            nameBox.Text = CreateScenarioManagerDefaultName(plan.Scenarios);
        }

        void CreateSummaryReport()
        {
            if (!ValidateScenarioManagerFields(ScenarioManagerDialogAction.Report))
                return;

            IReadOnlyList<CellAddress> resultCells = [];
            if (!string.IsNullOrWhiteSpace(resultCellsBox.Text))
            {
                if (!WorkbookRangeTextCodec.TryParseMany(
                        _session.ActiveSheet.Id,
                        resultCellsBox.Text,
                        ResolveScenarioManagerSheetIdByName,
                        out var resultRanges))
                {
                    var message = UiText.Get("ScenarioManager_EnterValidResultCellsReference");
                    errorText.Text = message;
                    errorText.IsVisible = true;
                    ShowEditIssue(message);
                    resultCellsBox.Focus();
                    resultCellsBox.SelectAll();
                    return;
                }

                resultCells = resultRanges.SelectMany(range => range.AllCells()).Distinct().ToArray();
            }

            var summaryPlan = ScenarioManagerPlanner.CreateSummaryReportPlan(_session.Workbook, resultCells);
            var result = _session.ExecuteScenarioManagerSummaryReportPlan(summaryPlan);
            if (!ApplyScenarioManagerResult(
                    result,
                    $"Created Scenario Summary for {summaryPlan.Scenarios.Count} {FormatCountLabel(summaryPlan.Scenarios.Count, "scenario")}"))
                return;

            RefreshDialogPlan(selectedScenarioName);
        }

        scenarioList.SelectionChanged += (_, _) => RefreshSelectionDetails();
        saveButton.Click += (_, _) => SaveCurrentValues(ScenarioManagerDialogAction.Add);
        editButton.Click += (_, _) => SaveCurrentValues(ScenarioManagerDialogAction.Edit);
        showButton.Click += (_, _) => ShowSelectedScenario();
        deleteButton.Click += (_, _) => DeleteSelectedScenario();
        summaryButton.Click += (_, _) => CreateSummaryReport();
        closeButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var closeButtonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, ScenarioManagerDialogLayout.CloseRowTopMargin, 0, 0),
            Children =
            {
                closeButton,
            },
        };

        var actionColumn = new StackPanel
        {
            Spacing = 6,
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
            Margin = new Thickness(10, 20, 0, 0),
            Children =
            {
                saveButton,
                editButton,
                deleteButton,
                showButton,
                summaryButton,
            },
        };

        var scenariosHeader = new TextBlock
        {
            Text = StripDisplayMnemonic(UiText.Get("ScenarioManager_Scenarios")),
            Margin = new Thickness(0, 0, 0, ScenarioManagerDialogLayout.ScenarioListHeaderBottomMargin),
        };

        var fields = new AvaloniaGrid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto,Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions($"{ScenarioManagerDialogLayout.FieldLabelColumnWidth},*"),
        };

        AddScenarioManagerField(fields, 0, StripDisplayMnemonic(UiText.Get("ScenarioManager_ScenarioName")), nameBox);
        AddScenarioManagerField(fields, 1, StripDisplayMnemonic(UiText.Get("ScenarioManager_ChangingCells")), changingCellsBox);
        AddScenarioManagerField(fields, 2, StripDisplayMnemonic(UiText.Get("ScenarioManager_ResultCells")), resultCellsBox);
        AddScenarioManagerField(fields, 3, StripDisplayMnemonic(UiText.Get("ScenarioManager_Comment")), commentBox);
        AddScenarioManagerCheckBox(fields, 4, preventChangesBox);
        AddScenarioManagerCheckBox(fields, 5, hideBox);

        var addEditGroup = new GroupBox
        {
            Header = StripDisplayMnemonic(UiText.Get("ScenarioManager_AddEditScenario")),
            Margin = new Thickness(0, ScenarioManagerDialogLayout.GroupTopMargin, 0, 0),
            Padding = new Thickness(8),
            Content = fields,
        };
        AvaloniaCompactDialogChrome.ApplyGroupBox(addEditGroup, dialogChrome);

        var body = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        };
        var left = new StackPanel
        {
            Children = { scenariosHeader, scenarioList, addEditGroup },
        };
        body.Children.Add(left);
        body.Children.Add(actionColumn);
        AvaloniaGrid.SetColumn(actionColumn, 1);

        RefreshDialogPlan(selectedScenarioName);
        if (plan.SelectedScenario is null)
            nameBox.Text = CreateScenarioManagerDefaultName(plan.Scenarios);
        dialog.Content = new AvaloniaGrid
        {
            Margin = new Thickness(12),
            RowDefinitions = new RowDefinitions("*,Auto,Auto"),
            Children = { body, errorText, closeButtonRow },
        };
        AvaloniaGrid.SetRow(body, 0);
        AvaloniaGrid.SetRow(errorText, 1);
        AvaloniaGrid.SetRow(closeButtonRow, 2);
        dialog.Opened += (_, _) =>
        {
            if (plan.Scenarios.Count > 0)
                scenarioList.Focus();
            else
                nameBox.Focus();
        };

        await dialog.ShowDialog(this);
    }

    private IReadOnlyList<ScenarioCellValue> CaptureScenarioManagerChangingCells(
        IReadOnlyList<GridRange> ranges)
    {
        var values = new List<ScenarioCellValue>();
        var seen = new HashSet<CellAddress>();
        foreach (var range in ranges)
        {
            var sheet = _session.Workbook.GetSheet(range.Start.Sheet);
            if (sheet is null)
                continue;

            foreach (var address in range.AllCells())
            {
                if (seen.Add(address))
                    values.Add(new ScenarioCellValue(address, sheet.GetValue(address)));
            }
        }

        return values;
    }

    private static string FormatScenarioManagerSelectionSummary(GridRange range) =>
        $"Current selection: {FormatRangeReference(range)} ({range.CellCount} {FormatCountLabel(range.CellCount, "cell")})";

    private static string FormatScenarioManagerScenarioDetails(ScenarioManagerScenarioChoice? choice)
    {
        if (choice is null)
            return "No scenario selected.";

        var comment = string.IsNullOrWhiteSpace(choice.Comment)
            ? "No comment."
            : choice.Comment.Trim();
        var flags = new List<string>();
        if (choice.Hidden)
            flags.Add("hidden");
        if (choice.Locked)
            flags.Add("locked");

        var flagText = flags.Count == 0
            ? "Visible, editable."
            : string.Join(", ", flags.Select(flag => CultureInfo.CurrentCulture.TextInfo.ToTitleCase(flag))) + ".";
        return string.Join(
            Environment.NewLine,
            $"{choice.Name}: {choice.ChangingCellCount} {FormatCountLabel(choice.ChangingCellCount, "changing cell")}.",
            comment,
            flagText);
    }

    private static string CreateScenarioManagerDefaultName(IReadOnlyList<ScenarioManagerScenarioChoice> scenarios)
    {
        var existingNames = new HashSet<string>(
            scenarios.Select(scenario => scenario.Name),
            StringComparer.OrdinalIgnoreCase);
        var index = scenarios.Count + 1;
        while (true)
        {
            var candidate = $"Scenario {index}";
            if (!existingNames.Contains(candidate))
                return candidate;

            index++;
        }
    }

    private static string FormatCountLabel(long count, string singular) =>
        count == 1 ? singular : $"{singular}s";

    private static void AddScenarioManagerField(AvaloniaGrid grid, int row, string label, Control control)
    {
        var labelText = new TextBlock
        {
            Text = StripDisplayMnemonic(label),
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
            Margin = new Thickness(0, 0, 8, ScenarioManagerDialogLayout.FieldBottomMargin),
        };
        Grid.SetRow(labelText, row);
        Grid.SetColumn(labelText, 0);
        grid.Children.Add(labelText);

        control.MinWidth = 0;
        control.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
        control.Margin = new Thickness(0, 0, 0, ScenarioManagerDialogLayout.FieldBottomMargin);
        Grid.SetRow(control, row);
        Grid.SetColumn(control, 1);
        grid.Children.Add(control);
    }

    private static void AddScenarioManagerCheckBox(AvaloniaGrid grid, int row, CheckBox checkBox)
    {
        Grid.SetRow(checkBox, row);
        Grid.SetColumn(checkBox, 1);
        grid.Children.Add(checkBox);
    }

    private async Task ShowDataTableDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowDataTableInputDialogAsync();
        if (plan is null)
            return;

        var tableRange = FormatRangeReference(plan.TableRange);
        var result = _session.ExecuteDataTablePlan(plan);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? "Ready");
            ShowEditIssue(result.ErrorMessage ?? "Data Table failed.");
            return;
        }

        RefreshShell($"Created {FormatDataTableMode(plan)} Data Table for {tableRange}");
    }

    private async Task<DataTablePlan?> ShowDataTableInputDialogAsync()
    {
        DataTablePlan? result = null;
        var dialog = new Window
        {
            Title = "Data Table",
            Width = 360,
            Height = 210,
            MinWidth = 360,
            MinHeight = 210,
            MaxWidth = 360,
            MaxHeight = 210,
            CanResize = false,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontFamily = FormulaBarFontFamily,
            FontSize = 12,
        };
        AutomationProperties.SetAutomationId(dialog, "DataTableCompactDialog");

        var rowInputBox = new TextBox
        {
            MinWidth = 220,
        };
        ApplyDataToolsTextBoxChrome(rowInputBox);
        AutomationProperties.SetName(rowInputBox, "Row input cell");
        AutomationProperties.SetAutomationId(rowInputBox, "DataTableRowInputCellBox");
        AutomationProperties.SetHelpText(rowInputBox, "Cell whose value is substituted from the top row.");

        var columnInputBox = new TextBox
        {
            MinWidth = 220,
        };
        ApplyDataToolsTextBoxChrome(columnInputBox);
        AutomationProperties.SetName(columnInputBox, "Column input cell");
        AutomationProperties.SetAutomationId(columnInputBox, "DataTableColumnInputCellBox");
        AutomationProperties.SetHelpText(columnInputBox, "Cell whose value is substituted from the first column.");

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
            IsVisible = false,
        };
        AutomationProperties.SetName(errorText, "Data Table validation");
        AutomationProperties.SetAutomationId(errorText, "DataTableErrorText");
        AutomationProperties.SetHelpText(errorText, "Shows Data Table readiness and validation messages.");

        var okButton = new Button
        {
            Content = "OK",
            Width = 76,
            MinWidth = 76,
            IsDefault = true,
        };
        ApplyDataToolsButtonChrome(okButton, 76, isDefault: true);
        AutomationProperties.SetName(okButton, "OK");
        AutomationProperties.SetAutomationId(okButton, "DataTableOkButton");
        AutomationProperties.SetHelpText(okButton, "Create the Data Table.");

        var cancelButton = new Button
        {
            Content = "Cancel",
            Width = 76,
            MinWidth = 76,
            IsCancel = true,
        };
        ApplyDataToolsButtonChrome(cancelButton, 76);
        AutomationProperties.SetName(cancelButton, "Cancel");
        AutomationProperties.SetAutomationId(cancelButton, "DataTableCancelButton");
        AutomationProperties.SetHelpText(cancelButton, "Close Data Table without creating it.");

        DataTablePlanResult CreatePlan() =>
            DataTablePlanner.CreatePlan(
                _session.ActiveSheet,
                _session.SelectedRange,
                rowInputBox.Text,
                columnInputBox.Text,
                sheetName => _session.Workbook.GetSheet(sheetName)?.Id);

        void RefreshPlanStatus()
        {
            var planResult = CreatePlan();
            errorText.Text = planResult.IsReady
                ? string.Empty
                : FormatDataTablePlanError(planResult);
            errorText.IsVisible = !planResult.IsReady && !string.IsNullOrWhiteSpace(errorText.Text);
        }

        void Accept()
        {
            var planResult = CreatePlan();
            if (!planResult.IsReady || planResult.Plan is null)
            {
                errorText.Text = FormatDataTablePlanError(planResult);
                errorText.IsVisible = true;
                FocusDataTableErrorField(planResult.Status, rowInputBox, columnInputBox);
                return;
            }

            result = planResult.Plan;
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        rowInputBox.TextChanged += (_, _) => RefreshPlanStatus();
        columnInputBox.TextChanged += (_, _) => RefreshPlanStatus();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 10, 0, 0),
            Children =
            {
                okButton,
                cancelButton,
            },
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);

        dialog.Content = new DockPanel
        {
            Margin = new Thickness(16),
            Children =
            {
                buttonRow,
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        CreateDataTableField("Row input cell", rowInputBox),
                        CreateDataTableField("Column input cell", columnInputBox),
                        errorText,
                    },
                },
            },
        };
        dialog.Opened += (_, _) =>
        {
            rowInputBox.Focus();
            rowInputBox.SelectAll();
        };

        await dialog.ShowDialog(this);
        return result;
    }

    private static string FormatDataTableMode(DataTablePlan plan) =>
        plan.Mode == DataTablePlanMode.TwoVariable
            ? "two-variable"
            : plan.Orientation == DataTableInputOrientation.Row
                ? "one-variable row-input"
                : "one-variable column-input";

    private static string FormatDataTablePlanError(DataTablePlanResult result) =>
        string.IsNullOrWhiteSpace(result.InvalidText)
            ? result.StatusText
            : $"{result.StatusText} ({result.InvalidText})";

    private static void FocusDataTableErrorField(
        DataTablePlanStatus status,
        TextBox rowInputBox,
        TextBox columnInputBox)
    {
        var target = status switch
        {
            DataTablePlanStatus.InvalidRowInputCell or
            DataTablePlanStatus.RowInputCellInsideTableRange => rowInputBox,
            DataTablePlanStatus.InvalidColumnInputCell or
            DataTablePlanStatus.ColumnInputCellInsideTableRange or
            DataTablePlanStatus.InputCellsMustBeDifferent => columnInputBox,
            _ => rowInputBox
        };
        target.Focus();
        target.SelectAll();
    }

    private static StackPanel CreateDataTableField(string label, Control control) =>
        new()
        {
            Spacing = 4,
            Children =
            {
                new TextBlock { Text = StripDisplayMnemonic(label), FontSize = 12 },
                control,
            },
        };

    private async Task ShowForecastSheetDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowForecastSheetInputDialogAsync();
        if (plan is null)
            return;

        var sourceRange = FormatRangeReference(plan.SourceRange ?? _session.SelectedRange);
        var result = _session.ExecuteForecastSheetPlan(plan);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? "Ready");
            ShowEditIssue(result.ErrorMessage ?? "Forecast Sheet failed.");
            return;
        }

        RefreshShell($"Created Forecast Sheet from {sourceRange}");
    }

