        ApplyDialogComboBoxChrome(typeBox);

        var operatorBox = new ComboBox
        {
            ItemsSource = operatorChoices,
            MinWidth = 220,
        };
        AutomationProperties.SetName(operatorBox, "Data");
        AutomationProperties.SetAutomationId(operatorBox, "DataValidationOperatorBox");
        ApplyDialogComboBoxChrome(operatorBox);
        var operatorField = CreateDataValidationField(UiText.Get("DataValidation_Data"), operatorBox);

        var formula1Label = new TextBlock();
        var formula1Box = new TextBox
        {
            MinWidth = 240,
        };
        AutomationProperties.SetName(formula1Box, "Value");
        AutomationProperties.SetAutomationId(formula1Box, "DataValidationFormula1Box");
        ApplyDialogTextBoxChrome(formula1Box);
        var formula1Field = CreateDataValidationField(formula1Label, formula1Box);

        var formula2Label = new TextBlock();
        var formula2Box = new TextBox
        {
            MinWidth = 240,
        };
        AutomationProperties.SetName(formula2Box, "Maximum");
        AutomationProperties.SetAutomationId(formula2Box, "DataValidationFormula2Box");
        ApplyDialogTextBoxChrome(formula2Box);
        var formula2Field = CreateDataValidationField(formula2Label, formula2Box);

        var allowBlankBox = new CheckBox
        {
            Content = UiText.Get("DataValidation_IgnoreBlank"),
        };
        AutomationProperties.SetAutomationId(allowBlankBox, "DataValidationAllowBlankBox");
        ApplyDialogCheckBoxChrome(allowBlankBox);

        var sameSettingsBox = new CheckBox
        {
            Content = UiText.Get("DataValidation_ApplyTheseChangesToAllOtherCellsWithTheSameSettings"),
        };
        AutomationProperties.SetAutomationId(sameSettingsBox, "DataValidationSameSettingsBox");
        ApplyDialogCheckBoxChrome(sameSettingsBox);

        var showDropdownBox = new CheckBox
        {
            Content = UiText.Get("DataValidation_InCellDropdown"),
        };
        AutomationProperties.SetAutomationId(showDropdownBox, "DataValidationShowDropdownBox");
        ApplyDialogCheckBoxChrome(showDropdownBox);

        var showInputMessageBox = new CheckBox
        {
            Content = UiText.Get("DataValidation_ShowInputMessageWhenCellIsSelected"),
        };
        AutomationProperties.SetAutomationId(showInputMessageBox, "DataValidationShowInputMessageBox");
        ApplyDialogCheckBoxChrome(showInputMessageBox);

        var promptTitleBox = new TextBox
        {
            MinWidth = 240,
        };
        AutomationProperties.SetName(promptTitleBox, "Input title");
        AutomationProperties.SetAutomationId(promptTitleBox, "DataValidationPromptTitleBox");
        ApplyDialogTextBoxChrome(promptTitleBox);

        var promptMessageBox = new TextBox
        {
            AcceptsReturn = true,
            MinHeight = 54,
            MinWidth = 240,
            TextWrapping = TextWrapping.Wrap,
        };
        AutomationProperties.SetName(promptMessageBox, "Input message");
        AutomationProperties.SetAutomationId(promptMessageBox, "DataValidationPromptMessageBox");
        promptMessageBox.FontSize = 12;
        promptMessageBox.FontFamily = FormulaBarFontFamily;
        promptMessageBox.BorderBrush = Brush(130, 130, 130);
        promptMessageBox.BorderThickness = new Thickness(1);

        var showErrorMessageBox = new CheckBox
        {
            Content = UiText.Get("DataValidation_ShowErrorAlertAfterInvalidDataIsEntered"),
        };
        AutomationProperties.SetAutomationId(showErrorMessageBox, "DataValidationShowErrorMessageBox");
        ApplyDialogCheckBoxChrome(showErrorMessageBox);

        var alertStyleBox = new ComboBox
        {
            ItemsSource = alertStyleChoices,
            MinWidth = 220,
        };
        AutomationProperties.SetName(alertStyleBox, "Style");
        AutomationProperties.SetAutomationId(alertStyleBox, "DataValidationAlertStyleBox");
        ApplyDialogComboBoxChrome(alertStyleBox);

        var errorTitleBox = new TextBox
        {
            MinWidth = 240,
        };
        AutomationProperties.SetName(errorTitleBox, "Error title");
        AutomationProperties.SetAutomationId(errorTitleBox, "DataValidationErrorTitleBox");
        ApplyDialogTextBoxChrome(errorTitleBox);

        var errorMessageBox = new TextBox
        {
            AcceptsReturn = true,
            MinHeight = 54,
            MinWidth = 240,
            TextWrapping = TextWrapping.Wrap,
        };
        AutomationProperties.SetName(errorMessageBox, "Error message");
        AutomationProperties.SetAutomationId(errorMessageBox, "DataValidationErrorMessageBox");
        errorMessageBox.FontSize = 12;
        errorMessageBox.FontFamily = FormulaBarFontFamily;
        errorMessageBox.BorderBrush = Brush(130, 130, 130);
        errorMessageBox.BorderThickness = new Thickness(1);

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
        };
        AutomationProperties.SetAutomationId(errorText, "DataValidationErrorText");

        var applyButton = new Button
        {
            Content = UiText.Get("Common_Ok"),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(applyButton, "DataValidationApplyButton");
        ApplyDialogButtonChrome(applyButton, isDefault: true);

        var clearButton = new Button
        {
            Content = UiText.Get("DataValidation_ClearAll"),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(clearButton, "DataValidationClearButton");
        ApplyDialogButtonChrome(clearButton);

        var cancelButton = new Button
        {
            Content = UiText.Get("Common_Cancel"),
            IsCancel = true,
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(cancelButton, "DataValidationCancelButton");
        ApplyDialogButtonChrome(cancelButton);

        DvType SelectedType() =>
            typeBox.SelectedItem is DataValidationTypeChoice choice
                ? choice.Type
                : DvType.WholeNumber;

        DvOperator SelectedOperator() =>
            operatorBox.SelectedItem is DataValidationOperatorChoice choice
                ? choice.Operator
                : DataValidationDialogPlanner.DefaultOperatorForType(SelectedType());

        DvAlertStyle SelectedAlertStyle() =>
            alertStyleBox.SelectedItem is DataValidationAlertStyleChoice choice
                ? choice.AlertStyle
                : DvAlertStyle.Stop;

        void SelectOperator(DvOperator op)
        {
            operatorBox.SelectedItem = FindDataValidationOperatorChoice(operatorChoices, op);
        }

        void LoadRule(DataValidation rule)
        {
            typeBox.SelectedItem = FindDataValidationTypeChoice(typeChoices, rule.Type) ?? typeChoices[0];
            SelectOperator(rule.Operator);
            formula1Box.Text = rule.Formula1 ?? "";
            formula2Box.Text = rule.Formula2 ?? "";
            allowBlankBox.IsChecked = rule.AllowBlank;
            showDropdownBox.IsChecked = rule.ShowDropdown;
            showInputMessageBox.IsChecked = rule.ShowInputMessage;
            showErrorMessageBox.IsChecked = rule.ShowErrorMessage;
            alertStyleBox.SelectedItem = FindDataValidationAlertStyleChoice(alertStyleChoices, rule.AlertStyle);
            promptTitleBox.Text = rule.PromptTitle ?? "";
            promptMessageBox.Text = rule.PromptMessage ?? "";
            errorTitleBox.Text = rule.ErrorTitle ?? "";
            errorMessageBox.Text = rule.ErrorMessage ?? "";
        }

        void UpdateCriteriaVisibility()
        {
            var plan = DataValidationDialogPlanner.CreateVisibilityPlan(
                SelectedType(),
                SelectedOperator(),
                hasSelectionSource: false);

            formula1Label.Text = StripDisplayMnemonic(UiText.Get(DataValidationFormula1LabelKey(plan.Formula1Label)));
            AutomationProperties.SetName(formula1Box, formula1Label.Text);
            AutomationProperties.SetHelpText(formula1Box, DataValidationFormula1HelpText(plan.Formula1Label));
            formula2Label.Text = StripDisplayMnemonic(UiText.Get("DataValidation_Maximum"));
            operatorField.IsVisible = plan.ShowOperator;
            formula1Field.IsVisible = plan.ShowFormula1;
            formula2Field.IsVisible = plan.ShowFormula2;
            showDropdownBox.IsVisible = plan.ShowDropdown;
        }

        void RefreshMessageEditorStates()
        {
            var plan = new DvMessageVisibility(
                showInputMessageBox.IsChecked == true,
                showErrorMessageBox.IsChecked == true,
                SelectedAlertStyle());

            promptTitleBox.IsEnabled = plan.InputEditorsEnabled;
            promptMessageBox.IsEnabled = plan.InputEditorsEnabled;
            alertStyleBox.IsEnabled = plan.AlertStyleEnabled;
            errorTitleBox.IsEnabled = plan.ErrorEditorsEnabled;
            errorMessageBox.IsEnabled = plan.ErrorEditorsEnabled;
        }

        void Accept()
        {
            var type = SelectedType();
            var op = SelectedOperator();
            var validation = DataValidationDialogPlanner.ValidateCriteria(type, op, formula1Box.Text, formula2Box.Text);
            if (!validation.IsValid)
            {
                errorText.Text = DataValidationValidationErrorText(validation.FirstError);
                return;
            }

            var rule = DataValidationDialogPlanner.CreateRule(new DataValidationRuleEditorInput
            {
                Type = type,
                Operator = op,
                Formula1 = formula1Box.Text,
                Formula2 = formula2Box.Text,
                AllowBlank = allowBlankBox.IsChecked == true,
                ShowDropdown = showDropdownBox.IsChecked == true,
                ShowInputMessage = showInputMessageBox.IsChecked == true,
                ShowErrorMessage = showErrorMessageBox.IsChecked == true,
                AlertStyle = SelectedAlertStyle(),
                PromptTitle = promptTitleBox.Text,
                PromptMessage = promptMessageBox.Text,
                ErrorTitle = errorTitleBox.Text,
                ErrorMessage = errorMessageBox.Text
            });

            result = new DataValidationDialogResult(DataValidationDialogAction.Apply, rule, sameSettingsBox.IsChecked == true);
            dialog.Close();
        }

        applyButton.Click += (_, _) => Accept();
        clearButton.Click += (_, _) =>
        {
            result = new DataValidationDialogResult(DataValidationDialogAction.Clear, null);
            dialog.Close();
        };
        cancelButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        LoadRule(initialRule);
        UpdateCriteriaVisibility();
        RefreshMessageEditorStates();

        typeBox.SelectionChanged += (_, _) =>
        {
            var type = SelectedType();
            LoadRule(DataValidationDialogPlanner.CreateDefaultRule(type, _session.SelectedRange));
            UpdateCriteriaVisibility();
            RefreshMessageEditorStates();
        };
        operatorBox.SelectionChanged += (_, _) => UpdateCriteriaVisibility();
        showInputMessageBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RefreshMessageEditorStates();
        };
        showErrorMessageBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RefreshMessageEditorStates();
        };

        var criteriaHeader = new TextBlock
        {
            Text = UiText.Get("DataValidation_ValidationCriteria"),
            FontWeight = FontWeight.SemiBold,
        };

        var settingsContent = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                criteriaHeader,
                CreateDataValidationField(UiText.Get("DataValidation_Allow"), typeBox),
                operatorField,
                formula1Field,
                formula2Field,
                showDropdownBox,
                allowBlankBox,
                sameSettingsBox,
            },
        };

        var inputMessageContent = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                showInputMessageBox,
                CreateDataValidationField(UiText.Get("DataValidation_InputTitle"), promptTitleBox),
                CreateDataValidationField(UiText.Get("DataValidation_InputMessage2"), promptMessageBox),
            },
        };

        var errorAlertContent = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                showErrorMessageBox,
                CreateDataValidationField(UiText.Get("DataValidation_AlertStyle"), alertStyleBox),
                CreateDataValidationField(UiText.Get("DataValidation_ErrorTitle"), errorTitleBox),
                CreateDataValidationField(UiText.Get("DataValidation_ErrorMessage"), errorMessageBox),
            },
        };

        var settingsTab = CreateFormatCellsTab(
            UiText.Get("DataValidation_Settings"),
            "DataValidationSettingsTab",
            settingsContent);
        var inputMessageTab = CreateFormatCellsTab(
            UiText.Get("DataValidation_InputMessage"),
            "DataValidationInputMessageTab",
            inputMessageContent);
        var errorAlertTab = CreateFormatCellsTab(
            UiText.Get("DataValidation_ErrorAlert"),
            "DataValidationErrorAlertTab",
            errorAlertContent);

        var tabStrip = new TabControl
        {
            SelectedIndex = 0,
            Padding = new Thickness(0),
            ItemsSource = new[]
            {
                settingsTab,
                inputMessageTab,
                errorAlertTab,
            },
        };
        AutomationProperties.SetAutomationId(tabStrip, "DataValidationTabStrip");
        AvaloniaCompactDialogChrome.ApplyClassicTabChrome(tabStrip);

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 10, 0, 0),
            Children =
            {
                clearButton,
                applyButton,
                cancelButton,
            },
        };

        var root = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 10,
            Children =
            {
                summaryText,
                tabStrip,
                errorText,
                buttonRow,
            },
        };
        ConfigureDialogTabCycle(dialog, root);
        dialog.Content = root;
        dialog.Opened += (_, _) => typeBox.Focus();
        if (launchSmokeProbe is not null)
        {
            dialog.Opened += (_, _) =>
            {
                RunLaunchSmokeDialogProbe(
                    dialog,
                    () => launchSmokeProbe(new DataValidationDialogSmokeProbe(
                        dialog,
                        summaryText,
                        typeBox,
                        operatorBox,
                        formula1Box,
                        formula2Box,
                        allowBlankBox,
                        showDropdownBox,
                        showInputMessageBox,
                        promptTitleBox,
                        promptMessageBox,
                        showErrorMessageBox,
                        alertStyleBox,
                        errorTitleBox,
                        errorMessageBox,
                        applyButton,
                        clearButton,
                        cancelButton)));
            };
        }

        await dialog.ShowDialog(this);
        return result;
    }

