    private bool HasStatusBarAccessibleValue() =>
        !string.IsNullOrWhiteSpace(_statusText.Text) ||
        !string.IsNullOrWhiteSpace(_selectionStatsText.Text);

    private static bool HasToolbarMenuItem(MenuItem item, string expectedHeader) =>
        string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal);

    private bool HasNativeTopLevelMenu(NativeMenuTopLevelId id) =>
        HasNativeTopLevelMenu(_nativeMenu, id);

    private static bool HasNativeTopLevelMenu(NativeMenu? menu, NativeMenuTopLevelId id) =>
        HasNativeTopLevelMenu(menu, GetNativeTopLevelHeader(id));

    private static bool HasNativeTopLevelMenu(NativeMenu? menu, string expectedHeader) =>
        FindNativeTopLevelSubmenu(menu, expectedHeader) is not null;

    private static string GetNativeTopLevelMenuOrder(NativeMenu? menu) =>
        string.Join("|", menu?.Items.OfType<NativeMenuItem>()
            .Select(static item => item.Header?.ToString())
            .Where(static header => !string.IsNullOrWhiteSpace(header)) ?? []);

    private static NativeMenu? FindNativeTopLevelSubmenu(NativeMenu? menu, string expectedHeader) =>
        menu?.Items.OfType<NativeMenuItem>().FirstOrDefault(item =>
            string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal) &&
            item.Menu is not null)?.Menu;

    private static int CountNativeTopLevelMenuItems(NativeMenu? menu, NativeMenuTopLevelId id) =>
        CountNativeTopLevelMenuItems(menu, GetNativeTopLevelHeader(id));

    private static int CountNativeTopLevelMenuItems(NativeMenu? menu, string expectedHeader) =>
        FindNativeTopLevelSubmenu(menu, expectedHeader)?.Items.OfType<NativeMenuItem>()
            .Count(static item => !string.IsNullOrWhiteSpace(item.Header?.ToString())) ?? 0;

    private static string GetNativeTopLevelHeader(NativeMenuTopLevelId id) =>
        NativeMenuCatalog.TopLevelMenus.First(plan => plan.Id == id).Header;

    private static bool HasNativeMenuItem(NativeMenuItem item, string expectedHeader, bool requireGesture = true) =>
        string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal) &&
        (!requireGesture || item.Gesture is not null);

    private static bool HasNativeMenuItem(NativeMenuItem item, NativeMenuItemId id)
    {
        var plan = NativeMenuCatalog.GetMenuItem(id);
        return HasNativeMenuItem(item, GetNativeMenuItemHeader(plan), plan.RequiresGestureInSmoke);
    }

    private static bool HasNativeFileMenuItem(NativeMenuItem item, NativeFileMenuItemId id)
    {
        var plan = NativeMenuCatalog.GetFileMenuItem(id);
        return HasNativeMenuItem(item, GetNativeFileMenuItemHeader(plan), plan.RequiresGestureInSmoke);
    }

    private static bool HasEnabledNativeMenuItem(NativeMenuItem item, string expectedHeader, bool requireGesture = true) =>
        item.IsEnabled &&
        HasNativeMenuItem(item, expectedHeader, requireGesture);

    private static bool HasEnabledNativeFileMenuItem(NativeMenuItem item, NativeFileMenuItemId id) =>
        item.IsEnabled &&
        HasNativeFileMenuItem(item, id);

    private bool HasSheetTabButton(Func<Button, bool> predicate) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(predicate);

    private bool HasSheetTabContextMenuItem(string expectedHeader) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(button =>
                button.ContextMenu?.ItemsSource is IEnumerable<Control> items &&
                items
                    .OfType<MenuItem>()
                    .Any(item => string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal)));

    private bool HasSheetTabContextSubmenuItem(string parentHeader, string expectedHeader) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(button =>
                button.ContextMenu?.ItemsSource is IEnumerable<Control> items &&
                items
                    .OfType<MenuItem>()
                    .Where(item => string.Equals(item.Header?.ToString(), parentHeader, StringComparison.Ordinal))
                    .Any(item =>
                        item.ItemsSource is IEnumerable<MenuItem> submenuItems &&
                        submenuItems.Any(submenuItem => string.Equals(submenuItem.Header?.ToString(), expectedHeader, StringComparison.Ordinal))));

    private static bool HasNativeSubmenuItem(NativeMenu? menu, string expectedHeader) =>
        menu?
            .Items
            .OfType<NativeMenuItem>()
            .Any(item => string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal)) == true;

    private static bool HasNativeSubmenuItem(NativeMenu? menu, NativeMenuItemId id) =>
        HasNativeSubmenuItem(menu, GetNativeMenuItemHeader(id));

    private static int CountNativeColorPaletteSwatches(NativeMenu? menu) =>
        menu?
            .Items
            .OfType<NativeMenuItem>()
            .Count(item => item.Header?.ToString()?.StartsWith("#", StringComparison.Ordinal) == true) ?? 0;

    private static int CountNativeOpenRecentItems(NativeMenu? menu) =>
        menu?
            .Items
            .OfType<NativeMenuItem>()
            .Count(item => item.IsEnabled && !string.Equals(item.Header?.ToString(), "(No Recent Workbooks)", StringComparison.Ordinal)) ?? 0;

    private void RefreshNativeOpenRecentMenu(bool isIdle)
    {
        _openRecentMenuItem.Menu = CreateNativeOpenRecentMenu(isIdle);
    }

    private NativeMenu CreateNativeOpenRecentMenu(bool isIdle)
    {
        var menu = new NativeMenu();
        var plan = OpenRecentWorkbookMenuPlanner.Create(
            _recentFiles.Snapshot(),
            File.Exists,
            path => _session.TryResolveOpenTarget(path, out var target, out _) ? target!.Path : null);
        if (plan.ItemCount == 0)
        {
            menu.Items.Add(new NativeMenuItem
            {
                Header = "(No Recent Workbooks)",
                IsEnabled = false,
            });
            return menu;
        }

        foreach (var entry in plan.Items)
        {
            var path = entry.Path;
            var fileAccessIdentity = entry.FileAccessIdentity;
            var item = new NativeMenuItem
            {
                Header = entry.Header,
                IsEnabled = isIdle,
            };
            item.Click += async (_, _) => await OpenRecentWorkbookAsync(path, fileAccessIdentity);
            menu.Items.Add(item);
        }

        return menu;
    }

    private async Task OpenRecentWorkbookAsync(
        string path,
        WorkbookFileAccessIdentity? fileAccessIdentity = null)
    {
        if (!_session.TryResolveOpenTarget(path, fileAccessIdentity, out var target, out _) ||
            target is null)
        {
            _recentFiles.Remove(path);
            RefreshNativeOpenRecentMenu(!_isOpening && !_isSaving);
            ShowOpenIssue($"Recent workbook no longer exists: {path}");
            return;
        }

        using var fileAccess = await _workbookFileAccessService.BeginAccessAsync(
            StorageProvider,
            target.FileAccessIdentity);
        if (!File.Exists(target.Path))
        {
            _recentFiles.Remove(path);
            RefreshNativeOpenRecentMenu(!_isOpening && !_isSaving);
            ShowOpenIssue($"Recent workbook no longer exists: {path}");
            return;
        }

        await OpenWorkbookPathAsync(target.Path, target.FileAccessIdentity);
    }

    private void RecordStartupRecentWorkbook(StartupWorkbookLoadResult source)
    {
        if (!source.IsFallback && !string.IsNullOrWhiteSpace(source.SourcePath))
            RecordRecentWorkbook(source.SourcePath, source.SourceFileAccessIdentity);
    }

    private void RecordRecentWorkbook(string path, WorkbookFileAccessIdentity? fileAccessIdentity = null)
    {
        if (!_session.TryResolveOpenTarget(path, out var target, out _) ||
            target is null ||
            !File.Exists(target.Path))
            return;

        RecentFileRegistrationService.RegisterIfNeeded(
            _recentFiles,
            new RecentFileRegistrationRequest(
                target.Path,
                FileAccessIdentity: fileAccessIdentity ?? target.FileAccessIdentity));
        RefreshNativeOpenRecentMenu(!_isOpening && !_isSaving);
    }

    private static bool HasOnlyCommandModifier(KeyModifiers modifiers)
    {
        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return (modifiers & commandModifiers) != 0 &&
            (modifiers & ~commandModifiers) == 0;
    }

    private static bool HasCommandAndShiftModifiers(KeyModifiers modifiers)
    {
        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return modifiers.HasFlag(KeyModifiers.Shift) &&
            (modifiers & commandModifiers) != 0 &&
            (modifiers & ~(commandModifiers | KeyModifiers.Shift)) == 0;
    }

    private static bool IsShellFocusCycleKey(KeyEventArgs args) =>
        args.Key == Key.F6 &&
        (args.KeyModifiers == KeyModifiers.None || args.KeyModifiers == KeyModifiers.Shift);

    private static bool HasOnlyControlModifier(KeyModifiers modifiers) =>
        modifiers == KeyModifiers.Control;

    private static bool IsAutoSumShortcut(KeyEventArgs args) =>
        args.Key == Key.OemPlus && args.KeyModifiers == KeyModifiers.Alt;

    private static bool IsSelectVisibleCellsOnlyShortcut(KeyEventArgs args) =>
        args.Key == Key.Oem1 && args.KeyModifiers == KeyModifiers.Alt;

    private static bool IsOpenActiveDropdownShortcut(KeyEventArgs args) =>
        args.Key == Key.Down && args.KeyModifiers == KeyModifiers.Alt;

    private static bool TryGetNumberFormatShortcut(WorkbookShortcutRoute route, out NumberFormatShortcut shortcut)
    {
        shortcut = route switch
        {
            WorkbookShortcutRoute.NumberFormatGeneral => NumberFormatShortcut.General,
            WorkbookShortcutRoute.NumberFormatNumber => NumberFormatShortcut.Number,
            WorkbookShortcutRoute.NumberFormatTime => NumberFormatShortcut.Time,
            WorkbookShortcutRoute.NumberFormatDate => NumberFormatShortcut.Date,
            WorkbookShortcutRoute.NumberFormatCurrency => NumberFormatShortcut.Currency,
            WorkbookShortcutRoute.NumberFormatPercentage => NumberFormatShortcut.Percentage,
            WorkbookShortcutRoute.NumberFormatScientific => NumberFormatShortcut.Scientific,
            _ => default
        };

        return WorkbookKeyboardShortcutCatalog.IsNumberFormatRoute(route);
    }

    private static bool TryGetWorkbookShortcutRoute(
        Key key,
        KeyModifiers modifiers,
        out WorkbookShortcutRoute route)
    {
        route = default;
        return TryGetWorkbookShortcutKey(key, out var shortcutKey) &&
            TryGetWorkbookShortcutRoute(shortcutKey, ToWorkbookShortcutModifiers(modifiers), out route);
    }

    internal static bool TryResolveWorkbookShortcutRouteForTest(
        Key key,
        KeyModifiers modifiers,
        out WorkbookShortcutRoute route) =>
        TryGetWorkbookShortcutRoute(key, modifiers, out route);

    private static bool TryGetWorkbookShortcutRoute(
        WorkbookShortcutKey key,
        WorkbookShortcutModifiers modifiers,
        out WorkbookShortcutRoute route) =>
        WorkbookKeyboardShortcutCatalog.TryGetWindowsRoute(key, modifiers, out route) ||
        WorkbookKeyboardShortcutCatalog.TryGetNativeMenuRoute(key, modifiers, out route);

    private static bool TryGetWorkbookShortcutKey(Key key, out WorkbookShortcutKey shortcutKey)
    {
        shortcutKey = key switch
        {
            Key.A => WorkbookShortcutKey.A,
            Key.Back => WorkbookShortcutKey.Back,
            Key.B => WorkbookShortcutKey.B,
            Key.C => WorkbookShortcutKey.C,
            Key.D => WorkbookShortcutKey.D,
            Key.D1 or Key.NumPad1 => WorkbookShortcutKey.D1,
            Key.D2 or Key.NumPad2 => WorkbookShortcutKey.D2,
            Key.D3 or Key.NumPad3 => WorkbookShortcutKey.D3,
            Key.D4 or Key.NumPad4 => WorkbookShortcutKey.D4,
            Key.D5 or Key.NumPad5 => WorkbookShortcutKey.D5,
            Key.D6 or Key.NumPad6 => WorkbookShortcutKey.D6,
            Key.D7 => WorkbookShortcutKey.D7,
            Key.Delete => WorkbookShortcutKey.Delete,
            Key.E => WorkbookShortcutKey.E,
            Key.F => WorkbookShortcutKey.F,
            Key.F3 => WorkbookShortcutKey.F3,
            Key.F5 => WorkbookShortcutKey.F5,
            Key.F11 => WorkbookShortcutKey.F11,
            Key.F12 => WorkbookShortcutKey.F12,
            Key.G => WorkbookShortcutKey.G,
            Key.H => WorkbookShortcutKey.H,
            Key.I => WorkbookShortcutKey.I,
            Key.Insert => WorkbookShortcutKey.Insert,
            Key.N => WorkbookShortcutKey.N,
            Key.O => WorkbookShortcutKey.O,
            Key.Oem3 => WorkbookShortcutKey.Oem3,
            Key.OemMinus => WorkbookShortcutKey.OemMinus,
            Key.OemPlus or Key.Add => WorkbookShortcutKey.OemPlus,
            Key.PageDown => WorkbookShortcutKey.PageDown,
            Key.PageUp => WorkbookShortcutKey.PageUp,
            Key.P => WorkbookShortcutKey.P,
            Key.R => WorkbookShortcutKey.R,
            Key.S => WorkbookShortcutKey.S,
            Key.U => WorkbookShortcutKey.U,
            Key.V => WorkbookShortcutKey.V,
            Key.X => WorkbookShortcutKey.X,
            Key.Y => WorkbookShortcutKey.Y,
            Key.Z => WorkbookShortcutKey.Z,
            _ => default
        };

        return key is
            Key.A or
            Key.Back or
            Key.B or
            Key.C or
            Key.D or
            Key.D1 or
            Key.NumPad1 or
            Key.D2 or
            Key.NumPad2 or
            Key.D3 or
            Key.NumPad3 or
            Key.D4 or
            Key.NumPad4 or
            Key.D5 or
            Key.NumPad5 or
            Key.D6 or
            Key.NumPad6 or
            Key.D7 or
            Key.Delete or
            Key.E or
            Key.F or
            Key.F3 or
            Key.F5 or
            Key.F11 or
            Key.F12 or
            Key.G or
            Key.H or
            Key.I or
            Key.Insert or
            Key.N or
            Key.O or
            Key.Oem3 or
            Key.OemMinus or
            Key.OemPlus or
            Key.Add or
            Key.PageDown or
            Key.PageUp or
            Key.P or
            Key.R or
            Key.S or
            Key.U or
            Key.V or
            Key.X or
            Key.Y or
            Key.Z;
    }

    private static WorkbookShortcutModifiers ToWorkbookShortcutModifiers(KeyModifiers modifiers)
    {
        var result = WorkbookShortcutModifiers.None;
        if (modifiers.HasFlag(KeyModifiers.Control))
            result |= WorkbookShortcutModifiers.Control;
        if (modifiers.HasFlag(KeyModifiers.Meta))
            result |= WorkbookShortcutModifiers.Meta;
        if (modifiers.HasFlag(KeyModifiers.Alt))
            result |= WorkbookShortcutModifiers.Alt;
        if (modifiers.HasFlag(KeyModifiers.Shift))
            result |= WorkbookShortcutModifiers.Shift;
        return result;
    }

    /// <summary>
    /// The worksheet-cell context-menu shortcut (Menu key / Shift+F10) — the same key combo used for
    /// the sheet-tab context menu (<see cref="IsSheetTabContextMenuKey"/>), Excel's universal
    /// "open the context menu for whatever's focused" gesture applied to the active grid cell/range.
    /// </summary>
    private static bool IsWorksheetContextMenuKey(KeyEventArgs args) =>
        args.Key == Key.Apps ||
        args.Key == Key.F10 && args.KeyModifiers == KeyModifiers.Shift;

    /// <summary>
    /// True for Ctrl/Cmd(+Shift)+Arrow, Ctrl/Cmd+Home, and Ctrl/Cmd(+Shift)+End - the Excel
    /// used-range navigation/extend shortcuts that must still reach <see cref="NavigateActiveCell"/>
    /// even though the command modifier is held (mirrors the WPF host's
    /// <see cref="ExcelWorksheetNavigationPlanner.ShouldHandleWorksheetNavigationKey"/> gate).
    /// </summary>
    private static bool IsWorksheetNavigationKeyWithCommandModifier(KeyEventArgs args)
    {
        if (args.Key is not (Key.Up or Key.Down or Key.Left or Key.Right or Key.Home or Key.End))
            return false;

        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return (args.KeyModifiers & commandModifiers) != 0 &&
            (args.KeyModifiers & ~(commandModifiers | KeyModifiers.Shift)) == 0;
    }

    private async void MainWindow_KeyDown(object? sender, KeyEventArgs e) =>
        await MainWindow_KeyDownAsync(e);

    /// <summary>
    /// Test-only seam that drives the real worksheet-grid key-handling logic (F9/Ctrl+Space/
    /// Ctrl+Arrow/etc.) with a caller-supplied <see cref="KeyEventArgs"/>, awaiting completion so
    /// assertions can run against the resulting <see cref="Session"/> state. Not used by production
    /// code paths (the real <c>KeyDown</c> subscription goes through the <c>async void</c> wrapper
    /// above, as Avalonia event handlers require).
    /// </summary>
    internal Task RaiseKeyDownForTest(KeyEventArgs e) => MainWindow_KeyDownAsync(e);

    private async Task MainWindow_KeyDownAsync(KeyEventArgs e)
    {
        if (e.Key is Key.CapsLock or Key.NumLock)
        {
            UpdateKeyLockToggleState(e.Key);
            RefreshKeyLockIndicators();
        }

        if (e.KeyModifiers == KeyModifiers.None && TryRouteFormulaPointModeKey(e.Key))
        {
            e.Handled = true;
            return;
        }

        if (TryHandleWorkbookWindowSwitchShortcut(e))
            return;

        if (TryHandleLegacyDataFilterSequence(e))
            return;

        if (TryHandleRibbonKeyTips(e))
            return;

        if (_backstageOverlay.IsVisible && e.Key == Key.Escape)
        {
            HideBackstageOverlay();
            e.Handled = true;
            return;
        }

        if (TryHandleSlicerTimelinePaneKey(e))
            return;

        if (IsShellFocusCycleKey(e))
        {
            e.Handled = true;
            CycleShellFocus(reverse: e.KeyModifiers == KeyModifiers.Shift);
            return;
        }

        if (IsOpenActiveDropdownShortcut(e))
        {
            if (!_formulaBox.IsFocused)
            {
                e.Handled = OpenActiveDropdown();
            }

            return;
        }

        if (IsWorksheetContextMenuKey(e) && !IsTextEditingEventSource(e))
        {
            // Menu key / Shift+F10 over the worksheet grid: open the same cell context menu the
            // pointer-driven right-click path opens (OpenWorksheetCellContextMenu), anchored on the
            // active cell's Border so it appears where the user is actually looking — mirrors WPF's
            // KeyboardCommandShortcut.OpenContextMenu -> OpenKeyboardContextMenu.
            var anchor = (Control?)_activeCellBorder ?? _sheetGridHost;
            OpenWorksheetCellContextMenu(anchor);
            e.Handled = true;
            return;
        }

        if (await TryHandleAvaloniaHostShortcutAsync(e))
            return;

        if (e.Key == Key.Enter &&
            HasHyperlinkActivationModifier(e.KeyModifiers) &&
            !e.KeyModifiers.HasFlag(KeyModifiers.Shift) &&
            !e.KeyModifiers.HasFlag(KeyModifiers.Alt) &&
            !_formulaBox.IsFocused &&
            !IsTextEditingEventSource(e))
        {
            e.Handled = true;
            await OpenSelectedHyperlinkAsync();
            return;
        }

        if (IsAutoSumShortcut(e))
        {
            e.Handled = true;
            InsertAutoSumFormula("SUM");
            return;
        }

        if (IsSelectVisibleCellsOnlyShortcut(e))
        {
            e.Handled = true;
            SelectGoToSpecial(GoToSpecialKind.VisibleCellsOnly);
            return;
        }

        if (TryHandleRowColumnVisibilityShortcut(e))
            return;

        if (e.Key == Key.F4 && e.KeyModifiers == KeyModifiers.None &&
            !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            e.Handled = true;
            ExecuteRepeatLastAction();
            return;
        }

        if (e.Key == Key.F9 && !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            if (e.KeyModifiers == KeyModifiers.None)
            {
                e.Handled = true;
                CalculateNow();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                CalculateActiveSheet();
                return;
            }

            if (e.KeyModifiers == (KeyModifiers.Control | KeyModifiers.Alt))
            {
                e.Handled = true;
                CalculateNow();
                return;
            }
        }

        if (e.Key == Key.Space && !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            if (e.KeyModifiers == (KeyModifiers.Control | KeyModifiers.Shift))
            {
                e.Handled = true;
                SelectAllCells();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Control)
            {
                e.Handled = true;
                SelectWholeColumnsFromSelection();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                SelectWholeRowsFromSelection();
                return;
            }
        }

        if ((!e.KeyModifiers.HasFlag(KeyModifiers.Control) &&
                !e.KeyModifiers.HasFlag(KeyModifiers.Meta)) ||
            IsWorksheetNavigationKeyWithCommandModifier(e))
        {
            if (e.Key == Key.F5)
            {
                e.Handled = true;
                await ShowGoToDialogAsync();
                return;
            }

            if (_formulaBox.IsFocused)
                return;

            if (IsTextEditingEventSource(e))
                return;

            if (e.Key == Key.F11 && e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                AddNewSheet();
                return;
            }

            if (e.Key == Key.F3 && e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                InsertFunction();
                return;
            }

            if (e.Key == Key.F1)
            {
                e.Handled = true;
                await OpenExternalHelpLinkAsync(AppHelpInfo.HelpUrl, "Help Online");
                return;
            }

            if (e.Key == Key.Delete)
            {
                if (IsTextEditingEventSource(e))
                    return;

                e.Handled = true;
                ClearSelectedRangeContents();
                return;
            }

            if (e.Key == Key.Escape && _session.IsFormatPainterActive)
            {
                e.Handled = true;
                CancelFormatPainter();
                return;
            }

            if (e.Key == Key.Escape && _borderDrawModeActive)
            {
                e.Handled = true;
                CancelBorderDrawMode();
                return;
            }

            // R75-render-selection-marquee-4-2: Escape cancels an active Copy/Cut marching-ants
            // marquee, mirroring the WPF host's ClearClipboardVisualState call on Escape
            // (MainWindow.Editing.cs).
            if (e.Key == Key.Escape &&
                (_clipboardMarqueeRange is not null || _internalObjectClipboard is not null))
            {
                e.Handled = true;
                SetClipboardMarquee(null, isCut: false);
                _internalObjectClipboard = null;
                RefreshShell("Ready");
                return;
            }

            NavigateActiveCell(e);
            return;
        }

        if (_formulaBox.IsFocused &&
            e.Key is Key.Z or Key.Y or Key.X or Key.C or Key.V or Key.A or Key.B or Key.D or Key.E or Key.I or Key.R or Key.U or Key.D4 or Key.NumPad4 or Key.D5 or Key.NumPad5)
        {
            return;
        }

        if (e.Key == Key.G && e.KeyModifiers == KeyModifiers.Meta)
        {
            e.Handled = true;
            FindNext();
        }
        else if (e.Key == Key.K && HasOnlyControlModifier(e.KeyModifiers))
        {
            e.Handled = true;
            await ShowInsertHyperlinkDialogAsync();
        }
        else if (e.Key == Key.V && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            // Ctrl+Shift+V ("Paste Values") — Excel/WPF paste the literal computed value only, with
            // no formula and no source formatting. Must be checked before the bare Key.V fallback
            // below, which performs a full (formula + formatting) paste.
            e.Handled = true;
            await PasteSpecialClipboardTextAsync(PasteCellsMode.Values, default, "Values");
        }
        else if (e.Key == Key.A && HasOnlyCommandModifier(e.KeyModifiers))
        {
            e.Handled = true;
            var before = _session.SelectedRange;
            SelectCurrentRegionOrAll();
            RecordLaunchSmokeLiveSelectAllCommandKey(before, _session.SelectedRange);
        }
        else if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Shift))
        {
            e.Handled = true;
            await SaveWorkbookAsAsync();
        }
        else if (e.Key == Key.W && HasOnlyCommandModifier(e.KeyModifiers))
        {
            e.Handled = true;
            await CloseWorkbookAsync();
        }
        else if (e.Key == Key.P && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            e.Handled = true;
            await ShowPrintPreviewDialogAsync();
        }
        else if (e.Key == Key.O && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            // Ctrl+Shift+O ("Select Cells with Comments") — must be checked before the bare Key.O
            // fallback below, which opens the file-Open dialog.
            e.Handled = true;
            SelectGoToSpecial(GoToSpecialKind.Comments);
        }
        else if (await TryHandleWorkbookShortcutRouteAsync(e))
        {
        }
    }

    private async Task<bool> TryHandleWorkbookShortcutRouteAsync(KeyEventArgs e)
    {
        var effectiveKey = GetEffectiveWorkbookShortcutKey(e);
        if (effectiveKey != e.Key)
        {
            var normalizedArgs = new KeyEventArgs
            {
                Key = effectiveKey,
                PhysicalKey = e.PhysicalKey,
                KeyModifiers = e.KeyModifiers,
            };
            var handled = await TryHandleWorkbookShortcutRouteAsync(normalizedArgs);
            e.Handled = normalizedArgs.Handled;
            return handled;
        }

        if (!TryGetWorkbookShortcutRoute(e.Key, e.KeyModifiers, out var route))
            return false;

        switch (route)
        {
            case WorkbookShortcutRoute.NewWorkbook:
                e.Handled = true;
                await CreateNewWorkbookAsync();
                return true;
            case WorkbookShortcutRoute.OpenWorkbook:
                e.Handled = true;
                await OpenWorkbookAsync();
                return true;
            case WorkbookShortcutRoute.SaveWorkbook:
                e.Handled = true;
                await SaveCurrentWorkbookAsync();
                return true;
            case WorkbookShortcutRoute.PrintWorkbook:
                e.Handled = true;
                ShowBackstagePrintPane();
                return true;
            case WorkbookShortcutRoute.Copy:
                e.Handled = true;
                await CopySelectedRangeToClipboardAsync();
                return true;
            case WorkbookShortcutRoute.Cut:
                e.Handled = true;
                await CutSelectedRangeToClipboardAsync();
                return true;
            case WorkbookShortcutRoute.Paste:
                e.Handled = true;
                await PasteClipboardTextAsync();
                return true;
            case WorkbookShortcutRoute.PasteSpecial:
                e.Handled = true;
                await ShowPasteSpecialDialogAsync();
                return true;
            case WorkbookShortcutRoute.Undo:
                e.Handled = true;
                UndoLastEdit();
                return true;
            case WorkbookShortcutRoute.Redo:
                e.Handled = true;
                RedoLastEdit();
                return true;
            case WorkbookShortcutRoute.ToggleBold:
                e.Handled = true;
                ToggleSelectedRangeBold(trackLaunchSmokeLiveCommandKey: e.Key == Key.B);
                return true;
            case WorkbookShortcutRoute.ToggleItalic:
                e.Handled = true;
                ToggleSelectedRangeItalic(trackLaunchSmokeLiveCommandKey: e.Key == Key.I);
                return true;
            case WorkbookShortcutRoute.ToggleUnderline:
                e.Handled = true;
                ToggleSelectedRangeUnderline(trackLaunchSmokeLiveCommandKey: e.Key == Key.U);
                return true;
            case WorkbookShortcutRoute.ToggleStrikethrough:
                e.Handled = true;
                ToggleSelectedRangeStrikethrough();
                return true;
            case WorkbookShortcutRoute.FillDown:
                e.Handled = true;
                FillSelectedRange(FillCellsDirection.Down);
                return true;
            case WorkbookShortcutRoute.FillRight:
                e.Handled = true;
                FillSelectedRange(FillCellsDirection.Right);
                return true;
            case WorkbookShortcutRoute.FlashFill:
                e.Handled = true;
                FlashFillSelectedRange();
                return true;
            case WorkbookShortcutRoute.ToggleShowFormulas:
                e.Handled = true;
                ToggleShowFormulas();
                return true;
            case WorkbookShortcutRoute.ActivatePreviousSheet:
                e.Handled = SelectAdjacentVisibleSheetFromKeyboard(direction: -1, selectRange: false);
                return true;
            case WorkbookShortcutRoute.ActivateNextSheet:
                e.Handled = SelectAdjacentVisibleSheetFromKeyboard(direction: 1, selectRange: false);
                return true;
            case WorkbookShortcutRoute.SelectPreviousSheetGroup:
                e.Handled = SelectAdjacentVisibleSheetFromKeyboard(direction: -1, selectRange: true);
                return true;
            case WorkbookShortcutRoute.SelectNextSheetGroup:
                e.Handled = SelectAdjacentVisibleSheetFromKeyboard(direction: 1, selectRange: true);
                return true;
            case WorkbookShortcutRoute.OpenFormatCells:
                e.Handled = true;
                await ShowFormatCellsDialogAsync();
                return true;
            case WorkbookShortcutRoute.Find:
                e.Handled = true;
                await ShowFindDialogAsync();
                return true;
            case WorkbookShortcutRoute.Replace:
                e.Handled = true;
                await ShowReplaceDialogAsync();
                return true;
            case WorkbookShortcutRoute.GoTo:
                e.Handled = true;
                await ShowGoToDialogAsync();
                return true;
            case WorkbookShortcutRoute.InsertFunction:
                e.Handled = true;
                InsertFunction();
                return true;
            case WorkbookShortcutRoute.AutoSum:
                e.Handled = true;
                InsertAutoSumFormula("SUM");
                return true;
            case WorkbookShortcutRoute.WorkbookStatistics:
                e.Handled = true;
                await ShowWorkbookStatisticsDialogAsync();
                return true;
            case WorkbookShortcutRoute.InsertWorksheet:
                e.Handled = true;
                AddNewSheet();
                return true;
            case WorkbookShortcutRoute.ApplyOutlineBorder:
                e.Handled = true;
                ApplySelectedRangeBorderPreset(CellBorderPreset.Outside);
                return true;
            case WorkbookShortcutRoute.ClearOutlineBorder:
                e.Handled = true;
                ApplySelectedRangeBorderPreset(CellBorderPreset.NoBorder);
                return true;
        }

        if (TryGetNumberFormatShortcut(route, out var numberFormatShortcut))
        {
            e.Handled = true;
            ApplySelectedRangeNumberFormatShortcut(numberFormatShortcut);
            return true;
        }

        return false;
    }

    private bool IsTextEditingEventSource(KeyEventArgs args) =>
        _formulaBox.IsFocused ||
        _inlineCellEditor?.IsFocused == true ||
        _textBoxInlineEditor?.IsFocused == true ||
        args.Source is TextBox ||
        args.Source is TextPresenter;

    private bool OpenActiveDataValidationDropdown()
    {
        if (_isOpening || _isSaving)
            return true;

        if (!TryCommitPendingFormulaEdit())
            return true;

        RefreshShell("Ready");
        if (_activeDataValidationDropdown is null)
            return false;

        _activeDataValidationDropdown.Focus();
        _activeDataValidationDropdown.IsDropDownOpen = true;
        return true;
    }

    private bool OpenActiveDropdown() =>
        OpenActiveNameBoxDropdown() ||
        OpenActiveDataValidationDropdown() ||
        OpenActiveAutoFilterDropdown() ||
        OpenTextEntryPickListDropdown();

    private bool OpenActiveNameBoxDropdown()
    {
        if (!_cellAddressText.IsFocused)
            return false;

        ShowCellAddressAutocompletePopup();
        return true;
    }

    private bool OpenTextEntryPickListDropdown()
    {
        var items = DataValidationDropdownPlanner.GetTextEntryPickListItems(
            _session.ActiveSheet,
            _session.ActiveCell);
        if (items.Count == 0 ||
            _cellAffordanceOverlay is not { } overlay ||
            !TryGetDisplayedCellBounds(
                _session.Viewport,
                _session.ActiveCell,
                _session.IsShowingHeadings,
                GetActiveZoomFactor(),
                out var left,
                out var top,
                out var width,
                out var height))
        {
            return false;
        }

        var btnWidth = Math.Max(
            DataValidationDropdownPlanner.MinimumWidth,
            DataValidationAffordancePlanner.ArrowButtonWidth * GetActiveZoomFactor());
        var btnHeight = Math.Max(DataValidationDropdownPlanner.MinimumHeight, height);
        var plan = new DataValidationDropdownPlan(
            items,
            SelectedItem: null,
            new DataValidationDropdownBounds(left + width - btnWidth, top, btnWidth, btnHeight));
        var dropdown = CreateDataValidationDropdown(plan, btnWidth, btnHeight);
        Canvas.SetLeft(dropdown, plan.Bounds.Left);
        Canvas.SetTop(dropdown, plan.Bounds.Top);
        overlay.Children.Add(dropdown);
        _activeDataValidationDropdown = dropdown;
        dropdown.Focus();
        dropdown.IsDropDownOpen = true;
        return true;
    }

    private void DataValidationDropdown_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (sender is not ComboBox { SelectedItem: string selected })
            return;

        CommitDataValidationDropdownSelection(selected);
    }

    private void CommitDataValidationDropdownSelection(string selected)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var address = _session.ActiveCell;
        _session.BeginFormulaEdit(address);
        var result = _session.CommitCellText(selected, UseR1C1ReferenceStyle);
        if (!result.Success)
        {
            _session.CancelFormulaEdit();
            _formulaBoxEditOriginalText = null;
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_DataValidationDropdownFailed"));
            return;
        }

        RefreshShell($"Picked {selected} for {FormatCellReference(address)}");
    }

    private void CycleShellFocus(bool reverse)
    {
        var current = GetCurrentShellFocusTarget();
        for (var attempt = 0; attempt < Enum.GetValues<ShellFocusTarget>().Length; attempt++)
        {
            current = ShellFocusCyclePlanner.GetNextAvailable(current, reverse, IsShellFocusTargetAvailable);
            if (FocusShellRegion(current))
                return;
        }
    }

    private bool IsShellFocusTargetAvailable(ShellFocusTarget target) =>
        target != ShellFocusTarget.TaskPane ||
        _pivotFieldPaneHost.IsVisible ||
        _slicerTimelinePaneHost.IsVisible;

    private ShellFocusTarget GetCurrentShellFocusTarget()
    {
        if (_formulaBox.IsFocused)
            return ShellFocusTarget.FormulaBar;

        if (IsAnySheetTabFocused())
            return ShellFocusTarget.SheetTabs;

        if (_zoomText.IsFocused)
            return ShellFocusTarget.StatusBar;

        if (IsPivotFieldPaneFocused())
            return ShellFocusTarget.TaskPane;

        if (IsSlicerTimelinePaneFocused())
            return ShellFocusTarget.TaskPane;

        if (IsAnyToolbarControlFocused())
            return ShellFocusTarget.Ribbon;

        return ShellFocusTarget.Worksheet;
    }

    private bool FocusShellRegion(ShellFocusTarget target) =>
        target switch
        {
            ShellFocusTarget.Ribbon => FocusFirstEnabledToolbarControl(),
            ShellFocusTarget.FormulaBar => FocusControl(_formulaBox),
            ShellFocusTarget.SheetTabs => FocusActiveSheetTab(),
            ShellFocusTarget.TaskPane => FocusVisibleTaskPane(),
            ShellFocusTarget.StatusBar => FocusControl(_zoomText),
            _ => FocusControl(_sheetGridHost)
        };

    private bool FocusVisibleTaskPane() =>
        (_pivotFieldPaneSearchBox is { } searchBox && FocusControl(searchBox)) ||
        FocusControl(_pivotFieldPaneHost) ||
        FocusSlicerTimelinePane();

    private bool IsPivotFieldPaneFocused() =>
        _pivotFieldPaneHost.IsFocused ||
        _pivotFieldPaneSearchBox?.IsFocused == true ||
        _pivotDropZones.Any(zone => zone.Bucket.IsFocused);

    private bool FocusFirstEnabledToolbarControl()
    {
        foreach (var control in GetToolbarFocusTargets())
        {
            if (FocusControl(control))
                return true;
        }

        return false;
    }

